documentText =
  T.intercalate
    "\n"
    [ "# diagnostic のコード",
      "",
      "この文書は、Golem が出す diagnostic のコード（`G01001` など）を一つずつ説明する。",
      "diagnostic は、コードと一行のメッセージだけを出す。",
      "コードが何を表し、どう直せばよいかを、ここで引けるようにする。",
      "`golem explain <コード>` は、この文書の節をそのまま表示する（[golem-cli ADR 0005](golem-cli/adr/0005-explain-diagnostic-codes.md)）。",
      "LSP の diagnostic の `codeDescription` は、GitHub の上のこの文書の節を指す。",
      "",
      "プラグインが出す diagnostic のコードは、この文書の対象外である。",
      "プラグインのコードは `<プラグインの宣言の名前>/<英小文字で始まり、英小文字、数字、- だけからなる列>` の形で（[docs/adr/0108](adr/0108-plugin-diagnostic-codes-and-spans.md)、[docs/adr/0139](adr/0139-plugin-diagnostic-code-starts-with-letter.md)）、後ろの部分はプラグインが決めるので、プラグインの文書を参照する。",
      "",
      "コードは、以前は `G` と 4 桁の数字だった（[docs/adr/0061](adr/0061-five-digit-diagnostic-codes.md)）。",
      "4 桁のコードは廃止したので、`golem explain` も `silence-notices` と `silence-info` も受け付けない。",
      "監査の記録（`docs/audits/`）など、コミットの後に書き換えない文書には、4 桁のコードが残っている。",
      "4 桁のコードは、段階の 2 桁と番号の 2 桁のあいだに `0` を一つ足して読み替える（`G0258` は `G02058`、`G0910` は `G09010`）。",
      "",
      "## 節の形",
      "",
      "各コードの節は、`## G01001` の見出しから始まる。",
      "見出しにはコードだけを書くので、節の URL は `diagnostics.md#g01001` になる。",
      "節は次のものを、この順に持つ。",
      "",
      "- **題**：見出しの次の段落。一行で書き、`golem explain` の一覧に使う。",
      "- **重大度**：`- 重大度:` の行。エラー、警告、dev では警告、prod ではエラー、お知らせ、情報、プリフライトの設定による、のいずれかを書く。プリフライトの設定によるコードには、括弧で組み込みの設定 `print` の既定を添える（[golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)）。エラーが一つでもあれば、ビルドは失敗し、終了コードは 1 になる。お知らせは終了コードに影響せず、`manifest.toml` の `[diagnostics]` の `silence-notices` と、コマンドの `--no-notices` で抑制できる（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。情報は、コマンドに `--verbose`（`-v`）を付けたときだけ出す。終了コードと出力に影響せず、`[diagnostics]` の `silence-info` で止められ、`silence-notices` と `--no-notices` の対象ではない（[docs/adr/0104](adr/0104-info-severity.md)）。",
      "- **状態**：`- 状態:` の行。使用中か廃止を書く。",
      "- **意味**：`### 意味` の小見出し。いつ出るかを書き、メッセージの文言、段階とモジュール、ADR を添える。メッセージの引数を埋める部分は `<名前>` のように書く。番号を書いた ADR が見つからないコードは「ADR なし」とし、番号に触れているだけの ADR があれば併記する。",
      "- **主な原因**：`### 主な原因` の小見出し。よくある原因を書く。廃止したコードでは省ける。",
      "- **直し方**：`### 直し方` の小見出し。廃止したコードでは、代わりの書き方を書く。",
      "",
      "節はコードの昇順に並べる。",
      "golem をビルドするときにこの文書を埋め込み、節の形を検査する。",
      "形の崩れた文書では、golem をビルドできない。",
      "",
      "ソースで使っているコードがすべて状態「使用中」で載っていること、状態「使用中」のコードがすべてソースで使われていること、重大度が `profileDependentCodes` と `noticeCodes` と `infoCodes` と `preflightCodes` に合うことは、golem-driver のテスト（`modules/golem-driver/test/Main.hs`）が確かめる。",
      "新しいコードを足すときは、同じ変更でこの文書に節を足す。",
      "使わなくなったコードは、節を消さずに状態を「廃止」にする。",
      "",
      "## 番号の区分",
      "",
      "コードは `G` と 5 桁の数字からなる。",
      "上 2 桁が diagnostic を出す段階を表し（[golem-syntax ADR 0001](golem-syntax/adr/0001-source-spans-and-diagnostics.md)）、下 3 桁がその段階の中の番号である（[docs/adr/0061](adr/0061-five-digit-diagnostic-codes.md)）。",
      "番号の 000 から 099 は、4 桁のコードを写したものに取っておく。",
      "新しいコードには、100 から 999 の番号を割り当てる（評価なら G02100 から）。",
      "一度使った番号は、ほかの意味に使い回さない。",
      "",
      "| 上 2 桁 | 段階 | 主なモジュール |",
      "| --- | --- | --- |",
      "| 01 | 構文（読み込みと解析） | golem-parser |",
      "| 02 | 評価 | golem-eval（プラグインのコマンドは golem-driver） |",
      "| 03 | プロジェクト（`manifest.toml`、`style.toml`、import） | golem-project、golem-driver、golem-eval |",
      "| 04 | 文書の組み立て（ラベル、相互参照、目次） | golem-assemble |",
      "| 05 | lint | golem-lint |",
      "| 06 | プラグイン | golem-plugin、golem-driver |",
      "| 07 | レイアウト（版面、改ページ、傍注、表） | golem-layout-spec、golem-layout、golem-typeset、golem-assemble、golem-driver |",
      "| 08 | 出力（フォント、出力インテント） | golem-typeset、golem-driver |",
      "| 09 | プリフライト | golem-preflight |",
      "",
      "関数を書く言語 Emet（`.emet`）のコードは、`E` と 5 桁の数字からなる（[docs/adr/0160](adr/0160-emet-function-language-core.md)）。",
      "形は `G` のコードと同じで、上 2 桁が段階、下 3 桁が段階の中の番号であり、番号は 100 から使う。",
      "`E` の節は、コードの昇順に従って `G` の節より前に並ぶ。",
      "",
      "| 上 2 桁 | 段階 | 主なモジュール |",
      "| --- | --- | --- |",
      "| 01 | 構文 | golem-emet |",
      "| 02 | 名前と型 | golem-emet |",
      "| 03 | パターンマッチの網羅性 | golem-emet |",
      "| 04 | 評価の上限と循環 | golem-emet |",
      "| 05 | 要求（[docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)） | golem-emet、golem-driver |",
