      "| 07 | lint（[docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)） | golem-emet、golem-driver |",
      "",
      "`.emet` の原因が `.gm` と同じ誤りは、`G` のコードを使う。",
      "読み込みの誤りは [G01001](#g01001)、[G01002](#g01002)、[G01003](#g01003)、`import` のパスの誤りは [G03002](#g03002)、[G03003](#g03003) である。",
      "要求 `file` のパスの誤りも [G03003](#g03003) と [G03004](#g03004) である（[docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)）。",
      "数の演算の誤りは式文脈と同じ 02 のコード（[G02003](#g02003) など）で、位置は `.emet` の中である。",
      "`.gm` から関数を呼ぶときの `.gm` の側の誤り（引数の数と型、散文スロットと本体）は、`G` のコード（[G02119](#g02119) から [G02123](#g02123)）である（[docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)）。",
      "",
      "重大度がプロファイルで変わるコードは `Golem.Syntax.Diagnostic.profileDependentCodes` にまとめてあり、dev では警告、prod ではエラーになる。",
      "今は [G03010](#g03010)、[G05004](#g05004)、[G08100](#g08100) の三つである。",
      "[G02005](#g02005) は、prod でだけ出る警告である。",
      "",
      "09 のコードは、`golem preflight` だけが出す（[golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)）。",
      "[G09002](#g09002) から [G09021](#g09021) の重大度は、プリフライトの設定（`preflight.toml`）で決まり、`Golem.Syntax.Diagnostic.preflightCodes` にまとめてある。",
      "設定で選べるのはエラー、警告、off で、お知らせと情報は選べない。",
      "[G09001](#g09001) は設定のファイルの誤りで、常にエラーである。",
      "09 のコードのメッセージと事実（JSON の `facts`）に書く長さは mm で、小数点以下 2 桁に、等距離なら偶数の側へ丸めて書く。",
      "末尾の 0 は残し、単位の前に空白を入れない（`0.06mm`、`3.00mm`。[docs/adr/0103](adr/0103-single-place-for-unit-conversions.md)）。",
      "[G09013](#g09013) のはみ出しの量だけは、小数点以下 2 桁に切り上げて書く（[docs/adr/0210](adr/0210-warn-overfull-lines-in-build.md)）。",
      "",
      "## お知らせ",
      "",
      "お知らせは、誤りではないが書き手が知っておいたほうがよいことを伝える重大度である（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "直すべきものは警告にし、直さなくてよいものをお知らせにする。",
      "お知らせは終了コードに影響せず、プロファイルで重大度が変わらず、出力も変えない。",
      "人が読む形式と JSON の形式では、エラーと警告の後、情報の前に並ぶ。",
      "",
