      "| [G02108](#g02108) | 廃止予定 | 評価 |",
      "| [G02129](#g02129) | 廃止予定 | 評価 |",
      "| [G03023](#g03023) | 既定の使用 | プロジェクト |",
      "| [G03100](#g03100) | 効果のない書き方 | プロジェクト、評価 |",
      "| [G03114](#g03114) | 廃止予定 | プロジェクト |",
      "| [G03115](#g03115) | 廃止予定 | プロジェクト |",
      "| [G03116](#g03116) | 廃止予定 | プロジェクト |",
      "| [G03117](#g03117) | 廃止予定 | プロジェクト |",
      "| [G03120](#g03120) | 既定の使用 | プロジェクト |",
      "| [G03134](#g03134) | 処理系による調整 | プロジェクト |",
      "| [G04007](#g04007) | 効果のない書き方 | 文書の組み立て |",
      "| [G04008](#g04008) | 効果のない書き方 | 文書の組み立て |",
      "| [G04009](#g04009) | 効果のない書き方 | 文書の組み立て |",
      "| [G04011](#g04011) | 処理系による調整 | 文書の組み立て |",
      "| [G07030](#g07030) | 処理系による調整 | レイアウト |",
      "| [G07039](#g07039) | 処理系による調整 | レイアウト |",
      "| [G07045](#g07045) | 処理系による調整 | 出力 |",
      "| [G07046](#g07046) | 処理系による調整 | レイアウト |",
      "| [G07100](#g07100) | 一般的でない書き方 | レイアウト |",
      "| [G07101](#g07101) | 処理系による調整 | 出力 |",
      "| [G07112](#g07112) | 処理系による調整 | レイアウト |",
      "| [G07113](#g07113) | 処理系による調整 | レイアウト |",
      "| [G07123](#g07123) | 効果のない書き方 | レイアウト |",
      "| [G07124](#g07124) | 効果のない書き方 | レイアウト |",
      "| [G07126](#g07126) | 処理系による調整 | 出力 |",
      "| [G08008](#g08008) | 既定の使用 | 出力 |",
      "| [E02109](#e02109) | 効果のない書き方 | Emet の型の検査 |",
      "",
      "抑制できるのはお知らせと情報だけであり、エラーと警告を抑制する手段はない。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に並べたコードのお知らせは、`golem build`、`golem check`、`golem lint`、LSP のどれにも出ない。",
      "`golem build`、`golem check`、`golem lint` に `--no-notices` を付けると、その実行に限り、すべてのお知らせを出さない。",
      "",
      "```toml",
      "[diagnostics]",
      "silence-notices = [\"G02062\", \"G04007\"]",
      "```",
      "",
      "### 廃止予定の手順",
      "",
      "記法と設定のキーを廃止するときは、次の順に進める（[docs/adr/0174](adr/0174-compatibility-promises-for-1-0.md)）。",
      "いつ予告し、いつエラーにしてよいかは、互換性の文書 [docs/compatibility.md](compatibility.md) の「廃止の手順」に従う。",
      "",
      "1. 廃止を決める ADR で、廃止予定のお知らせのコードを決める。メッセージは「〜は廃止予定です」で始め、代わりの書き方を続ける。この文書の節の「直し方」に、書き換えの前と後の例を置く。",
      "2. 1.0.0 の後は、そのお知らせを minor のバージョンで出し始めることで、廃止を予告する。予告した書き方は、1.x のあいだ受け付け続ける。リリースノートの「変更」の項と、互換性の文書の廃止予定の一覧に挙げる。1.0.0 より前は、プレリリースを含むリリースで一度お知らせを出せば、次のリリースでエラーにしてよい。",
      "3. 1.0.0 の後は次の major のバージョンで、ADR を作ってその書き方をエラーにする。エラーには新しいコードを割り当て、お知らせのコードは状態を「廃止」にする。番号は使い回さない。`silence-notices` にそのコードを書いたプロジェクトは [G03024](#g03024) になるので、リリースノートに、その行を消すよう書く。",
      "",
      "## 情報",
      "",
      "情報は、お知らせより下の重大度である（[docs/adr/0104](adr/0104-info-severity.md)）。",
      "組版の規則どおりに処理系が行ったことの記録で、書き手が知らなくても困らないものを伝える。",
      "`golem build`、`golem check`、`golem lint` に `--verbose`（短い形は `-v`）を付けたときにだけ出し、付けなければ出さない。",
      "人が読む形式でも JSON の形式でも同じである。",
      "情報は終了コードに影響せず、プロファイルで重大度が変わらず、出力も変えない。",
      "`--verbose` を付けても付けなくても、出力のバイト列は同じである。",
      "人が読む形式と JSON の形式では、お知らせの後、最後に並ぶ。",
      "LSP では、目立たない表示の `Hint` として、つねに公開する。",
      "",
      "お知らせと情報を分ける基準は、書き手がそれを知る必要があるかどうかである。",
      "原稿か設定に理由があり、書き手が知っておいたほうがよいものはお知らせにする。",
      "処理系が組版の規則どおりに行ったことで、見落としても困らないものを情報にする。",
      "迷うものはお知らせにする。",
      "一つのコードの重大度は一つに決まり、同じコードが場合によってお知らせになったり情報になったりすることはない。",
      "",
      "情報のコードは `Golem.Syntax.Diagnostic.infoCodes` にまとめてある。",
      "今は次の二つである。",
      "",
      "| コード | 種類 | 段階 |",
      "| --- | --- | --- |",
      "| [G07047](#g07047) | 処理系による調整 | レイアウト |",
      "| [E05108](#e05108) | 効果のない書き方 | Emet の型の検査 |",
      "",
      "`manifest.toml` の `[diagnostics]` の `silence-info` に並べたコードの情報は、`--verbose` を付けても出ず、LSP でも公開しない。",
      "`--verbose` を付けて、ほかの情報は見たいが特定のコードは見たくない、という場合に使う。",
      "すべての情報を止める値はなく、止めるものをコードで書く。",
      "`silence-notices` には情報のコードを、`silence-info` にはお知らせのコードを書けず、どちらも [G03024](#g03024) になる。",
      "`--no-notices` は情報を止めず、`--verbose` と一緒に付けると、お知らせを出さずに情報を出す。",
      "",
      "```toml",
      "[diagnostics]",
      "silence-notices = [\"G02062\"]",
      "silence-info = [\"G07047\"]",
      "```",
      "",
      "## 使っていない番号",
