      "- **廃止**：G09005。[golem-cli ADR 0006](golem-cli/adr/0006-preflight.md) がプリフライトの読めない図版に定めたが、[golem-pdf ADR 0008](golem-pdf/adr/0008-pdf-figures.md) で `golem build` の [G08010](#g08010) に置き換えた。下に節を置く。",
