      "- **空き**：G03103 から G03107。取り下げた [docs/adr/0149](adr/0149-gmx-requirements-and-driver-handlers.md) の実装が `[functions]` の誤りに使った番号で、[docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md) は同じ意味の G03101 と G03102 だけを使い直した。ほかの意味にも使い回さない。",
      "- **空き**：G02109。[docs/adr/0113](adr/0113-closed-range-literal.md) が範囲のコードの番号を詰め直したときに使わなかった番号で、空けておく。",
      "- **新しいコードの番号**：各区分の 100 から 999。",
      "- **使わない区分**：G10。取り下げた [docs/adr/0148](adr/0148-gmx-function-language-core.md) の実装が関数の誤りに使ったが、関数の言語のコードは `E` にしたので（[docs/adr/0160](adr/0160-emet-function-language-core.md)）、G10 の番号はどれも使わず、ほかの意味にも使い回さない。",
      "",
      "## E01100",
      "",
      ".emet の構文の誤りです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "関数のファイル（`.emet`）を文法どおりに読めない。",
      "位置は、読めなくなった字句である。",
      "メッセージには、そこで要る字句を添える。",
      "`.emet` の文法は回復をしないので、一つのファイルに出すのは最初の一つだけである。",
      "文字列と文字のリテラルの `\\u{...}` が Unicode のスカラー値（サロゲートを除く U+10FFFF まで）でないときも、このコードとし、位置はそのエスケープである。",
      "",
      "- メッセージ: `構文の誤りです。<要る字句> が要ります`、`\\u{<16 進数>} は Unicode のスカラー値ではありません`",
      "- 段階とモジュール: Emet の構文（golem-emet の `Golem.Emet.Parse`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- `;` で区切った。`.emet` は宣言、`where` の束縛、`case` の選択肢を改行で区切り、`;` を持たない。",
      "- 二つの束縛や選択肢を一行に書いた。",
      "- 式を次の行に続けるのに、続きの行であることを字句で示さなかった。行の最後に演算子、`=`、`->`、`::`、`,`、`?`、`:` を置くか、次の行を `|`、`-` を除く二項演算子、`?`、`:`、`where`、`->` で始めるか、括弧で囲む。",
      "- 引き算を次の行の行頭の `-` で続けた。行頭の `-` は新しい項目の始まりである。",
      "- 三項演算子の真の枝に、括弧のない `?` を書いた。",
      "- 知らないエスケープ（`\\q` など）を書いた。",
      "",
      "### 直し方",
      "",
      "メッセージの要る字句を書き足すか、改行の位置を直す。",
      "続きの行にするときは、行の最後に演算子を置くか、括弧で囲む。",
      "",
      "## E01101",
      "",
      ".emet に閉じていない括弧か引用符があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の `{`、`(`、`[`、文字列の `\"`、文字の `'` が閉じていない。",
      "`{` はファイルの終わりまで閉じないとき、`(` と `[` は閉じる前に `}` かファイルの終わりが来たとき、文字列と文字は行の終わりかファイルの終わりまで閉じないときに、このコードとする。",
      "位置は、閉じる記号が要るところである。",
      "",
      "- メッセージ: `閉じていない { があります。} が要ります`（`(`、`[`、文字列、文字のリテラルも同じ形）",
      "- 段階とモジュール: Emet の構文（golem-emet の `Golem.Emet.Parse`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- `case ... of {` や `where {` の `}` を書き忘れた。",
      "- 文字列の中に改行を入れた。文字列の改行は `\\n` と書く。",
      "",
      "### 直し方",
      "",
      "閉じる記号を書き足す。",
      "",
      "## E01102",
      "",
      ".emet で使えない予約語です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` が予約しているが使えない語（`if`、`then`、`else`、`for`、`while`、`let`、`in`、`lazy`、`class`、`instance`、`deriving`、`default`）を書いた。",
      "名前の誤りではなく、使えない構文であることを伝えるためのコードである。",
      "位置はその語である。",
      "",
      "- メッセージ: `<語> は .emet で使えない予約語です。<代わりの書き方>`",
      "- 段階とモジュール: Emet の構文（golem-emet の `Golem.Emet.Parse`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- ほかの言語の癖で `if` や `for` を書いた。",
      "- `where` の束縛に `lazy` を付けた。`where` の束縛はどれも、使ったときに一度だけ評価する。",
      "- 型クラスの宣言を書いた。v1 は型クラスを持たない。",
      "",
      "### 直し方",
      "",
      "分岐はガード、`case`、三項演算子で、繰り返しは再帰で、局所の定義は関数の末尾の `where` で書く。",
      "",
      "## E01103",
      "",
      "関数の末尾にない where です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`where` を、関数の最後の等式（ガードがあれば最後のガード）の後ろ以外に書いた。",
      "最後でない等式の後ろ、二つめの `where`、`case` の選択肢とガードの後ろ、`where` の中の `where` が当たる。",
      "位置はその `where` である。",
      "",
      "- メッセージ: `where は関数の最後の等式（ガードがあれば最後のガード）の後ろに一つだけ書けます: <関数の名前>`、`where の中には where を書けません: <関数の名前>`、`case の選択肢の後ろには where を書けません: <関数の名前>`",
      "- 段階とモジュール: Emet の型の検査（golem-emet の `Golem.Emet.Check`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- Haskell のように、等式ごとに `where` を書いた。",
      "",
      "### 直し方",
      "",
      "`where` を一つにまとめ、最後の等式の後ろに置く。",
      "入れ子にした局所の定義は、同じ `where` の中に並べる。",
      "",
      "## E02100",
      "",
      ".emet の未定義の名前です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` で、定義していない名前、型、型変数、コンストラクタ、組み込みのモジュール、レコードの欄を参照した。",
      "シグネチャだけがあって等式のない関数と束縛も、このコードとする。",
      "位置はその名前である。",
      "",
      "- メッセージ: `未定義の名前 <名前> です`（型、コンストラクタ、モジュール、欄も同じ形）、`関数 <名前> の等式がありません`",
      "- 段階とモジュール: Emet の型の検査（golem-emet の `Golem.Emet.Check`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- `where` の中から、等式の引数のパターンの変数を参照した。`where` の中からは見えない。",
      "- 取り込んだファイルがさらに取り込んだ名前を使った。取り込みは推移しない。",
      "- 組み込みのモジュールの関数を、モジュールの名前を付けずに書いた（`length` ではなく `List.length`）。",
      "",
      "### 直し方",
      "",
      "名前を定義するか、綴りを直す。",
      "引数の値を使う局所の関数は、その値を引数として受け取る形で書く。",
      "",
      "## E02101",
      "",
      ".emet の型が合いません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の式の型が、その位置で求める型と合わない。",
      "数は自然数から整数へ、整数から有理数へ暗に広がるが、逆には狭まらない。",
      "比較の演算子は数、`Bool`、`Char`、`String` に、算術の演算子は数に、`++` は `String` と `List` にだけ使える。",
      "型の別名の循環と、型の引数の数の誤りも、このコードとする。",
      "位置は型の合わない式である。",
      "",
      "- メッセージ: `型が合いません: <求める型> を求める位置に <実際の型> があります`、`<演算子> は <使える型> にだけ使えます（<型> があります）`",
      "- 段階とモジュール: Emet の型の検査（golem-emet の `Golem.Emet.Check`、`Golem.Emet.Solve`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- `Char` と `String` を比べた（`'a' == \"a\"`）。",
      "- 利用者のデータ型の値を `==` で比べた。v1 では、データ型の値はパターンマッチで比べる。",
      "- シグネチャの型変数に算術の演算子を使った。",
      "",
      "### 直し方",
      "",
      "型を揃える。",
      "データ型の値は `case` かパターンで比べる。",
      "",
