      "`.emet` の等式、`case` の選択肢、ガードが、前のものがすべて覆っているので決して選ばれない。",
      "`otherwise` の後ろのガードも、このコードとする。",
      "位置はその等式、選択肢、ガードである。",
      "",
      "- メッセージ: `選ばれない等式です: <名前>`（`case` では「選択肢」）、`otherwise の後ろのガードは選ばれません: <名前>`",
      "- 段階とモジュール: Emet の型の検査（golem-emet の `Golem.Emet.Check`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- `_` の等式を、ほかの等式より前に書いた。",
      "",
      "### 直し方",
      "",
      "選ばれない等式を消すか、順を直す。",
      "",
      "## E03102",
      "",
      "ガードの並びの最後が otherwise ではありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` のガードの並びの最後が `otherwise` でない。",
      "網羅は条件の意味を解析せず構文で検査するので、`True` やつねに真になる式でも `otherwise` と見なさない。",
      "関数の最後の等式（`case` なら最後の選択肢）がガードを持たず、パターンがすべて変数か `_` であれば、このコードにしない。",
      "位置は並びの最後のガード（縦線から右辺の終わりまで）である。",
      "",
      "- メッセージ: `ガードの並びの最後が otherwise ではありません: <関数の名前>`",
      "- 段階とモジュール: Emet の型の検査（golem-emet の `Golem.Emet.Check`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)",
      "",
      "### 主な原因",
      "",
      "- 最後のガードに `n <= 1` のような条件を書いた。",
      "",
      "### 直し方",
      "",
      "最後のガードを `otherwise` にする。",
      "",
      "## E04100",
      "",
