      "手数は言語の意味で数えるので、止まる位置はマシンによらない。",
      "組み込みの関数と `++` が作る値の長さは、作る前に数える。",
      "値を作る前に上限を超えることがわかれば、その値を作らずに止める（[docs/adr/0223](adr/0223-emet-sizes-before-building-values.md)）。",
      "上限を超えた呼び出しは、出力を何も返さない。",
      "位置は評価を始めた `.gm` の呼び出しである。",
      "",
      "- メッセージ: `関数の評価の手数が上限（<上限> 手）を超えました: <関数の名前>（<.emet のパス>:<行>）`",
      "- 段階とモジュール: Emet の評価（golem-emet の `Golem.Emet.Eval`）",
      "- ADR: [docs/adr/0160](adr/0160-emet-function-language-core.md)、[docs/adr/0223](adr/0223-emet-sizes-before-building-values.md)",
      "",
      "### 主な原因",
      "",
      "- 再帰が止まらない。",
      "- 仕事の量が多すぎる。",
      "",
      "### 直し方",
      "",
      "再帰が止まることを確かめる。",
      "重い仕事はプラグインで書く。",
      "",
      "## E04101",
      "",
      "末尾でない呼び出しの深さが上限を超えました",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
