      "",
      "### 直し方",
      "",
      "結果を引数で持ち回る形にして、末尾再帰に書き直す。",
      "",
      "## E04102",
      "",
      "where の束縛が自分自身の値を求めました",
      "",
      "- 重大度: エラー",
