      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.Functions`）",
      "- ADR: [docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)",
      "",
      "### 主な原因",
      "",
      "- Shift_JIS など、UTF-8 でない符号化で保存した。",
      "",
      "### 直し方",
      "",
      "ファイルを UTF-8 で保存し直す。",
      "",
      "## E05104",
      "",
      "要求が manifest.toml の [functions.requires] にありません",
      "",
      "- 重大度: エラー",
