      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`pub inline` の戻り値が `Inlines` でない、`pub block` の戻り値が `Blocks` でない、`pub filter` の型が `Blocks -> Blocks`（要求の列を付けたものを含む）でない、`pub fn` の戻り値が `.gm` の値に写せない（`Nat`、`Int`、`Rat`、`String`、`Bool`、それらの `List` でない）。",
      "位置は戻り値の型か、フィルタではシグネチャの型である。",
      "",
      "- メッセージ: `pub <種類> の戻り値は <型> です: <名前> :: <書いた型>`、`pub filter の型は Blocks -> Blocks か、要求の列を付けた Blocks -> <...> Blocks です: <名前>`、`pub fn の戻り値は Nat、Int、Rat、String、Bool か、それらの List です: <名前> :: <書いた型>`",
      "- 段階とモジュール: `.gm` から使う関数の宣言（golem-emet の `Golem.Emet.Check`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- インラインのコマンドが文字列を返した。`Inline.text` で包む。",
      "- 式文脈から呼ぶ関数を `pub inline` で宣言した。",
      "",
      "### 直し方",
      "",
      "戻り値の型を種類に合わせるか、種類の語を変える。",
      "",
      "## E06102",
