      "並びの誤りは、`Inlines` と `Blocks` の引数をほかの型の引数の前に置くこと、インラインのコマンドの `Blocks`、ブロックコマンドの `Inlines`、最後でない `Blocks`、`pub fn` の `Inlines` と `Blocks` である。",
      "位置は、その引数の型である。",
