      "空行、ファイルの末尾、ブロックの始まりの文字（`#`、`- ` など）で始まる行が続いた。",
      "見出しと定義リストの用語の行末の `\\` も、このコードになる。",
      "表の行の閉じる `|` の後に書いた `\\` も、このコードになる（[golem-parser ADR 0010](golem-parser/adr/0010-ruby-slash-escape-and-table-cell-breaks.md)）。",
