      "",
      "## G01029",
      "",
      "構文エラー",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "コードを割り当てていない文法のラベルで解析が失敗した。",
      "G01010 から G01023 に当たらない構文エラーの既定のコードである。",
      "",
      "- メッセージ: `構文エラー（<ラベル>）`",
      "- 段階とモジュール: 構文（golem-parser）",
      "- ADR: [golem-parser ADR 0009](golem-parser/adr/0009-syntax-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- G01010 から G01023 に当たらない構文の誤り。メッセージのラベルが、失敗した文法の部分を示す。",
      "",
      "### 直し方",
      "",
      "ラベルの示す位置の記法を、[記法](markup.md) と照らして直す。",
      "",
      "## G01100",
      "",
      "予約された記法です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "将来のために予約された記法を書いた。",
      "予約された記法は次のとおりである（[予約された記法](markup.md#予約された記法)）。",
      "",
      "- `[!`：インラインのマクロのための記法。インラインのコマンドを書けるところで使えない。",
      "- `@!`：ブロックのマクロのための記法。ブロックコマンドを書ける行頭で使えない。段落の二行め以降の行頭も含む。",
      "- `..`：端を省いた範囲と、終わりを含まない範囲のための記法。式の中と、`@listing` の `lines` とコードブロックの `highlight` の語と文字列で使えない（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "",
      "位置は、予約された記法の最初の字から始まる。",
      "範囲は記法ごとに次のとおりである（[docs/adr/0116](adr/0116-narrow-reserved-syntax-recovery.md)）。",
      "",
      "- `[!`：同じ行の対応する `]` まで。`[` と `]` の入れ子を数え、エスケープ（`\\]`）とコメント（`%% ] %%`）の中の `]` は数えない。対応する `]` が同じ行になければ `[!` の二字だけである。",
      "- `@!`：行の終わりまで。",
      "- `..`：二字だけ。",
      "",
      "予約された記法の後ろは、そのまま読まれる。",
      "後ろに別の誤りがあれば、それも報告される。",
      "たとえば `[strong: [!x]]` の外の `]` は `strong` を閉じ、`[= [1..3]]` の `3` と閉じ括弧は式として読まれる。",
      "`@!` は本体を持たないので、次の行から `@!` より深く字下げした行は、それぞれ字下げの誤り（[G01011](#g01011)）になる。",
      "語と文字列の中の `..` は評価の段階で見つかり、位置はその引数である。",
      "記法によらず、メッセージは一つである。",
      "どの記法を書いたかは位置で分かる。",
      "",
      "- メッセージ: `予約された記法です。今のバージョンでは使えません`",
      "- 段階とモジュール: 構文（golem-parser）。語と文字列の中の `..` は評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0115](adr/0115-reserved-syntax-code.md)、[docs/adr/0113](adr/0113-closed-range-literal.md)、[docs/adr/0116](adr/0116-narrow-reserved-syntax-recovery.md)",
      "",
      "### 主な原因",
      "",
      "- 本文に `[!` を書こうとした。",
      "- 本文の行頭に `@!` を書こうとした。",
      "- `[= 1..3]` や `lines=1..3` のように、範囲を `..` で書いた。",
      "",
      "### 直し方",
      "",
      "本文の `[!` は `\\[!` と書く。",
      "本文の行頭の `@!` は `\\@!` と書く。",
      "行の途中の `@!` は記法ではないので、そのまま書ける。",
      "両端を含む範囲は `...` で書く（`1..3` ではなく `1...3`）。",
      "",
      "## G02001",
      "",
      "型が合いません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "式の演算や関数に、使えない型の値を渡した。",
      "",
      "- メッセージ: 型の誤りを述べる文言。たとえば `- は <型> に使えません`、`<型> と <型> にこの演算子は使えません`、`<型> は数ではありません`、`<型> の要素は参照できません`、`% は整数にだけ使えます`、`div は整数にだけ使えます`、`join の配列には文字列だけを並べます`、`join は文字列の配列と区切りの文字列に使えます`。",
      "`<型>` は値の型の名前であり、数では `自然数`、`整数`、`有理数` のどれかである（[docs/adr/0101](adr/0101-rational-numbers-in-expressions.md)）。",
      "`%` と `div` は、整数の値を持つ数にだけ使える。",
      "有理数の型でも、値が整数なら使える（`div(4.0, 2)`）。",
      "",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.Expr`）",
      "- ADR: [golem-eval ADR 0003](golem-eval/adr/0003-evaluation-diagnostic-codes.md)。[docs/adr/0033](adr/0033-colophon-contributors-and-printings.md) が `join` の誤りを加えた。[docs/adr/0101](adr/0101-rational-numbers-in-expressions.md) が数の型の名前を改めた",
      "",
      "### 主な原因",
      "",
      "- 文字列と数の演算など、型の合わない値を演算子や関数に渡した。",
      "- `(1...2) < (1...3)` や `(1...2) + 1` のように、範囲を大小の比較や算術の演算子に使った。範囲に使える演算子は `==` と `!=` だけである（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "- `join` に、文字列でない要素を持つ配列か、配列でない値を渡した。区切りに文字列でない値を渡した。",
      "",
      "### 直し方",
      "",
      "値の型をそろえる。",
      "",
      "## G02002",
      "",
      "未定義の名前です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "式が、定義されていない変数、名前空間、要素を参照した。",
      "",
      "- メッセージ: `未定義の名前 <名前> です`、`未定義の名前空間 <名前空間> です`、`名前がありません`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.Expr`）",
      "- ADR: [golem-eval ADR 0003](golem-eval/adr/0003-evaluation-diagnostic-codes.md)。[docs/adr/0033](adr/0033-colophon-contributors-and-printings.md) が `meta.roles` などの例を加えた",
      "",
      "### 主な原因",
      "",
      "- 名前の綴りを誤った。",
      "- `@set` や `@import` を書き忘れた。",
      "- マニフェストにない値を `meta` で引いた。その役割の項目がない `meta.roles.binder`、`printings` のない本の `meta.printing`、`publisher-person` のない本の `meta.publisher_person` などである。",
      "",
      "### 直し方",
      "",
      "定義を確かめ、綴りを直すか定義を書く。",
      "",
      "## G02003",
      "",
      "0 で割っています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
