      "## G02037",
      "",
      "lines の範囲がファイルの行を外れています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@listing` の `lines` の範囲が、ファイルの行（1 から行数まで）を外れる。",
      "始めが 0 の範囲も、このコードになる。",
      "位置は `lines` の引数である。",
      "",
      "`lines` のほかの誤りは、原因ごとのコードになる（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "行の番号でも範囲でもない値は [G02105](#g02105)、始めが終わりより大きい範囲は [G02106](#g02106)、二つ以上の項目か配列は [G02107](#g02107)、端のない範囲か端の読めない範囲は [G02110](#g02110) である。",
      "端が負の数なら [G02103](#g02103)、整数でない数なら [G02104](#g02104)、式の評価の上限を超える数なら [G02086](#g02086) になる（[docs/adr/0102](adr/0102-natural-number-type.md)）。",
      "",
      "- メッセージ: `@listing の lines の範囲がファイルの行（1〜<行数>）を外れています: <値>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [golem-eval ADR 0003](golem-eval/adr/0003-evaluation-diagnostic-codes.md)、[docs/adr/0113](adr/0113-closed-range-literal.md)",
      "",
      "### 主な原因",
      "",
      "- 範囲の終わりが、ファイルの行数より大きい。ファイルが短くなった。",
      "- `lines=0...5` のように、行の番号を 0 から数えた。",
      "",
      "### 直し方",
      "",
      "`lines=3...10` のように、1 以上でファイルの行数以下の範囲を書く。",
      "",
      "## G02038",
      "",
      "散文スロットの数が違います",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "インラインのコマンドの散文スロット（`: ` の後の本文）の数が違う。",
      "`number-text`、`ref-number`、`ref-title`、`ref-page`、`cite` は散文スロットを取らないので、書くとこのコードになり、コマンドは出力しない。",
      "`link` の散文スロットは一つまでで、二つ以上書くとこのコードになる（[docs/adr/0182](adr/0182-external-links.md)）。",
      "`[note 名前: 本文]` のように、名前と散文スロットを両方書いた `note` もこのコードになり、何も出力しない（[docs/adr/0263](adr/0263-notes-with-more-than-one-paragraph.md)）。",
      "",
      "- メッセージ: `<名前> には散文スロットが一つ必要です`、`index には散文スロットが一つ必要です`、`ruby には散文スロットが二つ必要です`、`<名前> は散文スロットを取りません`、`link の散文スロットは一つまでです`、`note は名前を書くと散文スロットを取りません`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [golem-eval ADR 0003](golem-eval/adr/0003-evaluation-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- インラインのコマンドの `: ` の後の本文（散文スロット）の数を誤った。",
      "",
      "### 直し方",
      "",
      "コマンドの書き方を確かめ、スロットの数をそろえる。",
      "ルビは対象と読みの二つを書く。",
      "散文スロットを取らないコマンドからは、`: ` の後の本文を消す。",
      "名前を書いた `note` の本文は、`@note 名前` の本体に書く。",
      "",
