      "式の言語から浮動小数点数をなくし、累乗の結果を丸めなくなったので、このコードは出なくなった（[docs/adr/0101](adr/0101-rational-numbers-in-expressions.md)）。",
      "",
      "- メッセージ: `累乗の正確な計算に要るビットの数 <n> が、上限の 1048576（2 の 20 乗）を超えます（結果の大きさによらない上限です）`",
      "- 段階とモジュール: 評価（golem-eval）",
      "- ADR: [golem-eval ADR 0005](golem-eval/adr/0005-float-overflow.md)、[golem-eval ADR 0006](golem-eval/adr/0006-exact-power-limit-before-range.md)、[golem-eval ADR 0007](golem-eval/adr/0007-power-limit-message.md)（定めた）、[docs/adr/0101](adr/0101-rational-numbers-in-expressions.md)（使わなくした）",
