      "絶対値の平方根でよければ `sqrt(abs(x))` と書く。",
      "",
      "## G02102",
      "",
      "小数点以下が 1000 桁を超える数は本文に埋め込めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[= ...]` で本文に埋め込む数の表記が、小数点以下 1000 桁を超える。",
      "数は値で書き、有限小数になる有理数は正確な値を、循環小数になる有理数は有効数字 17 桁に丸めた値を書く（[docs/markup.md](markup.md) の「数の規則」）。",
      "どちらの場合も、書く表記の小数点以下の桁数が 1000 を超えれば、このエラーになる。",
      "位置は `[= ...]` である。",
      "",
      "- メッセージ: `小数点以下が 1000 桁を超える数は本文に埋め込めません。round か fixed で桁数を決めます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.Expr`）",
      "- ADR: [docs/adr/0101](adr/0101-rational-numbers-in-expressions.md)",
      "",
      "### 主な原因",
      "",
      "- `[= 2 ** -1001]` のように、分母の大きい有限小数を埋め込んだ。",
      "- `[= 1 / (3 * 10 ** 990)]` のように、絶対値のとても小さい数を埋め込んだ。",
      "",
      "### 直し方",
      "",
      "`round(x, n)` か `fixed(x, n)` で、小数点以下の桁数を決めてから埋め込む。",
      "",
      "## G02103",
      "",
      "自然数を求める箇所に負の数があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "0 以上の整数（自然数）だけを受け取る箇所に、負の数を書いた（[docs/adr/0102](adr/0102-natural-number-type.md)）。",
      "原稿と設定のファイルの両方に出る。",
      "",
      "原稿で自然数を求める箇所は、`@toc` の `depth`、`@need-lines`、`@blank-line`、`@number`、図版の `page`、`@listing` の `lines` の両端、コードブロックの `numbers` と `highlight` の両端、`round` と `fixed` の桁数である。",
      "語で書いても式で書いても、同じコードとメッセージになる。",
      "`doc` を参照しない式の値は、評価の前の解析で調べる。",
      "`doc` を参照する式の値は、文書構造（S1）で評価するときに調べ、同じ位置に出す。",
      "位置は、コマンドの引数ならコマンド、`round` と `fixed` の桁数なら桁数の式である。",
      "",
      "設定のファイルで自然数を読むキーは、`style.toml` の `[page.grid]` の `characters`、`lines`、`columns`、見出しの `lines`、`[index]` の `columns`、`manifest.toml` の `printings` の `edition` と `printing`、`preflight.toml` のしきい値と数のキーである。",
      "負の数は、ファイルごとのコード（[G03006](#g03006)、[G03001](#g03001)、[G09001](#g09001)）ではなく、このコードになる。",
      "原因が原稿の負の数と同じなので、コードの上 2 桁が段階を表す規則の例外として、設定のファイルを読む段階でもこのコードを出す。",
      "位置は、そのキーの値である。",
      "0 や 1 以上を求める範囲の検査と、小数を書いた型の誤りは、ファイルごとのコードのままである。",
      "",
      "- メッセージ: 原稿では `<何>には 0 以上の整数を書きます（書かれた値は <値>）`、設定のファイルでは `<キー> には 0 以上の整数を書きます`（キーは `page.grid.lines` のような経路で、値は位置で示す）。`<何>` は箇所の名前（`@blank-line の引数`、`round の桁数`、`@listing の lines` など）で、名前がラテン文字で終わるときは「には」の前に空白を置く（`@listing の lines には`）。`<値>` は書かれた値を正確に書いたもので、循環小数になる値は分数（`7/3`）で書く。",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、`Golem.Eval.Expr`、`Golem.Eval.Analysis`）、プロジェクト（golem-project の `Golem.Project.Manifest`、`Golem.Project.Style`、golem-preflight の `Golem.Preflight.Rules`）",
      "- ADR: [docs/adr/0102](adr/0102-natural-number-type.md)",
      "",
      "### 主な原因",
      "",
      "- `@blank-line -1` のように、負の数を書いた。",
      "- `@listing` の `lines=3...-1` のように、範囲の端に負の数を書いた。",
      "- `style.toml` の `lines = -1` のように、設定のファイルに負の数を書いた。",
      "- `[= round(x, n - 3)]` のように、負になりうる式を書いた。",
      "",
      "### 直し方",
      "",
      "0 以上の整数を書く。",
      "式なら、値が負にならないように直す。",
      "",
      "## G02104",
      "",
      "自然数を求める箇所に整数でない数があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "0 以上の整数（自然数）だけを受け取る箇所に、整数でない数を書いた（[docs/adr/0102](adr/0102-natural-number-type.md)）。",
      "箇所と調べる時期は [G02103](#g02103) と同じである。",
      "値が整数の有理数（`2.0`、`[= 4 / 2]`）は、整数として受け取る。",
      "負の数で整数でもない数は、[G02103](#g02103) になる。",
      "",
      "範囲の端に整数でない数を書いたときも、語でも式でもこのコードになる（`lines=1...1.5`、`[= 1...7 / 2]`、`@set r = 1.5...3`、[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "範囲を受け取らない引数の語（`[number-text -1...1.5]`、`@blank-line 1...1.5`）も、同じ字の式と同じく、範囲を受け取らない引数の範囲（[G02113](#g02113)）ではなくこのコードになる（[docs/adr/0135](adr/0135-range-words-read-as-range-expressions.md)）。",
      "原因は「整数が要るところに整数でない数を書いた」で同じだからである。",
      "範囲の値を作るときは、範囲の端は負でもよいので、負で整数でない数もこのコードになる。",
      "位置は、範囲の値を作るときはその範囲の式である。",
      "",
      "- メッセージ: `<何>には 0 以上の整数を書きます（書かれた値 <値> は整数ではありません）`。`<何>` と `<値>` は [G02103](#g02103) と同じである。範囲の値を作るときは `範囲の端には整数を書きます（書かれた値 <値> は整数ではありません）`。",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、`Golem.Eval.Expr`、`Golem.Eval.Analysis`）",
      "- ADR: [docs/adr/0102](adr/0102-natural-number-type.md)、[docs/adr/0113](adr/0113-closed-range-literal.md)、[docs/adr/0135](adr/0135-range-words-read-as-range-expressions.md)",
      "",
      "### 主な原因",
      "",
      "- `@blank-line 1.5` のように、小数を書いた。",
      "- `@set r = 1.5...3` のように、範囲の端に小数を書いた。",
      "- `[= round(x, n / 2)]` のように、割り切れない割り算を書いた。",
      "",
      "### 直し方",
      "",
      "整数を書く。",
      "式なら、`floor`、`ceil`、`round`、`div` で整数にする。",
      "",
      "## G02105",
      "",
      "行の番号でも範囲でもない値です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@listing` の `lines` かコードブロックの `highlight` の値（配列なら要素、語と文字列ならカンマで区切った項目）が、行の番号でも範囲でもない（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "語と文字列では、数でも `a...b` でも `a-b` でもない項目と、空の項目である。",
      "式では、数でも範囲でも文字列でも（`highlight` では配列でも）ない値（真偽値、`nil`、連想配列）と、`highlight` の配列の数でも範囲でもない要素である。",
      "位置は引数である。",
      "",
      "- メッセージ: `<何> には行の番号か範囲を書きます: <値>`。`<何>` は `@listing の lines` か `コードブロックの highlight` である。",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0113](adr/0113-closed-range-literal.md)",
      "",
      "### 主な原因",
      "",
      "- `lines=abc` のように、数でない語を書いた。",
      "- `highlight=3,,5` のように、カンマを続けて空の項目を書いた。",
      "- `lines=[= true]`、`highlight=[= [nil]]` のように、数でも範囲でもない値の式を書いた。",
      "",
      "### 直し方",
      "",
      "行の番号（`5`）か範囲（`3...5`）を書く。",
