      "",
      "### 意味",
      "",
      "`@listing` の `lines` かコードブロックの `highlight` の語か文字列に、両端を `-` で区切った範囲（`3-5`）を書いた（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "範囲は `...` で区切る（`3...5`）。",
