      "今は `-` で区切った範囲も同じ行を取り込み、強調する。",
      "お知らせは引数ごとに一つであり、メッセージの範囲はその引数の最初の `-` の範囲である。",
      "位置は引数である。",
      "`-` の範囲をエラーにする時期は、[docs/compatibility.md](compatibility.md) の「廃止予定の書き方」にある。",
      "",
