      "",
      "書き換える前：",
      "",
      "```",
      "@listing src/Main.hs lines=10-20 highlight=12,14-15",
      "```",
      "",
      "書き換えた後：",
      "",
      "```",
      "@listing src/Main.hs lines=10...20 highlight=12,14...15",
      "```",
      "",
      "## G02110",
      "",
      "範囲の端には数を書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "範囲の端がない、端が数でない、または端が数として読めない（[docs/adr/0113](adr/0113-closed-range-literal.md)）。",
      "式の構文では、端のない範囲（`[= 5...]`、`[= ...5]`）、端の読めない範囲（`[= 1....2]`）、端の後に点が続く範囲（`[= 1...2...3]`、`[= 1...2..3]`）である。",
      "式の評価では、端の値が数でない範囲（`[= \"a\"...3]`、`[= true...3]`）である。",
      "`lines` と `highlight` の語と文字列では、端が空の項目（`1...`、`...3`）と、端が数のリテラルとして読めない項目（`a...3`、`1-2...3`、`1....2`、`1...2...3`、`1...2..3`）である。",
      "位置は、式の構文ではその誤りの位置、式の評価ではその範囲の式、語と文字列では引数である。",
      "",
      "- メッセージ: `範囲の端には数を書きます: <値>`。式の構文の誤りでは `範囲の端には数を書きます`。",
      "- 段階とモジュール: 構文（golem-parser）、評価（golem-eval の `Golem.Eval.Expr`、`Golem.Eval.Analysis`、`Golem.Eval.File`）",
      "- ADR: [docs/adr/0113](adr/0113-closed-range-literal.md)",
      "",
      "### 主な原因",
      "",
