      "### 主な原因",
      "",
      "- 図版のキャプションの中に、別の `@figure` を字下げして書いた。",
      "- キャプションに箇条書き、表、コードブロックを書いた。",
      "",
      "### 直し方",
      "",
      "キャプションは段落だけで書く。",
      "箇条書きや表は、図版の後の本文に置く。",
      "図版を並べたいときは、`@figure` を字下げせずに続けて書く。",
      "",
      "## G02119",
      "",
      "シグネチャにないキーワード引数です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の関数のコマンドに、そのシグネチャにないキーワード引数を書いた。",
      "関数は呼ばない。",
      "位置は、そのキーワード引数である。",
      "",
      "- メッセージ: `シグネチャにないキーワード引数です: <名前>（<コマンド> のキーワード引数: <名前の一覧>）`、`シグネチャにないキーワード引数です: <名前>（<コマンド> はキーワード引数を取りません）`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- キーワード引数の名前を書き誤った。",
      "",
      "### 直し方",
      "",
      "メッセージの一覧にある名前を使う。",
      "",
      "## G02120",
      "",
      "位置引数の数が合いません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の関数のコマンドか `pub fn` に渡した位置引数の数が、シグネチャと合わない。",
      "可変長引数（`Varargs`）を持つ関数では、可変長引数の前の引数の数より少ないときに出す。",
      "関数は呼ばない。",
      "位置は、呼び出しである。",
      "",
      "- メッセージ: `位置引数の数が合いません: <関数> は <数> 個の位置引数を取りますが、<数> 個あります`。可変長引数を持つ関数では `位置引数の数が合いません: <関数> は <数> 個以上の位置引数を取りますが、<数> 個あります`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、`Golem.Eval.Expr`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- 引数を書き忘れたか、空白を含む値を `\"...\"` で囲み忘れて二つの引数にした。",
      "",
      "### 直し方",
      "",
      "シグネチャの位置引数の数だけ値を書く。",
      "",
      "## G02121",
      "",
      "値の型が引数の型に写せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の関数のコマンドか `pub fn` に渡した値が、引数の型に写せない。",
      "狭い数は広い数に写せるが、逆は写せない（`Int` の値を `Nat` の引数に渡せない）。",
      "語の `true` と `false` は真偽値として写す。",
      "メッセージには、何番目の値か（キーワード引数ならその名前）と、求めた型と、渡した値の型を書く。",
      "関数は呼ばない。",
      "位置は、呼び出しである。",
      "",
      "- メッセージ: `引数の型が合いません: <関数> の <番号> 番目の値は <型> を求めますが、<値の型>です`。キーワード引数では `引数の型が合いません: <関数> のキーワード引数 <名前> は <型> を求めますが、<値の型>です`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、`Golem.Eval.Expr`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- 数を求める引数に語を書いた。",
      "- 可変長引数の文字列の並びに数を書いた。数を文字列として渡すには `\"1\"` と書く。",
      "",
      "### 直し方",
      "",
      "求める型の値を書く。",
      "",
      "## G02122",
      "",
      "散文スロットの数が合いません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`.emet` の関数のインラインのコマンドに書いた散文スロットの数が、シグネチャの `Inlines` の引数の数と合わない。",
      "関数は呼ばない。",
      "位置は、呼び出しである。",
      "",
      "- メッセージ: `散文スロットの数が合いません: <コマンド> は <数> 個の散文スロットを取りますが、<数> 個あります`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- `:` の後ろの散文を書き忘れた。",
      "- `|` で散文スロットを分け過ぎた。",
      "",
      "### 直し方",
      "",
      "シグネチャの `Inlines` の数だけ散文スロットを書く。",
      "",
      "## G02123",
      "",
      "本体を受け取らない関数のブロックコマンドに本体があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "最後の引数が `Blocks` でない `.emet` の関数のブロックコマンドに、字下げした本体を書いた。",
      "関数は呼ばない。",
      "位置は、呼び出しである。",
      "",
      "- メッセージ: `本体を受け取らない関数のブロックコマンドに本体があります: @<コマンド>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0162](adr/0162-calling-emet-functions-from-gm.md)",
      "",
      "### 主な原因",
      "",
      "- 次の段落を、ブロックコマンドの行の下に字下げして書いた。",
      "",
      "### 直し方",
      "",
      "本体を字下げせずに書くか、関数の最後の引数を `Blocks` にする。",
      "",
      "## G02124",
      "",
      "link の引数が誤っています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[link]` の引数が、URL の文字列の位置引数の一つだけでない。",
      "URL がない、位置引数が二つ以上ある、キーワード引数を書いた、URL が文字列でない場合である。",
      "URL は、文字列リテラル（`\"...\"`）か、文字列を値に持つ式文脈（`[= ...]`）で書く。",
      "語や数は文字列ではない。",
      "コマンドは実行せず、リンクを作らない。",
      "位置は、コマンドである。",
      "",
      "- メッセージ: `link の引数が誤っています`。URL の位置引数が語で、散文スロットが `//` で始まるときは `link の引数が誤っています。URL は \"https://...\" のように引用符で囲みます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0182](adr/0182-external-links.md)",
      "",
      "### 主な原因",
      "",
      "- `[link https://example.com/: 例]` のように、URL を引用符で囲まずに書いた。命令文脈の `:` は散文スロットの始まりなので、位置引数は語 `https` だけになる。",
      "- URL を書き忘れた。",
      "- 表示の文字を、二つ目の位置引数に書いた。",
      "",
      "### 直し方",
      "",
      "URL を引用符で囲み、`[link \"https://example.com/\": 例]` と書く。",
      "表示の文字は、`:` の後の散文スロットに書く。",
      "",
      "## G02125",
      "",
      "URL の形が誤っています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[link]` の URL が、RFC 3986 の絶対 URI の形でない。",
      "空白と制御文字を含む、`%` の後に 16 進の数字が二つ続かない、`#` が二つ以上ある、`http` と `https` の URL に `//` とホストがない、ホストが空である、といった場合である。",
      "パス、クエリ、フラグメント、ホストの ASCII でない文字は、RFC 3987 の IRI の文字としてこの検査を通る（ホストの ASCII でない文字は [G02127](#g02127)）。",
      "リンクは作らない。",
      "位置は、コマンドである。",
      "プラグインと `.emet` の関数が返したリンクの URL の誤りは、プラグインでは [G06009](#g06009)、関数では [E06104](#e06104) になる。",
      "",
      "- メッセージ: `URL の形が誤っています: <URL>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、golem-doc の `Golem.Doc.Url`）",
      "- ADR: [docs/adr/0182](adr/0182-external-links.md)",
      "",
      "### 主な原因",
      "",
      "- URL に空白を書いた。",
      "- `https:///a` のように、ホストを書き忘れた。",
      "- `%` を、符号化の印でなく文字として書いた。",
      "",
      "### 直し方",
      "",
      "空白と `%` は `%20` と `%25` に符号化して書く。",
      "`https://` の後にホストを書く。",
      "",
      "## G02126",
      "",
      "リンクにできる URL は http と https だけです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[link]` の URL の scheme が、`http` と `https` のどちらでもない。",
      "scheme の大文字と小文字は区別しない。",
      "scheme のない URL（`example.com` など）も、これに当たる。",
      "`javascript:` のような URL をリンクにしないためである。",
      "リンクは作らない。",
      "位置は、コマンドである。",
      "",
      "- メッセージ: `リンクにできる URL は http と https だけです: <URL>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、golem-doc の `Golem.Doc.Url`）",
      "- ADR: [docs/adr/0182](adr/0182-external-links.md)",
      "",
      "### 主な原因",
      "",
      "- `https://` を書き忘れた。",
      "- `mailto:` や `tel:` の URL をリンクにしようとした。",
      "",
      "### 直し方",
      "",
      "`https://` から書く。",
      "`mailto:` などの URL は、リンクにせず、文字として書く。",
      "",
      "## G02127",
      "",
      "URL のホストは ASCII で書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[link]` の URL のホストに、ASCII でない文字がある。",
      "国際化ドメイン名は、利用者が Punycode（`xn--` で始まる形）で書く。",
      "パス、クエリ、フラグメントの ASCII でない文字は、この検査に当たらない。",
      "リンクは作らない。",
      "位置は、コマンドである。",
      "",
      "- メッセージ: `URL のホストは ASCII で書きます: <URL>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、golem-doc の `Golem.Doc.Url`）",
      "- ADR: [docs/adr/0182](adr/0182-external-links.md)",
      "",
      "### 主な原因",
      "",
      "- `https://例え.jp/` のように、日本語のドメイン名をそのまま書いた。",
      "",
      "### 直し方",
      "",
      "ホストを Punycode で書く（`https://xn--r8jz45g.jp/`）。",
      "",
      "## G02128",
      "",
      "リンクの中にリンクになる要素は置けません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[link]` の散文スロットの中に、リンク、相互参照（`[ref-number]`、`[ref-title]`、`[ref-page]`）、脚注、傍注、引用を書いた。",
      "どれも HTML では `a` 要素になる要素であり、`a` 要素の中に `a` 要素は置けない。",
      "文字スタイル、色、圏点、ルビの親文字の中に書いたものも数える。",
      "見つけた要素ごとに一つ出す。",
      "リンクは作らない。",
      "位置は、外側の `[link]` である。",
      "",
      "- メッセージ: `リンクの中にリンクになる要素は置けません: <要素>`。要素は `link`、`ref-number`、`ref-title`、`ref-page`、`note`、`sidenote`、`cite` のどれかである",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`、golem-doc の `Golem.Doc.Url`）",
      "- ADR: [docs/adr/0182](adr/0182-external-links.md)",
      "",
      "### 主な原因",
      "",
      "- リンクの文字に脚注を付けた。",
      "",
      "### 直し方",
      "",
      "脚注、相互参照、引用は、リンクの外に書く。",
      "## G02129",
      "",
      "@table の src= は廃止予定です",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@table` の表のファイルのパスを `src=` で書いた。",
      "パスは最初の引数に書くのを正とし、`src=` は廃止する予定である。",
      "今は `src=` でも同じ表を組む。",
      "位置は `src=` の引数である。",
      "",
      "- メッセージ: `@table の src= は廃止予定です。パスを最初の引数に書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0184](adr/0184-table-positional-path.md)",
      "",
      "### 主な原因",
      "",
      "- v0.1.0-rc3 までの書き方に合わせて、`src=` でパスを書いた。",
      "",
      "### 直し方",
      "",
      "パスを最初の引数に書く。",
      "ほかの引数はそのままでよい。",
      "",
      "書き換える前：",
      "",
      "```",
      "@table src=data/sizes.tsv align=left,right,right",
      "```",
      "",
      "書き換えた後：",
      "",
      "```",
      "@table data/sizes.tsv align=left,right,right",
      "```",
      "",
      "## G02130",
      "",
      "@table にはファイルのパスを一つ書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@table` に表のファイルのパスを二つ以上書いた。",
      "位置引数のパスが二つ以上あるときと、位置引数のパスと `src=` の両方があるときである。",
      "どちらのパスが正しいかは処理系には分からないので、表を組まない。",
      "`src=` を書いたときは、その引数に [G02129](#g02129) の notice も出す。",
      "位置はコマンドの行である。",
      "",
      "- メッセージ: `@table にはファイルのパスを一つ書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0184](adr/0184-table-positional-path.md)",
      "",
      "### 主な原因",
      "",
      "- 最初の引数にパスを書き足したが、前からある `src=` を消し忘れた。",
      "- 二つの表を一つの `@table` に書いた。",
      "",
      "### 直し方",
      "",
      "組みたい表のファイルのパスを一つだけ、最初の引数に書く。",
      "二つの表を組むときは、`@table` を二つ書く。",
      "",
      "## G02131",
      "",
      "lang には言語のタグを一つ書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "インラインのコマンド `[lang]` かブロックコマンド `@lang` の引数が、言語のタグ一つではない。",
      "位置引数は、語か文字列で書いた言語のタグちょうど一つである。",
      "位置引数がない、二つ以上ある、キーワード引数がある、式やコマンドで書いた、のどれかである。",
      "`[lang]` は散文を区間なしで残し、`@lang` はブロックに言語を付けない。",
      "位置はコマンドである。",
      "",
      "- メッセージ: `lang には言語のタグを一つ書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0187](adr/0187-inline-language-switch.md)",
      "",
      "### 主な原因",
      "",
      "- `[lang: ...]` のように、タグを書き忘れた。",
      "- `[lang en fr: ...]` のように、二つの言語を書いた。",
      "",
      "### 直し方",
      "",
      "言語のタグを一つ書く（`[lang en: ...]`、`@lang fr`）。",
      "二つの言語の部分は、`[lang]` を二つに分けて書く。",
      "",
      "## G02132",
      "",
      "言語のタグの形が誤っています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[lang]` か `@lang` に書いた言語のタグが、BCP 47（RFC 5646）の形ではない。",
      "検査するのは形だけで、IANA の登録簿に載っているかは調べない。",
      "`[lang]` は散文を区間なしで残し、`@lang` はブロックに言語を付けない。",
      "位置はコマンドである。",
      "",
      "- メッセージ: `言語のタグの形が誤っています: <タグ>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0187](adr/0187-inline-language-switch.md)",
      "",
      "### 主な原因",
      "",
      "- `e_n` のように、区切りに `-` でない文字を使った。",
      "- `en-` のように、タグが `-` で終わる。",
      "- `123` のように、言語の副タグが英字ではない。",
      "",
      "### 直し方",
      "",
      "`ja`、`en-US`、`zh-Hant-TW` のように、BCP 47 の形で書く。",
      "",
      "## G02133",
      "",
      "図版の width が読めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@figure` の `width` が、寸法としても行長の割合としても読めないか、値が 0 である。",
      "回り込ませる図版も、回り込ませない図版も、回した図版（`rotate=true`）も対象である。",
      "図版は置かない。",
      "位置は `width` の引数で、プラグインが作った図版ではコマンドの呼び出しである。",
      "評価で報告するので、PDF、HTML、EPUB、プレーンテキストのどれを組んでも、`golem check` でも出る。",
      "dev と prod の両方でエラーである。",
      "",
      "- メッセージ: `図版の width が読めません。寸法（10zw、50mm など）か行長の割合（50% など）で書きます: <値>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0190](adr/0190-non-wrapping-figure-width.md)",
      "",
      "### 主な原因",
      "",
      "- 単位を書いていない（`width=50`）か、`mm`、`pt`、`Q`、`H`、`in`、`zw`、`%` のほかの単位（`em` など）を書いた。",
      "- 負の値（`width=-3zw`）か、0（`width=0zw`、`width=0%`）を書いた。",
      "",
      "### 直し方",
      "",
      "`width` を、`12zw`、`40mm` のような寸法か、`50%` のような行長の割合で書く。",
      "割合は、回り込ませない図版と回り込ませる図版では段の行長、回した図版では枠の行長に対する割合である。",
      "",
      "## G02134",
      "",
      "キャプションのないコードブロックと表への @nonumber は要りません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "キャプション（`@caption`）のないコードブロック（```` ``` ```` か `@listing`）か表（`|` の表か `@table`）に `@nonumber` を付けた。",
      "リスト番号と表番号を持つのはキャプションのあるコードブロックと表だけなので、キャプションのないものには、振らないでおく番号がない（表は [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。",
      "`@caption` と `@nonumber` のどちらを先に書いても同じく、そのブロックの属性をすべて当てた後で判定する。",
      "コードブロックと表は、`@nonumber` がないものとして組む。",
      "位置は `@nonumber` の行である。",
      "",
      "- メッセージ: `キャプションのないコードブロックは番号を持たないので、@nonumber は要りません`、`キャプションのない表は番号を持たないので、@nonumber は要りません`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0200](adr/0200-figures-and-listings-without-numbers.md)、[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)（表）",
      "",
      "### 主な原因",
      "",
      "- キャプションを付けるつもりで、`@caption` を書き忘れた。",
      "- 番号のない図版にならって、キャプションのないコードブロックか表にも `@nonumber` を書いた。",
      "",
      "### 直し方",
      "",
      "キャプションを付けるなら `@caption` を書く。",
      "キャプションが要らないなら `@nonumber` を消す。",
      "",
      "## G02135",
      "",
      "@column-widths の値が読めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "表の `@column-widths` の値が、`auto`、寸法（`mm`、`pt`、`Q`、`H`、`in`、`zw`）、割合（`%`）のどれとしても読めない（[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。",
      "0 の幅と、式で書いた値もこの誤りである。",
      "数の書き方は図版の `width` と同じである。",
      "読めない値ごとに一つ報告し、その `@column-widths` を捨てて、すべての列を `auto` として組む。",
      "位置は `@column-widths` の行である。",
      "",
      "- メッセージ: `@column-widths の値が読めません。auto、寸法（10zw、30mm など）、割合（50% など）で書きます: <値>`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)",
      "",
      "### 主な原因",
      "",
      "- 単位を書かなかったか、知らない単位を書いた。",
      "- 幅を 0 にした。",
      "- `[= ...]` の式で幅を書いた。",
      "",
      "### 直し方",
      "",
      "値を `auto`、`10zw` や `30mm` のような寸法、`25%` のような割合で書く。",
      "",
      "## G02136",
      "",
      "@column-widths の値の数が表の列の数と違います",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
