      "- 列を足すか除いたのに、`@column-widths` を直さなかった。",
      "",
      "### 直し方",
      "",
      "値を一つにするか、列の数と同じ数にする。",
      "幅を決めない列は `auto` と書く。",
      "## G02137",
      "",
      "定義されていない注の名前です",
