      "### 主な原因",
      "",
      "- 複数の文献を引く `[cite a b]` に、頁を書いた。",
      "",
      "### 直し方",
      "",
      "文献ごとに頁が要るときは、`[cite a page=5][cite b page=7]` のように、文献ごとに `[cite]` を分ける。",
      "",
      "## G02150",
      "",
      "cite のキーは名前か文字列で書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[cite ...]` の位置引数が、キーとして読めない（[docs/adr/0266](adr/0266-citation-locators-and-multiple-keys.md)）。",
      "キーは名前（`knuth1981`）か文字列（`\"knuth1981\"`）で書き、`[= ...]` で書くときは値が文字列でなければならない。",
      "数、真偽値、配列などの値はこのコードになり、引用は出力に何も置かない。",
      "",
      "- メッセージ: `cite のキーは名前か文字列で書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0266](adr/0266-citation-locators-and-multiple-keys.md)",
      "",
      "### 主な原因",
      "",
      "- `[cite [= 1]]` のように、文字列でない値をキーに書いた。",
      "",
      "### 直し方",
      "",
      "キーを名前か文字列で書く。",
      "配列のキーをまとめて書くときは、`*[式]` で展開する。",
      "",
      "## G02151",
      "",
      "cite には書誌データのキーを書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[cite]` にキーを一つも書かなかった（[docs/adr/0266](adr/0266-citation-locators-and-multiple-keys.md)）。",
      "引用は出力に何も置かない。",
      "",
      "- メッセージ: `cite には書誌データのキーを書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0266](adr/0266-citation-locators-and-multiple-keys.md)",
      "",
      "### 主な原因",
      "",
      "- `[cite]` や `[cite page=5]` のように、キーを書き忘れた。",
      "",
      "### 直し方",
      "",
      "引く文献のキーを書く。",
      "## G02152",
      "",
      "[shy] は引数を取りません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "ソフトハイフンのコマンド `[shy]` に、位置引数かキーワード引数を書いた。",
      "`[shy]` は引数を取らず、U+00AD（ソフトハイフン）の一字になる。",
      "誤りのある `[shy]` は何も出力しない。",
      "散文スロットを書いたときは、このコードではなく [G02038](#g02038) になる。",
      "位置は `[shy]` のコマンドである。",
      "",
      "- メッセージ: `shy は引数を取りません。[shy] とだけ書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.File`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- 分ける位置を引数で指定できると考えて、`[shy 3]` のように書いた。",
      "",
      "### 直し方",
      "",
      "語を分けてよい位置に `[shy]` だけを書く（`in[shy]com[shy]pre`）。",
      "",
      "## G02153",
      "",
      "@hyphenation-exceptions にはキーワード引数を書けません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "ファイルの設定の `@hyphenation-exceptions` に、キーワード引数を書いた。",
      "`@hyphenation-exceptions` は、言語のタグと例外の語を位置引数だけで取る。",
      "キーワード引数は捨て、ほかの引数はそのまま読む。",
      "位置は、キーワード引数のそれぞれである。",
      "",
      "- メッセージ: `@hyphenation-exceptions にはキーワード引数を書けません。言語のタグと語だけを書きます`",
      "- 段階とモジュール: 評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- `@hyphenation-exceptions lang=en ta-ble` のように、言語をキーワードで書いた。",
      "",
      "### 直し方",
      "",
      "`@hyphenation-exceptions en ta-ble` のように、言語のタグを最初の位置引数に書く。",
      "",
      "## G03001",
      "",
      "manifest.toml の誤りです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` が TOML として読めないか、スキーマに合わないか、出力ターゲットが一つもない。",
      "`[source]` と章の項目の `[source]` のキー（`paragraph-separator` など）の未知のキーと不正な値、同じファイルを章の配列に二度並べて適用される `[source]` の値が異なる場合も、この誤りとする。",
      "`[targets.pdf]` の `pdfa` が `\"2a\"` でない場合と、`pdfua` が `\"1\"` でない場合（文字列でない値を含む）も、この誤りとする（[docs/adr/0183](adr/0183-tagged-pdf-and-pdf-a.md)）。",
      "`[metadata]` の `creators` と `contributors` の `role` が役割の表の語でない場合、`name` が空の文字列の場合、`publisher-person` が空の文字列か改行を含む場合、`printings` の版か刷が 0 の場合（負の数は [G02103](#g02103)、[docs/adr/0102](adr/0102-natural-number-type.md)）、`printings` が版と刷の順に狭義に増えていない場合、`printings` の `date` が前の項目より前の場合も、この誤りとする。",
      "",
      "- メッセージ: `TOML の誤りです: <詳細>`、`@style-def の値が不正です: <詳細>`、`出力ターゲットが一つもありません`、`同じファイルを [source] の設定を変えて章に二度並べています: <パス>`、`章は、ファイルのパス、表、配列のどれかで書きます`、`役割は語で書きます。\"<符号>\" は \"<語>\" です`、`役割は <語の一覧> のどれかです: <値>`、`発行所は [metadata] の publisher に、発行人は publisher-person に書きます`、`name に空の文字列は書けません`、`publisher-person に空の文字列は書けません`、`publisher-person に改行は書けません`、`版と刷の番号は 1 以上の整数です`、`printings は版と刷の順に、同じ版と刷を二度書かずに並べます`、`printings の date が前の項目の date より前です`、`pdfa に書けるのは \"2a\" だけです: <値>`、`pdfua に書けるのは \"1\" だけです: <値>`、または TOML のスキーマの誤りの文言（`知らないキーです: <経路>.<キー>`、`必須のキーがありません: <経路>.<キー>`、`<経路> には<型>を書きます（<型>が書かれています）`、`[source]` の不正な値など）。TOML の誤りの詳細は、`文字列が閉じていません`、`閉じた表にキーを足しています: <キー>` などの日本語の文言である。経路は `metadata.title` や `chapters[0]` の形で書く。Golem の検査の文言には、`(chapters[0])` のように経路を後ろに添える。経路が空のとき（ファイルの最上位の誤り）は添えない。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）。位置は、スキーマの誤りと Golem が値の読み込みで調べる誤り（章の項目、`[source]` の値など）では誤った値の位置、TOML の構文の誤りではその誤りの位置、それ以外（出力ターゲットが一つもないなど）では `manifest.toml` の先頭である",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)（定めた）。[golem-cli ADR 0002](golem-cli/adr/0002-build-all-targets-by-default.md) が触れ、[docs/adr/0013](adr/0013-paragraph-separator.md) が `[source]` の誤りの条件を加えた。[golem-project ADR 0007](golem-project/adr/0007-toml-messages-in-japanese.md) が TOML の誤りの文言を日本語にした。[docs/adr/0033](adr/0033-colophon-contributors-and-printings.md) が役割、名前、発行人、刷の検査を加えた。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- TOML の文法を誤った。",
      "- キーの綴りか値の型を誤った。未知のキーは無視せずエラーにする。",
      "- 出力ターゲット（`[targets.*]`）を一つも書いていない。",
      "- `[source]` の値を誤った。`paragraph-separator` は `\"blank-line\"` か `\"line\"` と書く。",
      "- `role` に MARC relator の符号（`aut` など）を書いた。役割は `author` のような語で書く。",
      "- `role = \"publisher\"` と書いた。発行所は `[metadata]` の `publisher` に、発行人は `publisher-person` に書く。",
      "- `printings` の項目の順を誤ったか、同じ版と刷を二度書いた。",
      "",
      "### 直し方",
      "",
      "メッセージの示すキーと値を直す。",
      "ターゲットを一つ以上書く。",
      "",
      "## G03002",
      "",
      "ファイルがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "章や `@import` が指すファイルがない。",
      "`golem inspect` と `golem fmt` の引数のファイルがないか、通常のファイルでない（ディレクトリなど）ときも、この誤りとする（[golem-cli ADR 0007](golem-cli/adr/0007-inspect-output.md)）。",
      "このときの位置は引数のファイルの先頭である。",
      "プロジェクトのルートに `manifest.toml` がないときは、この誤りではなく [G03016](#g03016) とする。",
      "",
      "- メッセージ: `ファイルがありません: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）。位置は、章なら `manifest.toml` の先頭、`@import` ならその `@import` のブロック全体である",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- 章や `@import` のパスの綴りを誤ったか、ファイルを置いていない。",
      "- `golem inspect` か `golem fmt` に渡したパスの綴りを誤った。",
      "",
      "### 直し方",
      "",
      "パスの綴りとファイルの置き場所を確かめる。",
      "",
      "## G03003",
      "",
      "使えないパスです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "章や `@import` のパス、`manifest.toml` の `bibliography` のファイル、プラグインの `path`（[docs/adr/0109](adr/0109-local-plugin-path.md)）とデータ（`data`、[docs/adr/0105](adr/0105-plugin-data.md)）のパス、`[functions.requires]` の `file` のパスと `.emet` の要求 `file` と `File.read` のパス（[docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)）が、絶対パス、URL、またはプロジェクトのルートの外を指すパスである。",
      "`.emet` の中のパスは字面で検査し、位置はそのパスである。",
      "シンボリックリンクを解決した実体がルートの外にあるときも、この誤りとする。",
      "`bibliography` とプラグインのパスの誤りの位置は、`manifest.toml` の先頭である。",
      "",
      "- メッセージ: `絶対パスは使えません: <パス>`、`URL は使えません: <パス>`、`プロジェクトルートの外を指しています: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）。章と `@import` の位置は [G03002](#g03002) と同じである",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)、[docs/adr/0105](adr/0105-plugin-data.md)、[docs/adr/0109](adr/0109-local-plugin-path.md)",
      "",
      "### 主な原因",
      "",
      "- 章、`@import`、`bibliography`、プラグインの `path` や `data` のパスに、絶対パスか URL を書いた。",
      "- `..` でプロジェクトのルートの外を指した。",
      "",
      "### 直し方",
      "",
      "プロジェクトのルートからの相対パスで書き、ファイルをプロジェクトの中に置く。",
      "",
      "## G03004",
      "",
      "大文字と小文字だけが異なるパスです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "大文字と小文字だけが違う二つのパスを使った。",
      "大文字と小文字を区別しないファイルシステムで、結果が変わるためである。",
      "`.emet` の一つの要求の列の二つの `file`、`[functions.requires]` の `file` の二つのパス、シグネチャの `file` と `[functions.requires]` のパスも比べる（[docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)）。",
      "書いたパスで比べるので、どのファイルシステムでも同じ誤りになる。",
      "シンボリックリンクを解決した後のパスも比べる。",
      "",
      "- メッセージ: `大文字と小文字だけが異なるパスです: <後のパス> と <先のパス>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）。位置は、章なら `manifest.toml` の先頭、`@import` ならその `@import` のブロック全体である",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- 同じファイルを、大文字と小文字の違う二つの綴りで指した。",
      "",
      "### 直し方",
      "",
      "どちらかのパスに綴りをそろえる。",
      "",
      "## G03005",
      "",
      "import が循環しています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@import` が循環している。",
      "自分自身の import も含む。",
      "",
      "- メッセージ: `import が循環しています: <ファイル> → <ファイル> → ... → <最初のファイル>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）。位置は循環の最初のファイルの `@import` で、循環に含まれる各 `@import` を関連位置に載せる",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- `@import` が循環している。自分自身の import も含む。",
      "",
      "### 直し方",
      "",
      "共通の定義を別のファイルに切り出し、循環を断つ。",
      "",
      "## G03006",
      "",
      "style.toml の誤りです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` が TOML として読めないか、スキーマに合わないか、値が範囲の外にある。",
      "フォントのファイルの欠落には使わない（[G03010](#g03010)、[G08002](#g08002)）。",
      "判型（`[page]` の `size`）の誤りには使わない（[G03017](#g03017)）。",
      "自然数を読むキー（`[page.grid]` の `characters`、`lines`、`columns`、見出しの `lines`、`[index]` の `columns`）の負の数には使わない（[G02103](#g02103)、[docs/adr/0102](adr/0102-natural-number-type.md)）。",
      "マスターページの柱の内容の誤りには使わない（[G03014](#g03014)）。",
      "見出しの `running-head` には使わない（[G03019](#g03019)）。",
      "文字スタイルと段落スタイルの `kerning`、`tracking`、`proportional-metrics`、`baseline-shift` の誤りには使わない（[G03021](#g03021)）。",
      "フォントの役割、文字スタイル、段落スタイルの `features` の要素の誤りには使わない（[G03124](#g03124)）。",
      "隠しノンブルの `gutter` と `size` の関係の誤りには使わない（[G03029](#g03029)）。",
      "`@style-def` の名前と欄の誤りにも出る。",
      "誤りのある定義は捨てる。",
      "",
      "- メッセージ: `TOML の誤りです: <詳細>`、TOML のスキーマの誤りの文言、または値の検査の文言（`スタイルの名前は英小文字で始まり、英小文字、数字、- だけからなります: <名前>`、`番号の書式が不正です: <書式>`、`塗り足しには zw を使えません`、`<キー> に使えない値です: <値>（<許す値> のどれか）`、`columns が 2 以上のときは column-gap が要ります`、`space-between は 0 以上です`、`長さの書き方が不正です: <値>（13Q や 20mm のように書きます）`、`長さは文字列で書きます`、`cmyk は 0 から 100 までの整数四つです`、`見出しの段は 1 から 6 のどれかです: <段>`、`見出しの番号の書式の {<k>} は上の階層の番号です。階層 <段> の見出しには書けません: <書式>`、`罫線の <キー> を寸法として読めません: <値>`、`罫線の length は 0 より大きい寸法です`、`罫線の weight には zw を使えません`、`罫線の weight は 0 より大きい寸法です`、`罫線の <キー> は 0 以上の寸法です`、`罫線の style に使えない値です: <値>（<許す値> のどれか）`、`罫線の <キー> には zw を使えません`、`罫線の <キー> は 0 より大きい寸法です`、`罫線の <キー> は style が <線の種類> のときには書けません`、`[notes.rule] には length が要ります`、`[notes] の mark-size は 0 より大きい寸法で、zw では 1 以下です`、`[notes] の mark-format が正しくありません（<理由>）: <書式>`、`[notes] の mark-size と、mark-style <名前> の size（[character-styles.<定義>] に書いたもの）は一緒に書けません。mark-size を消します`、`[notes] の mark-size と、注の印の文字スタイル note-mark の size（[character-styles.<定義>] に書いたもの）は一緒に書けません。mark-size を消します`、`lines は 1 以上の整数です: <値>`、`罫線の length と end-indent は一緒に書けません`、`罫線には表か false を書きます。true は書けません`、`[notes.rule] には <キー> を書けません。段落スタイルと見出しの罫線だけのキーです`、`段落スタイル <名前> には rule-before と rule-after を書けません`、`段落スタイル <名前> には 0 でない indent と first-line-indent を書けません。キャプションと傍注は字下げをしません: <キー>`（`table` では「キャプションと傍注」が「表のセル」になる）、`[tables] の number には {n} などの差し込みを書きます: <書式>`、`段落スタイル <名前> の罫線の長さが 0 以下です。start-indent と end-indent を狭めてください`、`文字スタイルの wrap-mark は code と based-on で code に行き着く文字スタイルにだけ書けます: <名前>` など）。廃止した欄（`[emphasis]`、`[verse]`、`[sidenotes]` の `font` と `size`）は、書き換え先を示す文言になる。TOML のスキーマの誤りの文言は、`知らないキーです: page.bindng`、`必須のキーがありません: <経路>.<キー>`、`page.binding には文字列を書きます（整数が書かれています）` のように、文言の中に経路を書く。Golem の検査の文言には、`(page.grid.font-size)` のように経路を後ろに添え、経路が空のときは添えない。TOML の誤りの詳細も、`文字列が閉じていません`、`閉じた表にキーを足しています: page` などの日本語の文言である。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。位置は、スキーマの誤りと Golem が値の読み込みで調べる誤りでは誤った値の位置、TOML の構文の誤りではその誤りの位置である。二つのキーの組み合わせの誤りは、文言が直すよう求めているキーの値の位置（`columns` と `column-gap` では `columns`）に出す。読み込んだ後の検査では、直すべき値の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置、それもなければ `style.toml` の先頭である。ファイルの中の定義（`@style-def`）は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)（定めた）。条件を加えた ADR は [golem-project ADR 0004](golem-project/adr/0004-font-file-check-per-target.md)、[docs/adr/0005](adr/0005-character-and-paragraph-styles.md)、[docs/adr/0006](adr/0006-paragraph-indent.md)、[golem-pdf ADR 0004](golem-pdf/adr/0004-crop-marks-and-bleed.md)、[golem-layout ADR 0008](golem-layout/adr/0008-explicit-hyphens.md)、[golem-layout ADR 0009](golem-layout/adr/0009-ruby-placement.md)、[golem-driver ADR 0009](golem-driver/adr/0009-pdf-toc-page-numbers.md)、[golem-driver ADR 0010](golem-driver/adr/0010-caption-style.md)、[golem-driver ADR 0011](golem-driver/adr/0011-sidenote-font.md)、[docs/adr/0014](adr/0014-in-file-settings.md)、[golem-driver ADR 0021](golem-driver/adr/0021-hidden-folios.md)、[golem-driver ADR 0024](golem-driver/adr/0024-rule-spec-and-footnote-separator.md)、[golem-driver ADR 0028](golem-driver/adr/0028-rule-colour-and-style.md)、[golem-driver ADR 0025](golem-driver/adr/0025-note-mark-size-and-format.md)、[golem-driver ADR 0032](golem-driver/adr/0032-default-heading-styles.md)、[golem-driver ADR 0043](golem-driver/adr/0043-caption-sidenote-do-not-inherit-indent.md)、[docs/adr/0118](adr/0118-ref-page-numerals-in-vertical-text.md)（`[numbers]` の `ref-page`）、[ADR 0188](adr/0188-headings-beyond-level-3.md)（`[headings.N]` の階層と見出しの番号の書式の `{k}`）である。[golem-project ADR 0007](golem-project/adr/0007-toml-messages-in-japanese.md) が TOML の誤りの文言を日本語にした。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- TOML の文法を誤った。",
      "- キーの綴り、値の型、単位、列挙の値を誤った。",
      "- 値が範囲の外にある。",
      "- 文字スタイルの `position` に `\"normal\"`、`\"superscript\"`、`\"subscript\"` のほかの値を書いた（[ADR 0269](adr/0269-superscript-and-subscript.md)）。",
      "- 文字スタイルの `underline` か `strikethrough` に、`true`、`false`、表のほかの値を書いた。表に、罫線の長さと位置のキー（`length`、`space-before`、`space-after`、`start-indent`、`end-indent`、`keep-in-column`）か未知のキーを書いた。`weight`、`dash`、`gap` が寸法として読めないか 0 以下であるか、`offset` が寸法として読めない。`dash` と `gap` を、それを使わない線の種類に書いた（[ADR 0270](adr/0270-underline-and-strikethrough.md)）。",
      "- 廃止した欄（`[emphasis]`、`[verse]`、`[sidenotes]` の `font` と `size`）を書いた。",
      "- 段落スタイル `code` に、`font`、`size`、`background`、`padding`、`border`、`border-width`、`border-style`、`border-sides`、`border-radius` のほかのキー（`based-on` を含む）を書いた（[golem-driver ADR 0017](golem-driver/adr/0017-pdf-code-blocks.md)）。",
      "- 段落スタイルの `padding` か `border-radius` が負であるか、寸法として読めない。`background` か `border` に `true` を書いた（[docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)）。",
      "- 組み込みの段落スタイル `caption`、`sidenote`、`table` に、0 でない `indent`、`first-line-indent`、`end-indent` を書いた。キャプションと傍注と表のセルは字下げをしないためである。値が 0 なら誤りとせず、お知らせ [G03100](#g03100) を出す（[golem-driver ADR 0043](golem-driver/adr/0043-caption-sidenote-do-not-inherit-indent.md)、[docs/adr/0189](adr/0189-paragraph-alignment-spacing-and-end-indent.md)、[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。三つに書けないキーは、0 でない `indent`、`first-line-indent`、`end-indent`、`rule-before`、`rule-after` と、囲みの七つのキー（`background`、`padding`、`border`、`border-width`、`border-style`、`border-sides`、`border-radius`）である。目次の項目の `toc-1` から `toc-6` にも、囲みの七つのキーを書けない（[docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)）。",
      "- 段落スタイルの `align` に九つのほかの値を書いたか、`space-before` か `space-after` に負の数を、`end-indent` に負の長さを書いた（[docs/adr/0189](adr/0189-paragraph-alignment-spacing-and-end-indent.md)）。段落スタイル `code` に `align`、`space-before`、`space-after`、`end-indent` を書いた場合も同じである。",
      "- 段落スタイルの `border-width` を zw で書いたか、負の値を書いた（[golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md)）。",
      "- 段落スタイルの `border-style` に `solid`、`dashed`、`dotted` のほかの値を書いた。`border-sides` が空の配列か、同じ辺を二度含むか、`before`、`after`、`start`、`end` のほかの値を含む（[docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)）。",
      "- 囲み（`background` か `border`）を持つ段落スタイルに、`rule-before` か `rule-after` を書いた。`based-on` で引き継いだ場合を含む。メッセージは `段落スタイル <名前> には囲みと罫線を一緒に書けません` である（[docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)）。",
      "- 段落スタイルの `keep-with-next` に 0 から 5 のほかの整数を、`keep-first-lines` か `keep-last-lines` に 0 を、`keep-all-lines` に真偽値でない値を、`page-break` に `\"any\"`、`\"column\"`、`\"page\"`、`\"recto\"`、`\"verso\"` のほかの値を書いた。段落スタイル `code` にこれらのキーを書いた場合も同じである。負の整数は [G02103](#g02103) とする（[ADR 0261](adr/0261-keep-options-of-paragraph-styles.md)）。",
      "- 段落スタイルの `line-adjustment` に `\"pull-in-first\"` と `\"balanced\"` のほかの値を書いたか、`stretch-limit` に負の数か整数でない値を書いた。段落スタイル `code` にこれらのキーを書いた場合も同じである（[ADR 0274](adr/0274-prefer-pulling-in-and-limit-the-stretch-of-lines.md)）。",
      "- 段落スタイルの `shrink-order` か `stretch-order` に、配列でない値、文字列でも文字列の配列でもない要素、空の内側の配列、内側の配列の中の配列、`word-space`、`middle-dot`、`brackets`、`comma`、`full-stop`、`paragraph-start`、`japanese-western`、`between-characters` のほかの名前を書いたか、同じキーに同じ名前を二度書いた（二度めの位置）。段落スタイル `code` にこれらのキーを書いた場合も同じである（[ADR 0278](adr/0278-use-the-places-of-line-adjustment-in-the-order-of-jlreq.md)）。",
      "- `[composition]` の `number-unit-penalty` に −9999 から 10000 のほかの値か、整数でない値を書いた（[ADR 0275](adr/0275-keep-numbers-with-the-units-after-them.md)）。",
      "- 文字スタイルの `background` か `padding` を、`code` と `based-on` で `code` に行き着く文字スタイルのほかに書いた。文字スタイルの `background` に `true` を書いた。文字スタイルの `padding` が負であるか、寸法として読めない（[golem-driver ADR 0029](golem-driver/adr/0029-inline-code-background.md)）。",
      "- 文字スタイルの `wrap-mark` を、`code` と `based-on` で `code` に行き着く文字スタイルのほかに書いた。`wrap-mark` を文字列で書いていない（[golem-layout ADR 0034](golem-layout/adr/0034-line-breaks-between-japanese-characters-in-inline-code.md)）。",
      "- `[code]` か `[code.colors]` に未知のキーを書いた。`[code]` の `line-numbers` が真偽値でない。`[code]` の `number` が `{n}` などの差し込みを含まない。",
      "- `[hidden-folio]` の `size` か `gutter` を `zw` で書いたか、0 以下にしたか、寸法として読めない値にした。`pages` に `unnumbered` と `all` のほかの値を書いた（[golem-driver ADR 0021](golem-driver/adr/0021-hidden-folios.md)）。`gutter` が `size` の半分より小さい誤りは [G03029](#g03029) である。",
      "- 罫線の指定（`[notes.rule]`）で、`length` が寸法として読めないか 0 以下、`weight` が寸法として読めないか 0 以下か `zw`、`space-before` か `space-after` が寸法として読めないか負である。未知のキーを書いた。`[notes.rule]` に `length` を書いていない（[golem-driver ADR 0024](golem-driver/adr/0024-rule-spec-and-footnote-separator.md)）。",
      "- 罫線の指定で、`style` に線の種類の表にない値を書いた。`dash` か `gap` が寸法として読めないか、0 以下か、`zw` である。`dash` を `\"dashed\"` のほかの線の種類に、`gap` を `\"dashed\"`、`\"dotted\"`、`\"japanese-dots\"` のほかの線の種類に書いた。`color` を文字列で書いていない（[golem-driver ADR 0028](golem-driver/adr/0028-rule-colour-and-style.md)）。",
      "- 段落スタイルか `[headings.N]` の `rule-before`、`rule-after` に、表と `false` のほかの値（`true` を含む）を書いた。組み込みの段落スタイル `caption`、`sidenote`、`code` に書いた。`@style-def` に書いた。`length` と `end-indent` を一緒に書いた。`start-indent` と `end-indent` を引くと罫線の長さが 0 以下になる。`[notes.rule]` に `start-indent`、`end-indent`、`keep-in-column` を書いた（[golem-driver ADR 0027](golem-driver/adr/0027-paragraph-style-rules.md)）。",
      "- `[headings.N]` の N に 1 から 6 のほかの値を書いた。見出しの番号の書式に、その見出しの階層より小さくない `{k}` を書いた（`[headings.2]` の `{2}`、`[headings.1]` の `{1}` など）。図版、コードブロック、ノンブルの番号の書式に `{3}` から `{5}` を書いた（[ADR 0188](adr/0188-headings-beyond-level-3.md)）。",
      "- `[notes]` の `mark-format` に数の差し込みを書かなかったか、二つ以上書いたか、表にない差し込みか表記の名前を書いたか、`{{`、閉じていない `{`、対応のない `}`、誤ったエスケープ（`\\a`、末尾の `\\`）を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "- `[notes]` の `mark-size` と、`size` を持つ文字スタイルを指す `mark-style` を一緒に書いた。`mark-style` を書かずに `[character-styles.note-mark]` の `size` と `mark-size` を一緒に書いた場合も同じである（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "- 見出し、図版、コードブロック、ノンブルの番号の書式に、表にない差し込みか表記の名前、閉じていない `{`、対応のない `}`、誤ったエスケープを書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "",
      "### 直し方",
      "",
      "メッセージの示すキーと値を直す。",
      "廃止した欄は、メッセージの示す節に移す。",
      "",
      "## G03007",
      "",
      "style.toml にないマスターページです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の項目の `master` が、`style.toml` にないマスターページを指す。",
      "`style.toml` がないときは、`master` を書いた項目がすべて該当する。",
      "名前ごとに一つだけ出し、順序は章の順で名前が最初に現れた順である。",
      "原稿に構文の誤りがあるときは調べない。",
      "",
      "- メッセージ: `style.toml にないマスターページです: <名前>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver`）。位置は `manifest.toml` の先頭である",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)（定めた）。[golem-driver ADR 0003](golem-driver/adr/0003-pdf-heading-styles.md) が使用済みの番号として触れる",
      "",
      "### 主な原因",
      "",
      "- `manifest.toml` の章の `master` の綴りを誤った。",
      "- `style.toml` にマスターページを定義していない。",
      "",
      "### 直し方",
      "",
      "`style.toml` にマスターページを定義するか、名前の綴りを直す。",
      "",
      "## G03008",
      "",
      "style.toml にないフォントの役割です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "見出し、文字スタイル、段落スタイルの `font` が、`[fonts]` にない役割を指す。",
      "`@style-def` の `font` にも出る。",
      "誤りのある定義は捨てる。",
      "組み込みの段落スタイル `code` と文字スタイル `code` の `font` が既定の役割 `code` を指し、`[fonts.code]` がない場合は、この誤りとせず、本文の役割で組む（[G08008](#g08008)、[golem-driver ADR 0017](golem-driver/adr/0017-pdf-code-blocks.md)）。",
      "",
      "- メッセージ: `style.toml にないフォントの役割です: <役割>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。`style.toml` の検査の位置は、直すべき値（`font`、`size`、`first-line-indent`、`based-on`、`color`、`kerning` など）の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置である。ファイルの中の定義（`@style-def`）は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [golem-driver ADR 0003](golem-driver/adr/0003-pdf-heading-styles.md)（定めた）、[docs/adr/0005](adr/0005-character-and-paragraph-styles.md)（段落スタイルに広げた）、[docs/adr/0014](adr/0014-in-file-settings.md)（ファイルの中の定義に広げた）。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- 見出し、文字スタイル、段落スタイルの `font` に、`[fonts]` にない役割を書いた。",
      "",
      "### 直し方",
      "",
      "`[fonts.<役割>]` を定義するか、役割の名前を直す。",
      "",
      "## G03009",
      "",
      "@import の形が不正です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@import` の引数が `パス as 名前空間` の形でない。",
      "引数は、ちょうど三つの位置引数「語か文字列」「語 `as`」「語」の並びでなければならない。",
      "キーワード引数、式やコマンドの引数、引数の数の違いは、すべてこの誤りである。",
      "展開（`*[式]`、`**[式]`）を書いた `@import` もこの誤りである。",
      "プロジェクトの外のファイルを評価するときも、展開せずに書いたままの引数を調べるので、同じくこのコードになる（[docs/adr/0142](adr/0142-import-arguments-are-not-spread.md)）。",
      "展開の式は評価しないので、式の中の誤りは出さない。",
      "",
      "- メッセージ: `@import は「@import パス as 名前空間」の形で書きます`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Imports`）。プロジェクトの外のファイルを評価するときは、golem-eval の `Golem.Eval.File` が同じ関数で調べる。位置はその `@import` のブロック全体である",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)（定めた）、[docs/adr/0142](adr/0142-import-arguments-are-not-spread.md)。[golem-driver ADR 0003](golem-driver/adr/0003-pdf-heading-styles.md) と [golem-project ADR 0004](golem-project/adr/0004-font-file-check-per-target.md) が使用済みの番号として触れる",
      "",
      "### 主な原因",
      "",
      "- `@import` の引数を `パス as 名前空間` の形で書かなかった。",
      "",
      "### 直し方",
      "",
      "`@import vars.gm as v` のように書く。",
      "",
      "## G03010",
      "",
      "フォントのファイルがないので、HTML と EPUB に同梱しません",
      "",
      "- 重大度: dev では警告、prod ではエラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "HTML か EPUB を作るときに、`[fonts]` が指すフォントのファイルがない。",
      "そのフォントを同梱せず、`@font-face` も書かずに出力する。",
      "prod では HTML と EPUB を書かない。",
      "LSP は出さない。",
      "",
      "- メッセージ: `フォントのファイルがないので、HTML と EPUB に同梱しません: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver`）",
      "- ADR: [golem-project ADR 0004](golem-project/adr/0004-font-file-check-per-target.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` の `[fonts]` のパスの綴りを誤った。",
      "- フォントのファイルを置いていない。`golem new --no-fonts` で作ったプロジェクトで起きる。",
      "",
      "### 直し方",
      "",
      "フォントのファイルを置くか、`[fonts]` のパスを直す。",
      "",
      "## G03011",
      "",
      "段落スタイルの文字の大きさが版面の文字の大きさを超えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "段落スタイルの解決した `size` が、`[page.grid]` の文字の大きさを超える。",
      "",
      "- メッセージ: `段落スタイルの文字の大きさが版面の文字の大きさを超えます: <名前>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。`style.toml` の検査の位置は、直すべき値（`font`、`size`、`first-line-indent`、`based-on`、`color`、`kerning` など）の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置である。ファイルの中の定義（`@style-def`）は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [docs/adr/0005](adr/0005-character-and-paragraph-styles.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- 段落スタイルの `size` を、`[page.grid]` の文字の大きさより大きくした。`based-on` で継いだ値も含む。",
      "",
      "### 直し方",
      "",
      "段落スタイルの `size` を版面の文字の大きさ以下にする。",
      "",
      "## G03012",
      "",
      "段落の最初の行が版面の外に出ます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "段落スタイルの `indent` と `first-line-indent` の和が負になる。",
      "",
      "- メッセージ: `段落の最初の行が版面の外に出ます。indent と first-line-indent の和を 0 以上にしてください: <名前>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。`style.toml` の検査の位置は、直すべき値（`font`、`size`、`first-line-indent`、`based-on`、`color`、`kerning` など）の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置である。ファイルの中の定義（`@style-def`）は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [docs/adr/0006](adr/0006-paragraph-indent.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- ぶら下げのために負の `first-line-indent` を書いたが、`indent` が足りない。",
      "",
      "### 直し方",
      "",
      "ぶら下げの分だけ `indent` を大きくし、`indent` と `first-line-indent` の和を 0 以上にする。",
      "",
      "## G03013",
      "",
      "style.toml のスタイルの参照が不正です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`based-on` が存在しないスタイルを指すか、循環するか、`body` に `based-on` があるか、文字スタイルの `color` が `[color.swatches]` にない。",
      "罫線の指定の `color` が `[color.swatches]` にない場合も、この誤りとする。",
      "正規表現スタイルの `style` が文字スタイルにないか、`@style-def regex` の段落スタイルがない場合も、この誤りとする。",
      "`[notes]` の `mark-style` か `body-mark-style` が文字スタイルにない場合も、この誤りとする（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "段落スタイルの `aki-set` と、アキ量のセットの `based-on` が存在しないセットを指すか、セットの `based-on` が循環する場合も、この誤りとする。",
      "",
      "- メッセージ: `style.toml のスタイルの参照が不正です: <理由>`（ファイルの中の定義では `@style-def のスタイルの参照が不正です: <理由>`）。正規表現スタイルの理由は `正規表現スタイルの文字スタイルがありません: <名前>` か `正規表現スタイルの段落スタイルがありません: <名前>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。`style.toml` の検査の位置は、直すべき値（`font`、`size`、`first-line-indent`、`based-on`、`color`、`kerning` など）の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置である。ファイルの中の定義（`@style-def`）は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [docs/adr/0005](adr/0005-character-and-paragraph-styles.md)（正規表現スタイルの参照は [docs/adr/0015](adr/0015-regex-styles.md)、アキ量のセットの参照は [docs/adr/0019](adr/0019-aki-settings.md)）。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- `based-on` が存在しないスタイルを指す。",
      "- `based-on` が循環する。",
      "- `body` に `based-on` を書いた。",
      "- 文字スタイルの `color` が `[color.swatches]` にない。",
      "- 文字スタイルの `background` が `[color.swatches]` にない（[golem-driver ADR 0029](golem-driver/adr/0029-inline-code-background.md)）。",
      "- 文字スタイルの `underline` か `strikethrough` の `color` が `[color.swatches]` にない（[ADR 0270](adr/0270-underline-and-strikethrough.md)）。",
      "- 正規表現スタイルの `style` に、組み込みにも `style.toml` にも同じファイルの `@style-def character` にもない文字スタイルを書いた。",
      "- `@style-def regex` の二つ目の引数に、ない段落スタイルを書いた。",
      "- `[notes]` の `mark-style` か `body-mark-style` に、組み込みにも `style.toml` にもない文字スタイルを書いた。理由は `[notes] の mark-style の文字スタイルがありません: <名前>` か `[notes] の body-mark-style の文字スタイルがありません: <名前>` である。`[notes]` は本に一つなので、`@style-def` の文字スタイルは指せない。",
      "- 段落スタイルの `aki-set` か、`[aki-sets.<名前>]` の `based-on` が、存在しないセットを指す。",
      "- `[aki-sets.<名前>]` の `based-on` が循環する。",
      "- 段落スタイルの `based-on` に `code` を書いた。`code` はほかの段落スタイルの元にならない（[golem-driver ADR 0017](golem-driver/adr/0017-pdf-code-blocks.md)）。",
      "- 段落スタイルの `background` が `[color.swatches]` にない（[docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)）。",
      "- 段落スタイルの `border`、`[code]` の `line-number-color`、`highlight`、`added`、`removed`、`[code.colors]` の値が `[color.swatches]` にない（[golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md)）。",
      "- 罫線の指定（`[notes.rule]`）の `color` が `[color.swatches]` にない。メッセージの理由は `[notes.rule] の color のスウォッチがありません: <名前>` である（[golem-driver ADR 0028](golem-driver/adr/0028-rule-colour-and-style.md)）。",
      "- 段落スタイルか見出しの罫線の `color` が `[color.swatches]` にない。理由は `段落スタイル <名前> の罫線の color のスウォッチがありません: <名前>` か `見出し <階層> の罫線の color のスウォッチがありません: <名前>` である（[golem-driver ADR 0027](golem-driver/adr/0027-paragraph-style-rules.md)、[golem-driver ADR 0028](golem-driver/adr/0028-rule-colour-and-style.md)）。",
      "",
      "### 直し方",
      "",
      "理由の示すスタイルの `based-on`、`color`、`aki-set`、正規表現スタイルの `style` か段落スタイルの名前、アキ量のセットの `based-on` を直す。",
      "誤りのある正規表現スタイルの組だけを捨て、ほかの組は適用する。",
      "",
      "## G03014",
      "",
      "柱の内容が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` のマスターページの `running-head` の内容が、決まった語彙のどれでもないか、書式が正しくないか、書き方の組み合わせが正しくない。",
      "内容は `content` に一つ書くか、`even` と `odd` の両方に書く。",
      "値は語彙の文字列か、書式の文字列の配列である。",
      "位置は誤った値の位置である。",
      "",
      "- メッセージ: 語彙と組み合わせの誤りは `柱の内容が正しくありません: <値>。heading.<階層>.short か heading.<階層>.numbered（末尾に .last を付けられます）、title、none のどれかを、content に一つ、または even と odd の両方に書いてください`。組み合わせの誤りでは、`<値>` に書いた欄と値を並べ、どれも書いていなければ `（なし）` とする。書式の誤りは `柱の書式が正しくありません: <理由>`。どちらも誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [golem-driver ADR 0014](golem-driver/adr/0014-running-heads.md)、[golem-driver ADR 0022](golem-driver/adr/0022-running-head-formats.md)、[ADR 0188](adr/0188-headings-beyond-level-3.md)（見出しの階層を 1 から 6 に限った）",
      "",
      "### 主な原因",
      "",
      "- 内容の値の綴りを誤った（`heading.1.long`、`chapter` など）。",
      "- 見出しの階層に 0、7 以上、数でないものを書いた。階層は 1 から 6 である（[ADR 0188](adr/0188-headings-beyond-level-3.md)）。",
      "- 書式を配列でなく文字列で書いた（`\"{meta.title}　{heading.1.short}\"`）。",
      "- 書式の `{` を閉じていないか、文字の `}` を `\\}` と書いていないか、`{}` を書いたか、`\\` の後に `{`、`}`、`\\` のほかの字を書いたか、行の末尾に `\\` を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "- 差し込みに表記を書いた（`{heading.1.short:kanji}`）。",
      "- 表にない差し込み（`{heading.1.long}`、`{meta.author}`、`{chapter}` など）か、配列の `{meta.creators}` を書いた。",
      "- 空の配列、空の文字列の行、改行を含む行、文字列でない行を書いた。",
      "- `content` と `even` または `odd` を一緒に書いた。",
      "- `even` と `odd` の片方だけを書いた。",
      "- 位置だけを書き、内容を書かなかった。",
      "",
      "### 直し方",
      "",
      "`content = \"heading.1.short\"` のように両方のページの内容を一つ書くか、`even = \"title\"` と `odd = \"heading.1.short\"` のように左右のページの内容を両方書く。",
      "書式は `content = [\"{meta.title}　{heading.1.short}\"]` のように文字列の配列で書き、配列の要素ごとに一行とする。",
      "柱を出さないページには `none` を書くか、`running-head` のないマスターページを使う。",
      "",
      "## G03015",
      "",
      "正規表現を解釈できません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "正規表現スタイルの `pattern` が、Golem の正規表現の方言（InDesign の方言の部分集合）にない構文を含むか、正規表現として誤っている。",
      "部分集合の外の構文は、黙って別の意味に読まずにこの誤りとする。",
      "",
      "- メッセージ: `正規表現を解釈できません: <理由>（<段落スタイル> の <n> 番目の正規表現の <位置> 字目）`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`、照合器は golem-regex の `Golem.Regex`）。`style.toml` の検査の位置は、その正規表現スタイルの `pattern` の値の位置である。ファイルの中の `@style-def regex` は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその行になる",
      "- ADR: [docs/adr/0015](adr/0015-regex-styles.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- 後方参照（`\\1`、`\\k<...>`）、名前付きの群、アトミックな群、所有的な量指定子（`*+` など）、条件、コメントの群を書いた。",
      "- 先頭でない位置に `(?i)` を書いたか、ほかのフラグ（`(?s)`、`(?m)`、`(?x)`、`(?-i)`）を書いた。",
      "- 方言の表にない英字のエスケープ（`\\h`、`\\Q`、`\\A` など）か、文字体系の `\\p{Han}` を書いた。",
      "- 長さが一つに決まらない後読み（`(?<=a+)` など）を書いた。",
      "- InDesign の `~` のメタ文字（`~m` など）を写した。",
      "- 括弧が閉じていないか、範囲の両端が逆か、`{n,m}` の `n` が `m` より大きい。",
      "- 量指定子の展開を含めて、照合のプログラムが 10000 命令を超えたか、繰り返しの回数に 65535 を超える数を書いた（メッセージは `繰り返しの回数が上限の 65535 回を超えています`）。",
      "",
      "### 直し方",
      "",
      "理由と位置の示す箇所を直す。",
      "文字の `~` は `\\~` と書く。",
      "和文の文字体系は `[\\x{4E00}-\\x{9FFF}]` のように符号位置の範囲で書く。",
      "長さの異なる候補を持つ後読みは、候補ごとの後読みに分けて並べる（`(?<=ab|c)x` は `(?:(?<=ab)|(?<=c))x` と書く）。",
      "`@style-def regex` の文字列の中では、正規表現の `\\` を `\\\\` と書く。",
      "",
      "## G03016",
      "",
      "manifest.toml がありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "プロジェクトのルートに `manifest.toml` がない。",
      "章や `@import` が指すファイルがないときは [G03002](#g03002) とする。",
      "",
      "- メッセージ: `manifest.toml がありません`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）。ファイルがないので、位置は表示されない",
      "- ADR: [golem-project ADR 0006](golem-project/adr/0006-project-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- プロジェクトのルートでない場所で `golem` を実行した。",
      "- `manifest.toml` を置いていないか、名前の綴りを誤った。",
      "",
      "### 直し方",
      "",
      "`golem` をプロジェクトのルートで実行しているかを確かめる。",
      "新しいプロジェクトは `golem new` で作る。",
      "",
      "## G03017",
      "",
      "判型が不正です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[page]` の `size` が、判型の表の名前でも、正しい `{ width, height }` でもない。",
      "位置は `size` の値の位置である。",
      "",
      "- メッセージ: `未知の判型です: <名前>。表にない判型は size = { width = \"…\", height = \"…\" } で書きます`、`判型の width と height はどちらも必須です`、`判型には zw を使えません`、`判型の幅と高さは 0 より大きい寸法です`、または未知のキーと寸法の誤りの TOML のスキーマの文言。どれも誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [golem-project ADR 0005](golem-project/adr/0005-page-size-by-dimensions.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- 判型の表にない名前を書いたか、名前の綴りを誤った。",
      "- `{ width, height }` の片方を書き忘れた。",
      "- 寸法に `zw` を使ったか、0 以下の値を書いた。",
      "",
      "### 直し方",
      "",
      "表の名前（`\"A4\"`、`\"A5\"`、`\"A6\"`、`\"B5\"`、`\"B6\"`、`\"四六判\"`、`\"菊判\"`、`\"新書判\"`、`\"mass-market\"`）を書くか、`size = { width = \"148mm\", height = \"210mm\" }` のように寸法で書く。",
      "単位は `mm`、`pt`、`Q`、`H`、`in` とし、`zw` は使わない。",
      "",
      "## G03018",
      "",
      "マスターページの位置が不正です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[masters.<名前>]` の `running-head` か `folio` の `position` が、`top-outside`、`top-inside`、`top-center`、`bottom-outside`、`bottom-inside`、`bottom-center` のどれでもない。",
      "`style.toml` を読むときに検査するので、ターゲットにかかわらず、`golem check` と LSP も報告する。",
      "位置は `position` の値の位置である。",
      "",
      "- メッセージ: `未知の位置です: <位置>`。誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- `position` の綴りを誤った。",
      "- `middle` や `top` のように、表にない位置を書いた。",
      "",
      "### 直し方",
      "",
      "`position` に上の 6 つのどれかを書く。",
      "",
      "## G03019",
      "",
      "見出しの running-head は廃止しました",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[headings.<階層>]` に `running-head` を書いた。",
      "柱に使う見出しは、マスターページの `running-head` の内容で決める。",
      "",
      "- メッセージ: `[headings.<l>] の running-head は廃止しました。柱に使う見出しは [masters.<名前>] の running-head の content で指定してください`。誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [golem-driver ADR 0014](golem-driver/adr/0014-running-heads.md)",
      "",
      "### 主な原因",
      "",
      "- 以前の `style.toml` の `[headings.1]` の `running-head = true` が残っている。",
      "",
      "### 直し方",
      "",
      "`[headings.<階層>]` の `running-head` の行を消し、マスターページの `running-head` に `content = \"heading.1.short\"` のように柱に出す見出しの階層を書く。",
      "",
      "## G03020",
      "",
      "アキの量の指定が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[aki-sets.<名前>]` か、寸法の欄に書いたアキの量が正しくない。",
      "`[aki-sets]` の中の誤りは、すべてこのコードになる。",
      "ファイルの中の段落スタイルの定義（`@style-def`）の寸法の欄も同じである。",
      "",
      "- メッセージ: `アキの量の指定が正しくありません: <理由>`。理由は `アキの量として読めません: <値>`、`未知のクラスの名前です: <名前>`、`line-end は after にだけ書けます`、`<名前> は before にだけ書けます`、`minimum、optimum、maximum の順に小さくない値を書きます`、`組み込みのアキ量のセットと同じ名前です。…`、`アキの量の名前と百分率は、アキの量を書く欄でだけ使えます。…` などである。誤った箇所の経路を添える。`[aki-sets]` の中の型の誤りは、TOML のスキーマの文言になる。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。位置は誤った値の位置であり、組み込みのセットと同じ名前のセットではそのセットの表の見出しの位置である。`@style-def` の寸法の欄は評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0019](adr/0019-aki-settings.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- 規則の `optimum`、`minimum`、`maximum` に、読めない量や負の量を書いた。",
      "- `minimum` が `optimum` より大きいか、`optimum` が `maximum` より大きい。",
      "- `before` と `after` に未知のクラスの名前を書いた。",
      "- `line-end` を `before` に、`line-start` か `paragraph-start` を `after` に書いた。",
      "- 組み込みのセット（`gyomatsu-yakumono-hankaku`、`gyomatsu-yakumono-zenkaku`）と同じ名前の節を書いた。",
      "- `indent = \"二分\"` のように、アキの量の名前や百分率を寸法の欄に書いた。",
      "",
      "### 直し方",
      "",
      "量は `\"四分\"`、`\"0.25zw\"`、`\"25%\"` のように書き、`minimum <= optimum <= maximum` にする。",
      "クラスの名前は仕様書の表のとおりに書く。",
      "組み込みのセットを変えたいときは、`based-on` で引き継いだ別の名前のセットを作る。",
      "寸法の欄には `\"0.5zw\"` や `\"2mm\"` のように寸法を書く。",
      "",
      "## G03021",
      "",
      "文字の送りの欄の値が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "文字スタイルか段落スタイルの `kerning`、`tracking`、`proportional-metrics`、`baseline-shift`、`punctuation-width` の値が正しくない。",
      "`style.toml` の `[character-styles.<名前>]` と `[paragraph-styles.<名前>]` にも、ファイルの中の定義（`@style-def`）にも出る。",
      "`kerning = \"optical\"` もこのコードになる。",
      "オプティカルカーニングは v2 以降に回した。",
      "",
      "- メッセージ: `<欄> の値が正しくありません: <値>`。`tracking` の範囲の外では `（-1000 から 10000 までです）` を添える。`kerning = \"optical\"` は `v1 ではオプティカルカーニングを使えません（<文字スタイル|段落スタイル> <名前> の kerning）`。値の型の誤りは、`character-styles.<名前>.kerning には文字列を書きます（整数が書かれています）` のように文言の中に経路を書く（`@style-def` では経路は `kerning` だけになる）。そのほかの文言には誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。`style.toml` の検査の位置は、直すべき値（`font`、`size`、`first-line-indent`、`based-on`、`color`、`kerning` など）の位置であり、その値が書かれていなければそのスタイルなどの表の見出しの位置である。ファイルの中の定義は評価（golem-eval の `Golem.Eval.Settings`）が同じ検査をし、位置はその `@style-def` の行になる",
      "- ADR: [docs/adr/0020](adr/0020-indesign-character-features.md)、`punctuation-width` は [ADR 0302](adr/0302-full-width-glyphs-for-punctuation-and-boxes-for-narrower-ones.md)。[golem-project ADR 0007](golem-project/adr/0007-toml-messages-in-japanese.md) が値の型の誤りの文言を日本語にした。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- `kerning` に `metrics`、`japanese-equal-width`、`none` のほかの値を書いた。",
      "- `kerning = \"optical\"` と書いた。",
      "- `tracking` が -1000 から 10000 までの整数でない。",
      "- `proportional-metrics` が真偽値でない。",
      "- `baseline-shift` が `\"1pt\"` や `\"-0.25zw\"` のような寸法として読めない。",
      "- `punctuation-width` が `\"full-width\"` でも `\"font\"` でもない。",
      "",
      "### 直し方",
      "",
      "`kerning` は `metrics`、`japanese-equal-width`、`none` のどれかにする。",
      "オプティカルカーニングの代わりには `metrics` を使う。",
      "`tracking` は -1000 から 10000 までの整数（文字の大きさの 1/1000 が単位）で、`proportional-metrics` は `true` か `false` で、`baseline-shift` は符号付きの寸法で、`punctuation-width` は `\"full-width\"` か `\"font\"` で書く。",
      "",
      "## G03022",
      "",
      "リストの書式が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[lists]` の `bullets`、`numbers`、`gap` のどれかが正しくない。",
      "メッセージがどの欄の誤りかを示す。",
      "",
      "- メッセージ: `[lists] の <欄> が正しくありません: <理由>`。理由は `空の配列です`、`空の文字列があります`、`番号の差し込みがありません`、`番号の差し込みが二つ以上あります`、`表にない差し込みです: {x}`、`表にない表記です: {n:x}。…`、`閉じていない { があります。文字の { は \\{ と書きます`、`寸法として読めません`、`負の寸法です` など。誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。位置は誤ったキーの値の位置である",
      "- ADR: [golem-driver ADR 0013](golem-driver/adr/0013-list-indents.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- `bullets` か `numbers` を空の配列にしたか、空の文字列を書いた。",
      "- `numbers` の書式に番号の差し込みを書かなかったか、二つ以上書いたか、表にない差し込みか表記の名前を書いた。",
      "- 文字の `{` と `}` を、`\\{` と `\\}` と書かなかったか、`\\` の後に `{`、`}`、`\\` のほかの字を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "- `gap` が寸法として読めないか、負である。",
      "",
      "### 直し方",
      "",
      "`bullets` には印の文字列を、`numbers` には `\"{n}.\"` や `\"({n:lower-alpha})\"` のように差し込みをちょうど一つ含む書式を、一つ以上書く。",
      "差し込みは `{n}` か `{n:<表記>}` にし、表記は docs/specifications.md の表記の表の名前（`arabic`、`kanji`、`circled` など）にする。",
      "`gap` は `\"0.5zw\"` のように 0 以上の寸法で書く。",
      "",
      "## G03023",
      "",
      "style.toml がないので、既定の体裁で組みます",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "プロジェクトルートに `style.toml` がない。",
      "`style.toml` がなくても HTML、EPUB、プレーンテキストは組めるので、既定の体裁で組まれていることに気づきにくい。",
      "PDF はフォントの設定がないので [G08007](#g08007) で止まるが、そのときもこのお知らせを出す。",
      "位置は `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `style.toml がないので、既定の体裁で組みます`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver`）",
      "- ADR: [golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` を置かずにプロジェクトを作った。",
      "- `style.toml` を別の名前で保存した、または別のディレクトリに置いた。",
      "",
      "### 直し方",
      "",
      "既定の体裁でよいなら、直す必要はない。",
      "`silence-notices` に `\"G03023\"` を加えると、このお知らせを出さなくなる。",
      "体裁を決めるなら、プロジェクトルートに `style.toml` を置く。",
      "`golem new` で作ったプロジェクトの `style.toml` が雛形になる。",
      "",
      "## G03024",
      "",
      "抑制の一覧に抑制できないコードがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[diagnostics]` の抑制の一覧（`silence-notices` か `silence-info`）に、その一覧では抑制できないコードを書いた。",
      "`silence-notices` に書けるのはお知らせのコードだけであり、`silence-info` に書けるのは情報のコードだけである。",
      "エラーと警告のコード、廃止したコード、存在しないコード、もう一方の一覧に書くコード、コードの形でない文字列（`\"g262\"`、`\"all\"`、4 桁の古い形の `\"G0262\"` など）はこのエラーになる。",
      "抑制できないことを、黙って無視せずに伝える。",
      "位置は一覧の値の中のそのコードである。",
      "誤った要素が複数あれば、それぞれに出す。",
      "",
      "- メッセージ: `抑制できるのはお知らせのコードだけです: <コード>`（`silence-notices` の誤り。情報のコードなら、後に `（情報のコードは silence-info に書きます）` を添える）、`silence-info に書けるのは情報のコードだけです: <コード>`（`silence-info` の誤り。お知らせのコードなら、後に `（お知らせのコードは silence-notices に書きます）` を添える）、`診断のコードは大文字の G か E の後に 5 桁の数字を続けて書きます: <文字列>`、`診断のコードは文字列で書きます`。どのメッセージにも、[G03001](#g03001) と同じく ` (diagnostics.silence-notices[0])` のように経路を後ろに添える（[golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md)）",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）",
      "- ADR: [golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)、[docs/adr/0061](adr/0061-five-digit-diagnostic-codes.md)（コードの形）、[docs/adr/0104](adr/0104-info-severity.md)（`silence-info` と一覧の取り違え）",
      "",
      "### 主な原因",
      "",
      "- 警告やエラーを止めるつもりで、そのコードを書いた。",
      "- お知らせのコードを `silence-info` に、情報のコードを `silence-notices` に書いた。",
      "- Golem のバージョンを上げて、書いてあったお知らせのコードが廃止になったか、情報に移った（G07047 など）。",
      "- コードを小文字で書いた。",
      "- コードを 4 桁の古い形で書いた。",
      "",
      "### 直し方",
      "",
      "メッセージがもう一方の一覧を示していれば、そのコードをその一覧に移す。",
      "そうでなければ、そのコードを一覧から消す。",
      "エラーと警告は抑制できないので、原因を直す。",
      "コードは大文字の `G` か `E` の後に 5 桁の数字を続けて書く。",
      "4 桁の古いコードは、段階の 2 桁の後に `0` を一つ足して 5 桁にする（`G0262` は `G02062`）。",
      "一覧の値そのものが配列でない場合（`silence-notices = \"all\"` など）は [G03001](#g03001) になる。",
      "すべてのお知らせを一度だけ止めたい場合は、コマンドに `--no-notices` を付ける。",
      "",
      "## G03025",
      "",
      "[index] の値が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[index]` の `columns` が 1 以上の整数でないか、`column-gap` が寸法として読めないか負であるか、`section-headings` が真偽値でない（[docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)）。",
      "位置はその値である。",
      "`[index]` の未知のキーは [G03006](#g03006) である。",
      "",
      "- メッセージ: `[index] の columns は 1 以上の整数です`、`[index] の column-gap が正しくありません`、`[index] の section-headings は真偽値です` のいずれか。誤った箇所の経路を添える。",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [docs/adr/0025](adr/0025-index-columns.md)。位置は [golem-project ADR 0008](golem-project/adr/0008-style-toml-value-positions.md) が定めた",
      "",
      "### 主な原因",
      "",
      "- `columns` に 0 や負の数、小数、文字列（`\"2\"`）を書いた。",
      "- `column-gap` に負の寸法か、単位のない値を書いた。",
      "- `section-headings` に `\"false\"` のような文字列を書いた。",
      "",
      "### 直し方",
      "",
      "`columns` は `2` のように 1 以上の整数で、`column-gap` は `\"2zw\"` のように 0 以上の寸法で、`section-headings` は `true` か `false` で書く。",
      "",
      "## G03026",
      "",
      "参考文献のファイルを読めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `bibliography` に並べたファイルがないか、JSON として読めないか、最上位が配列でない。",
      "重大度はプロファイルで変わらない。",
      "位置は `manifest.toml` の先頭である。",
      "`Manifest` が値の位置を持たないためであり、[G03002](#g03002) と同じ扱いである。",
      "パスの形の誤り（URL、絶対パス、ルートの外）は [G03003](#g03003) とする。",
      "読めなかったファイルの項目はないものとして評価を続けるので、そのファイルの文献を引く `[cite ...]` には [G02021](#g02021) も出る。",
      "G03026 はそれらの後に並ぶ。",
      "",
      "- メッセージ: `参考文献のファイルがありません: <パス>`、`参考文献のファイルを JSON として読めません: <パス>（<aeson の文言>）`、`参考文献のファイルは CSL-JSON の配列で書きます: <パス>`。aeson の文言は英語のままである",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.loadBibliography`）。`golem check` とどのターゲットのビルドも出す",
      "- ADR: [golem-doc ADR 0004](golem-doc/adr/0004-bibliography-formatting.md)",
      "",
      "### 主な原因",
      "",
      "- `bibliography` のパスの綴りを誤ったか、ファイルを置いていない。",
      "- 文献管理ソフトから書き出したファイルが途中で切れているか、JSON でない形式（BibTeX など）で書き出した。",
      "- 項目を一つだけ書くつもりで、`[` と `]` で囲まずにオブジェクトを書いた。",
      "",
      "### 直し方",
      "",
      "パスとファイルの置き場所を確かめ、ファイルを CSL-JSON の配列（`[{\"id\": ...}, ...]`）で書く。",
      "",
      "## G03027",
      "",
      "章末の注の番号が章の中で重なります",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "注を章の末尾にまとめる出力で、章の注の一覧の中に同じ番号が二度現れる。",
      "`[notes]` の `numbering` が `\"file\"` で、マニフェストの二つ以上のファイルからなる章の、二つ以上のファイルに注があるときに出る。",
      "注を章の末尾にまとめる出力は、`placement = \"chapter-end\"` の PDF と、`placement` によらず HTML、EPUB、プレーンテキストである。",
      "ターゲットが PDF だけで `placement` が `\"page-foot\"` なら出さない。",
      "出力は止めず、重なった番号のまま組む。",
      "HTML と EPUB では、注の id に章の中のファイルの順番を入れて（`note-2-1` など）、一つの文書の中で id が重ならないようにする。",
      "",
      "- メッセージ: `章末の注の番号が章の中で重なります（<章の最初のファイル>）。[notes] の numbering を \"chapter\" にしてください`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.chapterNoteDiagnostics`）。位置は、その章で注を持つ二つ目のファイルの最初の注である。`golem check` とビルドが出す",
      "- ADR: [golem-driver ADR 0026](golem-driver/adr/0026-chapter-end-notes.md)",
      "",
      "### 主な原因",
      "",
      "- 一つの章を複数のファイルに分け、`[notes]` の `numbering` を `\"file\"` にした。",
      "",
      "### 直し方",
      "",
      "`[notes]` の `numbering` を `\"chapter\"`（既定）か `\"book\"` にする。",
      "",
      "## G03028",
      "",
      "manifest.toml に出力に書けない文字があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の文字列の値（`[metadata]` の `title`、`publisher`、`creators` の `name` など、どのテーブルの文字列も）に、出力に書けない文字がある。",
      "出力に書けない文字は、U+0000 から U+001F のうちタブ、改行、復帰以外と、U+FFFE、U+FFFF、サロゲートの符号位置である（[G02089](#g02089) と同じ）。",
      "TOML の文字列に生の制御文字は書けないので、これに当たるのは `\\u0001` のようなエスケープである。",
      "スキーマの検査の前に検査し、一つでもあればマニフェストを読まない。",
      "一つの文字列に複数あれば最初の一つを述べ、文字列ごとに一つ出す。",
      "位置は、その値の TOML の位置である。",
      "dev と prod の両方でエラーであり、LSP も同じく出す。",
      "原稿の文字列は [G02089](#g02089)、参考文献の CSL-JSON のファイルは [G03108](#g03108) とする。",
      "",
      "- メッセージ: `<キーの経路> に出力に書けない文字（<符号位置>）があります`（例: `metadata.title に出力に書けない文字（U+0001）があります`）",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）",
      "- ADR: [docs/adr/0042](adr/0042-control-characters-and-glob-metacharacters.md)",
      "",
      "### 主な原因",
      "",
      "- 書名や著者名に、`\\u0001` のような制御文字のエスケープを書いた。",
      "",
      "### 直し方",
      "",
      "メッセージの経路の値から、その文字のエスケープを消す。",
      "",
      "## G03029",
      "",
      "隠しノンブルが仕上がりの線を越えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[hidden-folio]` の `gutter` が `size` の半分より小さい（`2 × gutter < size`）。",
      "隠しノンブルの数字の列は、ノドの仕上がりの線から `gutter` の距離にある中心線から、左右に `size` の半分ずつの幅を持つとして測るので、列がノドの仕上がりの線を越える。",
      "フォントの字の送りは使わず、実際の数字の幅より広い `size` で測る（[G07050](#g07050) と同じ）。",
      "`style.toml` をスキーマのとおりに読めた後の検査であり、ほかの検査の誤り（[G03011](#g03011) など）と一緒に出す。",
      "TOML として読めないか、スキーマに合わない（[G03006](#g03006) などで読み込みが止まる）ときは検査しない。",
      "`enabled`、`--marks`、ターゲットによらず検査する。",
      "位置は `gutter` の値で、`gutter` を書かず `size` だけを書いた場合は `size` の値である。",
      "値はどれも mm で、小数第 2 位まで、等距離なら偶数の側へ丸めて書く（[docs/adr/0103](adr/0103-single-place-for-unit-conversions.md)）。",
      "`<下限>` は、検査を通る `gutter` のうち 0.01mm の倍数で最も小さい値、`<上限>` は、検査を通る `size` のうち 0.01mm の倍数で最も大きい値であり、どちらも `style.toml` の寸法と同じ丸めで sp に直して求める。",
      "二つは 0.01mm の倍数なので、丸めずに書かれる。",
      "diagnostic の事実（JSON の `facts`）に、`gutter`、`size`、`min-gutter`、`max-size` を sp の整数で持つ。",
      "",
      "- メッセージ: `[hidden-folio] の gutter（<gutter>）が size（<size>）の半分（<半分>）より小さいため、隠しノンブルの数字が仕上がりの線を越えます（gutter を <下限> 以上にするか、size を <上限> 以下にします）`（例: `size = \"6pt\"`、`gutter = \"2pt\"` では `[hidden-folio] の gutter（0.71mm）が size（2.12mm）の半分（1.06mm）より小さいため、隠しノンブルの数字が仕上がりの線を越えます（gutter を 1.06mm 以上にするか、size を 1.41mm 以下にします）`）",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）",
      "- ADR: [golem-driver ADR 0041](golem-driver/adr/0041-hidden-folio-overlap-check-by-size.md)",
      "",
      "### 主な原因",
      "",
      "- `[hidden-folio]` の `gutter` を小さくしすぎた。",
      "- `[hidden-folio]` の `size` を大きくしすぎた。",
      "",
      "### 直し方",
      "",
      "`[hidden-folio]` の `gutter` を大きくするか、`size` を小さくする。",
      "メッセージの下限か上限の値をそのまま `\"1.06mm\"` のように書けば、検査を通る。",
      "",
      "## G03100",
      "",
      "キャプションと傍注は字下げを掛けないので、`<スタイル>.<キー> = <値>` は効果がありません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "組み込みの段落スタイル `caption`、`sidenote`、`table` に、値が 0 の `indent`、`first-line-indent`、`end-indent`（`\"0zw\"`、`\"0mm\"`、`\"-0pt\"` など）を書いた。",
      "キャプションと傍注と表のセルは字下げをしない（組み込みの定義が字下げ 0 を持つ）ので、書いた値は組版を変えない（`table` は [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。",
      "0 でない値は [G03006](#g03006) のエラーである。",
      "`style.toml` では位置は値で、`style.toml` を読めた後に出す。",
      "ファイルの中の定義（`@style-def`）では、位置はそのキーの引数で、評価（golem-eval の `Golem.Eval.Settings`）が出す。",
      "`<値>` は書いたとおりの値である（`style.toml` では `\"0zw\"` のように引用符を付ける）。",
      "",
      "- メッセージ: `キャプションと傍注は字下げを掛けないので、<スタイル>.<キー> = <値> は効果がありません`（例: `キャプションと傍注は字下げを掛けないので、caption.indent = \"0zw\" は効果がありません`）。`table` では「キャプションと傍注」が「表のセル」になる",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`、golem-driver の `Golem.Driver`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [golem-driver ADR 0043](golem-driver/adr/0043-caption-sidenote-do-not-inherit-indent.md)。お知らせにしたのは実装のときのメンテナーの判断である",
      "",
      "### 主な原因",
      "",
      "- `body` の字下げを打ち消すつもりで、`caption` か `sidenote` に字下げ 0 を書いた。",
      "",
      "### 直し方",
      "",
      "そのキーを消す。",
      "`silence-notices` に `\"G03100\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G03101",
      "",
      "[functions.requires] に知らない要求の種類があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[functions.requires]` に、要求の一覧にない種類のキーを書いた。",
      "v1 の要求の種類は `file` だけである。",
      "`.emet` のシグネチャに知らない種類を書いたときは [E05100](#e05100) である。",
      "二つは原因が同じ種類の誤りだが、直す人とファイルが違うので、コードを分ける。",
      "位置はそのキーである。",
      "",
      "- メッセージ: `[functions.requires] に知らない要求の種類があります: <キー>（使える種類: file）`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）",
      "- ADR: [docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)",
      "",
      "### 主な原因",
      "",
      "- `net` のように、一覧にない要求を許そうとした。",
      "- `file` の綴りを誤った（`files` など）。",
      "",
      "### 直し方",
      "",
      "キーを `file` にするか、消す。",
      "",
      "## G03102",
      "",
      "[functions.requires] の file のファイルがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[functions.requires]` の `file` に書いたファイルがない。",
      "ファイルは、関数を呼ぶかどうかによらず、プロジェクトを読み込む時点で読むので、関数を一つも呼ばない本でもこの誤りになる。",
      "位置は `manifest.toml` の先頭である。",
      "パスの形の誤り（URL、絶対パス、プロジェクトのルートの外）は [G03003](#g03003)、大文字と小文字だけが違う二つのパスは [G03004](#g03004) である。",
      "",
      "- メッセージ: `[functions.requires] の file のファイルがありません: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.Functions`）",
      "- ADR: [docs/adr/0161](adr/0161-emet-requirements-and-driver-handlers.md)",
      "",
      "### 主な原因",
      "",
      "- パスを誤った。",
      "- ファイルを移したか、消した。",
      "",
      "### 直し方",
      "",
      "ファイルを置くか、パスを直す。",
      "",
      "## G03108",
      "",
      "参考文献のファイルに出力に書けない文字があります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `bibliography` に並べた CSL-JSON のファイルの文字列かオブジェクトのキーに、出力に書けない文字（[G02089](#g02089) と同じ）がある。",
      "ファイルを JSON として読めた後、値の全体をたどって検査する。",
      "引用されている項目かどうか、Golem が読むフィールドかどうかを問わない。",
      "引用する項目を変えても結果が変わらないように、ファイル全体を検査する。",
      "一つでもあれば、そのファイルの項目を一つも使わない。",
      "読めないファイル（[G03026](#g03026)）と同じ扱いで、そのファイルの文献を引く `[cite ...]` には [G02021](#g02021) も出る。",
      "たどる順は、配列は添字の小さい順、オブジェクトはキーの符号位置の順で、キーはその値より先に検査する。",
      "この順で最初に見つかった文字列の、最初の文字を述べる。",
      "一つのファイルに一つ出し、ほかにも書けない文字を持つ文字列があれば、その数を添える。",
      "位置は `manifest.toml` の先頭である。",
      "`Manifest` が値の位置を持たず、CSL-JSON のファイルは位置を持てる原稿ではないためであり、[G03026](#g03026) と同じ扱いである。",
      "ファイルの中の場所は、メッセージの JSON Pointer（RFC 6901。`/3/title` は 4 番めの項目の `title`、キーの `/` と `~` は `~1` と `~0`）で示す。",
      "dev と prod の両方でエラーであり、ターゲットを問わず出す。",
      "LSP も同じく出す。",
      "",
      "- メッセージ: `参考文献のファイルに出力に書けない文字（<符号位置>）があります: <パス>（<JSON Pointer>）、ほか <n> 件`（例: `参考文献のファイルに出力に書けない文字（U+0001）があります: refs.json（/0/title）`）。ほかになければ `、ほか <n> 件` を書かない",
      "- 段階とモジュール: プロジェクト（golem-bibliography の `Golem.Bibliography.Csl.decodeCslJson`、golem-driver の `Golem.Driver.loadBibliography`）。`golem check` とどのターゲットのビルドも出す",
      "- ADR: [docs/adr/0159](adr/0159-unwritable-characters-in-csl-json.md)",
      "",
      "### 主な原因",
      "",
      "- 文献管理ソフトに貼り付けた書名や抄録に、制御文字が混ざっていた。",
      "- CSL-JSON に、`\\u0001` や ESC（`\\u001b`）のエスケープが書き出された。",
      "",
      "### 直し方",
      "",
      "メッセージの JSON Pointer の文字列から、その符号位置の文字を消す。",
      "引用しない項目でも、ファイルにあれば消す。",
      "",
      "## G03109",
      "",
      "[vars] に書けない値です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[vars]` に、浮動小数点数（`1.5`）、時刻（`12:30:00`）、日時（`2026-11-06T12:30:00`、時差つきの日時を含む）を書いた。",
      "配列の要素と表の中の値も同じである。",
      "`[vars]` の値は、文字列、整数、真偽値、ローカルの日付、配列、表のどれかである。",
      "TOML の浮動小数点数は `Double` を経て読むので、Golem の数（正確な有理数）に写すと書いた値と違う数になりうる。",
      "時刻と日時には、`meta` に当たる値がなく、文字列の形を決める理由がない。",
      "位置はその値である。",
      "",
      "- メッセージ: `<キーの経路> に浮動小数点数は書けません。[vars] の値は文字列、整数、真偽値、日付、配列、表のどれかです`（`浮動小数点数` は `時刻`、`日時` にもなる）",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）",
      "- ADR: [docs/adr/0185](adr/0185-project-wide-variables.md)",
      "",
      "### 主な原因",
      "",
      "- 比率や寸法を `ratio = 1.5` のように小数で書いた。",
      "- 日付に時刻を付けた。",
      "",
      "### 直し方",
      "",
      "整数でない数は文字列で書いて使う側で読むか、`@set` の式で作る。",
      "日付は時刻を付けずに `2026-11-06` と書く。",
      "",
      "## G03110",
      "",
      "[vars] のキーが式の名前の形ではありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[vars]` か、その中の表のキーが、式の識別子の形（英字か `_` で始まり、英数字と `_` が続く。`[a-zA-Z_][a-zA-Z0-9_]*`）ではない。",
      "`edition-count` のような `-` を含むキー、`2nd` のような数字で始まるキー、`\"日本語\"` のような引用符で囲んだキーが当たる。",
      "`meta` はマニフェストのキーの `-` を `_` に直すが、`[vars]` のキーは書き手が決めるので、直さずに書いたとおりの名前で引く。",
      "位置はそのキーである。",
      "",
      "- メッセージ: `<表の経路> のキー <キー> は式の名前の形（英字か _ で始まり、英数字と _ が続く）で書きます`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）",
      "- ADR: [docs/adr/0185](adr/0185-project-wide-variables.md)",
      "",
      "### 主な原因",
      "",
      "- `[metadata]` のキーにならって、`-` で語をつないだ。",
      "",
      "### 直し方",
      "",
      "`edition_count` のように、`-` を `_` に替えるか、英字で始まる名前にする。",
      "",
      "## G03111",
      "",
      "柱が参照する [vars] の変数がありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の柱の書式に書いた `{vars.<名前>}`（`?` なし）の名前が、`manifest.toml` の `[vars]` にない。",
      "表の中の値（`{vars.author.short}`）では、途中の表がない場合と、途中の値が表でない場合も当たる。",
      "`manifest.toml` と `style.toml` を読んだところで検査するので、章の数によらず、書式の行と名前ごとに一度だけ出す。",
      "`{set.<名前>}` の [G02067](#g02067) とは、変数の出どころ（`manifest.toml`）と検査の段階が違うので、コードを分ける。",
      "`{vars.<名前>?}` は、値がないときに空の文字列になり、このコードを出さない。",
      "位置は `style.toml` の書式の行の値である。",
      "",
      "- メッセージ: `柱が参照する変数 vars.<名前> が、manifest.toml の [vars] にありません（マスターページ <名前>）`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.ProjectVars`）。`golem check`、どのターゲットのビルド、LSP も出す",
      "- ADR: [docs/adr/0185](adr/0185-project-wide-variables.md)",
      "",
      "### 主な原因",
      "",
      "- 名前の綴りを誤った。",
      "- `[vars]` から変数を消した。",
      "",
      "### 直し方",
      "",
      "`[vars]` に変数を書くか、名前を直す。",
      "値がなくてもよい差し込みなら、`{vars.<名前>?}` と書く。",
      "",
      "## G03112",
      "",
      "柱に出せない [vars] の値です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の柱の書式に書いた `{vars.<名前>}` の値が、文字列でも数でもない（真偽値、配列、表）。",
      "日付は文字列なので出せる。",
      "`?` を付けても、値があればこのコードになる。",
      "`{set.<名前>}` の [G02068](#g02068) とは、変数の出どころと検査の段階が違うので、コードを分ける。",
      "位置は `style.toml` の書式の行の値である。",
      "",
      "- メッセージ: `柱に出せるのは文字列と数です: vars.<名前> は <型>（マスターページ <名前>）`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.ProjectVars`）。`golem check`、どのターゲットのビルド、LSP も出す",
      "- ADR: [docs/adr/0185](adr/0185-project-wide-variables.md)",
      "",
      "### 主な原因",
      "",
      "- 配列や表の全体を柱に出そうとした。",
      "",
      "### 直し方",
      "",
      "表の中の値なら `{vars.author.short}` のように値まで書く。",
      "配列は、`[vars]` に柱に出す文字列を別に書く。",
      "",
      "## G03113",
      "",
      "PDF/A には [color] の intent が要ります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[targets.pdf]` に `pdfa` を書いたのに、`style.toml` に `[color]` の `intent` がない。",
      "PDF/A は PDF/X-4 の上にだけ書くので、出力インテントの ICC プロファイルが要る。",
      "PDF は書かず、HTML、EPUB、プレーンテキストは書く。",
      "dev と prod の両方でエラーである。",
      "位置は `pdfa` の値である。",
      "",
      "- メッセージ: `PDF/A には [color] の intent が要ります`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。PDF を書くときに、組む前に調べる",
      "- ADR: [docs/adr/0183](adr/0183-tagged-pdf-and-pdf-a.md)",
      "",
      "### 主な原因",
      "",
      "- PDF/A を宣言したが、出力インテントを用意していない。",
      "- 支援技術のための宣言のつもりで `pdfa` を書いた。PDF/UA だけなら `pdfua` を書く。",
      "",
      "### 直し方",
      "",
      "`style.toml` の `[color]` に `intent` を書き、CMYK の ICC プロファイルを置く。",
      "PDF/A が要らなければ、`pdfa` を消す。",
      "## G03114",
      "",
      "[lists] の numbers の {{ と }} は廃止予定です",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[lists]` の `numbers` の書式に、括弧そのものを表す `{{` か `}}` を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "書式の括弧そのものは、原稿と同じくバックスラッシュのエスケープ（`\\{` と `\\}`）で書く。",
      "`{{` と `}}` は書式だけの例外なので、廃止する予定である。",
      "今は `{{` と `}}` を `{` と `}` に読み、組みは変わらない。",
      "お知らせは書式ごとに一つである。",
      "位置はその書式の値である。",
      "エラーにする時期は、「廃止予定の手順」と互換性の文書 [docs/compatibility.md](compatibility.md) の「廃止予定の書き方」に従う。",
      "",
      "- メッセージ: `[lists] の numbers の {{ と }} は廃止予定です。\\{ と \\} と書きます: <書式>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style.styleNotices`）",
      "- ADR: [docs/adr/0177](adr/0177-note-mark-style-and-numerals.md)",
      "",
      "### 主な原因",
      "",
      "- 以前の書き方に合わせて、括弧を `{{` と `}}` と書いた。",
      "",
      "### 直し方",
      "",
      "`{{` を `\\{` に、`}}` を `\\}` に書き換える。",
      "TOML の基本の文字列（`\"...\"`）では `\\` を `\\\\` と書くので、リテラル文字列（`'...'`）を使う。",
      "",
      "書き換える前：",
      "",
      "```toml",
      "[lists]",
      "numbers = [\"{{{n}}}\"]",
      "```",
      "",
      "書き換えた後：",
      "",
      "```toml",
      "[lists]",
      "numbers = ['\\{{n}\\}']",
      "```",
      "",
      "## G03115",
      "",
      "[lists] の numbers の一字の見本の差し込みは廃止予定です",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[lists]` の `numbers` の書式に、表記を一字の見本で選ぶ差し込み（`{1}`、`{一}`、`{①}`、`{a}`、`{A}`、`{i}`、`{I}`、`{イ}`、`{ア}`）を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "表記は、表記の表の名前で `{n:<名前>}` と選ぶ。",
      "見本の字は、表記を足すと決めにくく、`{1}` は見出しの番号の書式の第 1 階層と食い違うので、廃止する予定である。",
      "今は見本の差し込みを `{n:<名前>}` と同じに読み、組みは変わらない。",
      "お知らせは書式ごとに一つである。",
      "位置はその書式の値である。",
      "エラーにする時期は、「廃止予定の手順」と互換性の文書 [docs/compatibility.md](compatibility.md) の「廃止予定の書き方」に従う。",
      "",
      "- メッセージ: `[lists] の numbers の {<見本>} は廃止予定です。{n:<名前>} と書きます: <書式>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style.styleNotices`）",
      "- ADR: [docs/adr/0177](adr/0177-note-mark-style-and-numerals.md)",
      "",
      "### 主な原因",
      "",
      "- 以前の書き方に合わせて、表記を一字の見本で選んだ。",
      "",
      "### 直し方",
      "",
      "見本の差し込みを、メッセージの `{n:<名前>}` に書き換える。",
      "`{1}` は `{n:arabic}`、`{一}` は `{n:kanji}`、`{①}` は `{n:circled}`、`{a}` と `{A}` は `{n:lower-alpha}` と `{n:upper-alpha}`、`{i}` と `{I}` は `{n:lower-roman}` と `{n:upper-roman}`、`{イ}` は `{n:iroha}`、`{ア}` は `{n:aiueo}` である。",
      "",
      "書き換える前：",
      "",
      "```toml",
      "[lists]",
      "numbers = [\"{n}.\", \"({a})\", \"{一}、\"]",
      "```",
      "",
      "書き換えた後：",
      "",
      "```toml",
      "[lists]",
      "numbers = [\"{n}.\", \"({n:lower-alpha})\", \"{n:kanji}、\"]",
      "```",
      "",
      "## G03116",
      "",
      "柱の書式の {{ と }} は廃止予定です",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` のマスターページの柱の書式の行に、括弧そのものを表す `{{` か `}}` を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "書式の括弧そのものは、バックスラッシュのエスケープ（`\\{` と `\\}`）で書く。",
      "今は `{{` と `}}` を `{` と `}` に読み、組みは変わらない。",
      "お知らせは行ごとに一つである。",
      "位置はその行の値である。",
      "エラーにする時期は、「廃止予定の手順」と互換性の文書 [docs/compatibility.md](compatibility.md) の「廃止予定の書き方」に従う。",
      "",
      "- メッセージ: `柱の書式の {{ と }} は廃止予定です。\\{ と \\} と書きます: <書式>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style.styleNotices`）",
      "- ADR: [docs/adr/0177](adr/0177-note-mark-style-and-numerals.md)",
      "",
      "### 主な原因",
      "",
      "- 以前の書き方に合わせて、柱の書式の括弧を `{{` と `}}` と書いた。",
      "",
      "### 直し方",
      "",
      "`{{` を `\\{` に、`}}` を `\\}` に書き換え、リテラル文字列（`'...'`）で書く。",
      "",
      "書き換える前：",
      "",
      "```toml",
      "[masters.body]",
      "running-head = { position = \"top-outside\", content = [\"{{{meta.title}}}\"] }",
      "```",
      "",
      "書き換えた後：",
      "",
      "```toml",
      "[masters.body]",
      "running-head = { position = \"top-outside\", content = ['\\{{meta.title}\\}'] }",
      "```",
      "",
      "## G03117",
      "",
      "[notes] の mark-size は廃止予定です",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[notes]` に `mark-size` を書いた（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "注の印の大きさは、印の文字スタイル（`[notes]` の `mark-style`、既定は組み込みの `note-mark`）の `size` で決める。",
      "同じ値を二つのキーで書ける形を残さないため、`mark-size` を廃止する予定である。",
      "今は `mark-size` を本文の印の文字スタイルの `size` の省略形として読み、組みは変わらない。",
      "位置は `mark-size` の値である。",
      "エラーにする時期は、「廃止予定の手順」と互換性の文書 [docs/compatibility.md](compatibility.md) の「廃止予定の書き方」に従う。",
      "",
      "- メッセージ: `[notes] の mark-size は廃止予定です。[character-styles.note-mark] の size に書きます`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style.styleNotices`）",
      "- ADR: [docs/adr/0177](adr/0177-note-mark-style-and-numerals.md)",
      "",
      "### 主な原因",
      "",
      "- 以前の書き方に合わせて、印の大きさを `mark-size` で書いた。",
      "",
      "### 直し方",
      "",
      "`mark-size` を消し、同じ値を `[character-styles.note-mark]` の `size` に書く。",
      "`mark-style` で別の文字スタイルを指す本では、その文字スタイルの `size` に書く。",
      "絶対の寸法が印の位置の文字の大きさを超えるとその大きさで組む規則は `mark-size` だけのものなので、文字スタイルの `size` では、印の位置の文字より大きい値もそのまま組む。",
      "",
      "書き換える前：",
      "",
      "```toml",
      "[notes]",
      "mark-size = \"0.65zw\"",
      "```",
      "",
      "書き換えた後：",
      "",
      "```toml",
      "[character-styles.note-mark]",
      "size = \"0.65zw\"",
      "```",
      "",
      "## G03118",
      "",
      "縦組みの本では、段落スタイルの align にノドと小口の揃えを書けません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[page]` の `writing-mode` が `\"vertical\"` の本で、段落スタイルの `align` に `\"towards-spine\"` か `\"away-from-spine\"` を書いた。",
      "二つは、行をページのノドの側か小口の側に寄せる値である。",
      "縦組みの行は天から地へ進むので、ノドと小口は行の方向に交わらず、行をノドの側に寄せることが意味を持たない。",
      "InDesign は縦組みのフレームではこの二つを適用しないが、Golem は書いた値を黙って適用しない出力を作らずに止める。",
      "値そのものは正しく、書字方向との組み合わせが原因なので、値の書き間違い（[G03006](#g03006)）とはコードを分ける。",
      "`style.toml` では位置は `align` の値である。",
      "ファイルの中の定義（`@style-def`）では、位置は `align` の引数であり、その定義を使わない。",
      "",
      "- メッセージ: `縦組みの本では、段落スタイル <名前> の align に <値> を書けません。ノドと小口は横組みの本でだけ使えます`（例: `縦組みの本では、段落スタイル quote の align に towards-spine を書けません。ノドと小口は横組みの本でだけ使えます`）",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0189](adr/0189-paragraph-alignment-spacing-and-end-indent.md)",
      "",
      "### 主な原因",
      "",
      "- 横組みの本の `style.toml` を、縦組みの本に写した。",
      "- 本を横組みから縦組みに切り替えた。",
      "",
      "### 直し方",
      "",
      "縦組みの本なら、`align` を `\"left\"`（天付き）か `\"right\"`（地付き）などの値に変える。",
      "横組みの本にするなら、`writing-mode` を `\"horizontal\"` にする。",
      "",
      "## G03119",
      "",
      "PDF/A と PDF/UA には、language を言語のタグの形で書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[targets.pdf]` に `pdfa` か `pdfua` を書いた本で、`[metadata]` の `language` が BCP 47 の言語のタグの形でない。",
      "PDF のカタログの `/Lang` に書く値なので、PDF/A と PDF/UA はその形を調べる。",
      "調べるのは形だけで、IANA の登録簿に載っているかは調べない。",
      "`pdfa` も `pdfua` も書かない本では調べない。",
      "PDF は書かず、HTML、EPUB、プレーンテキストは書く。",
      "dev と prod の両方でエラーである。",
      "位置は `language` の値である。",
      "",
      "- メッセージ: `PDF/A と PDF/UA には、language を言語のタグの形で書きます: <値>`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`、形の検査は golem-syntax の `Golem.Syntax.LanguageTag`）。PDF を書くときに、組む前に調べる",
      "- ADR: [docs/adr/0183](adr/0183-tagged-pdf-and-pdf-a.md)",
      "",
      "### 主な原因",
      "",
      "- `language` に言語の名前（`日本語` など）を書いた。",
      "- 区切りに `_` を使った（`ja_JP`）。",
      "",
      "### 直し方",
      "",
      "`language` を `ja`、`en-US` のような言語のタグで書く。",
      "## G03120",
      "",
      "段落の区切り方を書いていないので、改行の様式（paragraph-separator = \"line\"）で読みます",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[source]` に `paragraph-separator` を書いていない。",
      "段落の区切り方の既定は、改行ひとつで段落を区切る改行の様式である。",
      "空行の様式で書いた原稿で一つの段落を複数の行に折り返していると、行ごとに別の段落になる。",
      "既定が空行の様式から改行の様式に変わったことを知らない書き手に、原稿の読み方が既定に依ることを知らせる。",
      "章の項目かファイルの中の上書き（`@manifest`）で、すべての原稿の値が決まっていても、`[source]` に書いていなければ出す。",
      "判定を `manifest.toml` だけで決めるためである。",
      "位置は `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `段落の区切り方を書いていないので、改行の様式（paragraph-separator = \"line\"）で読みます`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver`）",
      "- ADR: [docs/adr/0193](adr/0193-line-paragraph-separator-by-default.md)",
      "",
      "### 主な原因",
      "",
      "- 段落の区切り方の既定が空行の様式だったころに作ったプロジェクトで、`[source]` を書いていない。",
      "- `golem new` を使わずに `manifest.toml` を書いた。",
      "",
      "### 直し方",
      "",
      "空行で段落を区切って書いた原稿なら、`[source]` に `paragraph-separator = \"blank-line\"` と書く。",
      "原稿は書き換えなくてよい。",
      "改行で段落を区切って書いた原稿なら、`[source]` に `paragraph-separator = \"line\"` と書く。",
      "既定に任せるなら、`silence-notices` に `\"G03120\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G03121",
      "",
      "page-numbering の style が数の表記の名前ではありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の項目の `page-numbering` の `style` に、数の表記の名前でない文字列を書いた（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)）。",
      "書ける名前は、`style.toml` の番号の書式に書ける表記の名前（`arabic`、`kanji`、`kanji-digits`、`circled`、`lower-alpha`、`upper-alpha`、`lower-roman`、`upper-roman`、`iroha`、`aiueo`、`asterisks`、`note-symbols`）と同じである。",
      "マニフェストを読むときの誤りなので、どのターゲットでも出る。",
      "位置は `style` の値である。",
      "文字列でない値は [G03001](#g03001) とする。",
      "",
      "- メッセージ: `page-numbering の style <値> は数の表記の名前ではありません（書ける名前: <名前の一覧>）`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）。スキーマの検査の前に調べる",
      "- ADR: [docs/adr/0260](adr/0260-front-matter-folios-and-page-labels.md)",
      "",
      "### 主な原因",
      "",
      "- 名前を綴り違えた（`roman`、`lower_roman` など）。",
      "- CSS や LaTeX の名前（`lower-latin`、`roman`）を書いた。",
      "",
      "### 直し方",
      "",
      "`style` を、書ける名前のどれか（前付けなら `lower-roman` など）に直す。",
      "",
      "## G03122",
      "",
      "page-numbering の start が 0 です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の項目の `page-numbering` の `start` に 0 を書いた（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)）。",
      "`start` はセクションの最初のページの番号であり、1 以上の整数で書く。",
      "負の数は、ほかの自然数と同じく [G02103](#g02103) とし、整数でない値は [G03001](#g03001) とする。",
      "マニフェストを読むときの誤りなので、どのターゲットでも出る。",
      "位置は `start` の値である。",
      "",
      "- メッセージ: `page-numbering の start には 1 以上の整数を書きます`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Manifest`）。スキーマの検査の前に調べる",
      "- ADR: [docs/adr/0260](adr/0260-front-matter-folios-and-page-labels.md)",
      "",
      "### 主な原因",
      "",
      "- ページの番号を 0 から数えると考えて、`start = 0` と書いた。",
      "",
      "### 直し方",
      "",
      "`start` を 1 以上の整数にする。",
      "前のページの番号を続けるなら、`start` を書かない。",
      "",
      "## G03123",
      "",
      "同じファイルを page-numbering の設定を変えて章に二度並べています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の配列に同じファイルを二度並べ、二つの項目の `page-numbering` が異なる（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)）。",
      "ページとファイルの対応はファイルごとなので、どちらの値を使うかが決まらない。",
      "`page-numbering` を片方にだけ書いた場合も異なるとする。",
      "`style` の `arabic` と省いた `style` は同じとする。",
      "マニフェストを読むときの誤りなので、どのターゲットでも出る。",
      "位置は二つ目の項目の `page-numbering` の値であり、一つ目の値を関連する位置として添える。",
      "二つ目の項目が `page-numbering` を持たなければ、位置は一つ目の値である。",
      "",
      "- メッセージ: `同じファイルを page-numbering の設定を変えて章に二度並べています: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project`）",
      "- ADR: [docs/adr/0260](adr/0260-front-matter-folios-and-page-labels.md)",
      "",
      "### 主な原因",
      "",
      "- 同じファイルを前付けと本文の両方に並べ、片方にだけ `page-numbering` を書いた。",
      "",
      "### 直し方",
      "",
      "二つの項目の `page-numbering` をそろえるか、どちらかの項目を別のファイルにする。",
      "",
      "## G03124",
      "",
      "OpenType の機能の書き方が正しくありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "フォントの役割（`[fonts.<役割>]`）、文字スタイル、段落スタイルの `features` の要素が、受け付ける四つの形（`tag`、`+tag`、`-tag`、`tag=N`）のどれでもない。",
      "`tag` は英字と数字の 4 字であり、`N` は 0 から 65535 までの十進の整数である。",
      "HarfBuzz が読めるほかの形（`kern[3:5]` のような範囲、`aalt=on` のような語の値）も受け付けない。",
      "誤りのある要素ごとに一つ出し、要素の順に並べる。",
      "誤りのある定義は捨てる。",
      "`@style-def` では `features=\"smcp,-liga\"` のように `,` で区切った一つの文字列で書き、空の要素もこのエラーになる。",
      "`features` に配列でない値を書いた誤りは [G03006](#g03006) である。",
      "",
      "- メッセージ: `OpenType の機能の書き方が正しくありません: <文字列>（smcp、-liga、salt=2 のように書きます）`。後ろに `(character-styles.<名前>.features[<番号>])` のように経路を添える",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。位置は、`style.toml` ではその要素の値、`@style-def` ではその行である",
      "- ADR: [ADR 0268](adr/0268-opentype-features-on-character-styles.md)",
      "",
      "### 主な原因",
      "",
      "- タグを 4 字でなく書いた（`smc`、`smcpx`）。",
      "- 値を `=` の後に書いていないか、負の数や 65536 以上の数、語を書いた（`smcp=`、`smcp=-1`、`aalt=on`）。",
      "- HarfBuzz の範囲の書き方（`kern[3:5]`）を書いた。範囲は文字スタイルで当てる。",
      "- 空白や ASCII でない字を含めた。",
      "- 役割の `features` に、これまで黙って捨てられていた文字列が残っていた。",
      "",
      "### 直し方",
      "",
      "`smcp`、`-liga`、`salt=2` のように、四つの形のどれかで書き直す。",
      "役割の `features` の読めない文字列は今も組版に適用されていないので、消しても PDF は変わらない。",
      "## G03125",
      "",
      "注の印の文字スタイルの position は \"normal\" だけを書けます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "本文の注の印の文字スタイル（`[notes]` の `mark-style`、書かなければ `note-mark`）の `based-on` の鎖で、`position` が `\"normal\"` でない値（`\"superscript\"` か `\"subscript\"`）に解決する。",
      "本文の印の位置は `[notes]` と印の配置の規則で決まり、`position` の上げ下げを重ねると、どちらの位置で組むかが決まらない。",
      "注の本文の先頭の印（`body-mark-style`）には出さない。",
      "誤りのある定義は捨てる。",
      "",
      "- メッセージ: `注の印の文字スタイル <名前> の position は \"normal\" だけを書けます（印の位置は [notes] で決まります）`。`<名前>` は印の文字スタイルの名前である",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）。位置は、`position` を書いた定義の値である。組み込みの `superscript` か `subscript` に行き着き、`style.toml` に値がなければ `style.toml` の先頭である。ファイルの中の定義（`@style-def`）では、その行である",
      "- ADR: [ADR 0269](adr/0269-superscript-and-subscript.md)",
      "",
      "### 主な原因",
      "",
      "- `[notes]` の `mark-style` に、組み込みの `superscript` か、それを `based-on` にした文字スタイルを書いた。",
      "- `[character-styles.note-mark]` に `position` を書いた。",
      "",
      "### 直し方",
      "",
      "印の文字スタイルから `position` を消すか、`based-on` を `superscript` でないスタイルにする。",
      "印に書体の上付きの字形を使いたいときは、印の文字スタイルに `features = [\"sups\"]` を書く。",
      "",
      "## G03126",
      "",
      "分綴の例外の一覧のキーが言語のタグの形ではありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "分綴の例外の一覧の言語のタグが、BCP 47 の言語のタグの形ではない。",
      "形だけを検査し、IANA の登録簿は見ない（`[lang]` の [G02132](#g02132) と同じ規則）。",
      "ファイルの設定では、その行の全体を捨てる。",
      "誤りは `style.toml` の `[composition.hyphenation-exceptions]` と、ファイルの設定の `@hyphenation-exceptions` の両方に出す。",
      "位置は、`style.toml` ではその値、ファイルの設定ではその引数である。",
      "エラーなので、ビルドは止まる。",
      "",
      "- メッセージ: `分綴の例外の一覧のキーが言語のタグの形ではありません: <タグ>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- 言語の名前（`english`）や、`en_US` のように `_` で区切ったタグを書いた。",
      "",
      "### 直し方",
      "",
      "`en`、`en-US`、`fr` のように BCP 47 の形で書く。",
      "",
      "## G03127",
      "",
      "分綴の例外の語には字と - だけを書きます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "分綴の例外の語に、字（一般カテゴリが L の字）と `-` のほかの文字がある。",
      "空の語と、結合文字を含む語もこれにあたる。",
      "一つの語に二つ以上の誤りがあれば、このコードを [G03128](#g03128) と [G03129](#g03129) より先に出し、ほかは出さない。",
      "その語だけを捨てる。",
      "誤りは `style.toml` の `[composition.hyphenation-exceptions]` と、ファイルの設定の `@hyphenation-exceptions` の両方に出す。",
      "位置は、`style.toml` ではその値、ファイルの設定ではその引数である。",
      "エラーなので、ビルドは止まる。",
      "",
      "- メッセージ: `分綴の例外の語には字と - だけを書きます: <語>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- 数字、空白、アポストロフィを含む語を書いた。",
      "- 分ける位置を `-` ではなく `·` などで書いた。",
      "",
      "### 直し方",
      "",
      "分けてよい位置に `-` を書いた、字だけの語にする。",
      "",
      "## G03128",
      "",
      "分綴の例外の語の - が端にあるか、二つ続いています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "分綴の例外の語の最初か最後に `-` があるか、`-` が二つ続いている。",
      "`-` だけの語もこれにあたる。",
      "その語だけを捨てる。",
      "誤りは `style.toml` の `[composition.hyphenation-exceptions]` と、ファイルの設定の `@hyphenation-exceptions` の両方に出す。",
      "位置は、`style.toml` ではその値、ファイルの設定ではその引数である。",
      "エラーなので、ビルドは止まる。",
      "",
      "- メッセージ: `分綴の例外の語の - が端にあるか、二つ続いています: <語>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- `-ble` や `ta--ble` のように書き誤った。",
      "",
      "### 直し方",
      "",
      "`-` は字と字のあいだに一つずつ書く。",
      "",
      "## G03129",
      "",
      "同じ語を二度書いています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "一つの言語の分綴の例外の一覧に、同じ語を二度書いた。",
      "小文字にして `-` を除いた語が同じなら、`-` の位置が同じでも違っても同じ語とする。",
      "二つ目からの語を捨てる。",
      "誤りは `style.toml` の `[composition.hyphenation-exceptions]` と、ファイルの設定の `@hyphenation-exceptions` の両方に出す。",
      "位置は、`style.toml` ではその値、ファイルの設定ではその引数である。",
      "エラーなので、ビルドは止まる。",
      "",
      "- メッセージ: `同じ語を二度書いています: <語>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- `ta-ble` と `tab-le` のように、同じ語の分け方を二つ書いた。",
      "- 大文字の語と小文字の語を両方書いた。",
      "",
      "### 直し方",
      "",
      "一つの語に一つの分け方だけを残す。",
      "",
      "## G03130",
      "",
      "大文字と小文字だけが違う言語のタグの一覧が二つあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "分綴の例外の一覧に、大文字と小文字だけが違う言語のタグ（`en` と `EN` など）が二つある。",
      "`style.toml` では後のキーに、ファイルの設定では後の行に出し、ファイルの設定ではその行の全体を捨てる。",
      "誤りは `style.toml` の `[composition.hyphenation-exceptions]` と、ファイルの設定の `@hyphenation-exceptions` の両方に出す。",
      "位置は、`style.toml` ではその値、ファイルの設定ではその引数である。",
      "エラーなので、ビルドは止まる。",
      "",
      "- メッセージ: `大文字と小文字だけが違う言語のタグの一覧が二つあります: <タグ>`",
      "- 段階とモジュール: プロジェクト（golem-project の `Golem.Project.Style`）、評価（golem-eval の `Golem.Eval.Settings`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- 同じ言語の一覧を、二か所に分けて書いた。",
      "",
      "### 直し方",
      "",
      "一つの言語の語を一つの一覧（一つの行）にまとめる。",
      "## G03131",
      "",
      "プロジェクトのファイルがすでにあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`golem new` に渡したディレクトリに、`manifest.toml` か `style.toml` がすでにある。",
      "ファイルでなくても、ディレクトリやシンボリックリンク（辿れないものも含む）があれば、この誤りとする。",
      "二つともあれば、それぞれに一つずつ出す。",
      "このときは、ほかの雛形のファイルとの衝突（[G03132](#g03132)）を報告しない。",
      "同じディレクトリで `golem new` を二度実行すると、雛形のパスがすべてぶつかり、原因が埋もれるからである。",
      "`golem new` は何も書かず、フォントも取得せず、終了コード 1 で終える。",
      "位置は、そのパスの先頭である。",
      "",
      "- メッセージ: `プロジェクトのファイルがすでにあります: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.New`）",
      "- ADR: [docs/adr/0273](adr/0273-golem-new-in-a-directory-without-a-project.md)",
      "",
      "### 主な原因",
      "",
      "- すでにある Golem のプロジェクトの中で `golem new` を実行した。",
      "- 別の道具の設定のファイルが、同じ名前でディレクトリにある。",
      "",
      "### 直し方",
      "",
      "新しいプロジェクトを作るなら、別のディレクトリを指定する。",
      "すでにあるプロジェクトをそのまま使うなら、`golem new` を実行する必要はない。",
      "",
      "## G03132",
      "",
      "雛形のファイルを書くパスに、すでにエントリがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`golem new` が雛形のファイルを書くパスに、すでにファイル、ディレクトリ、シンボリックリンクのどれかがある。",
      "検査するパスは、`chapters/01.gm`、`preflight.toml`、フォントとそのライセンスの文書である。",
      "`--no-fonts` を付けたときは、フォントのパスと `fonts` を検査しない。",
      "途中の要素（`chapters`、`fonts`）が、シンボリックリンクでないディレクトリでないときも、この誤りとする。",
      "そのときは、その要素のパスで一つだけ出し、その下のパスには出さない。",
      "シンボリックリンクを衝突とみなすのは、雛形のファイルをリンクの先、つまり指定したディレクトリの外に書かないためである。",
      "衝突をすべて一度に、パスのバイト列の昇順に報告する。",
      "`golem new` は何も書かず、フォントも取得せず、終了コード 1 で終える。",
      "位置は、そのパスの先頭である。",
      "",
      "`manifest.toml` か `style.toml` があるときは、この誤りではなく [G03131](#g03131) とする。",
      "`.gitignore` があるときは、誤りとせず、書かずに残す（[G03134](#g03134)）。",
      "",
      "- メッセージ: `雛形のファイルを書くパスに、すでにエントリがあります: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.New`）",
      "- ADR: [docs/adr/0273](adr/0273-golem-new-in-a-directory-without-a-project.md)",
      "",
      "### 主な原因",
      "",
      "- 移そうとしている原稿のディレクトリに、`chapters/01.gm` や `preflight.toml` がすでにある。",
      "- `fonts` や `chapters` が、共有のディレクトリへのシンボリックリンクである。",
      "- `fonts` や `chapters` という名前のファイルがある。",
      "",
      "### 直し方",
      "",
      "報告されたパスのものを別の場所へ移してから、`golem new` を実行し直す。",
      "`fonts` がフォントのディレクトリへのシンボリックリンクなら、`--no-fonts` を付けて作るか、リンクを外す。",
      "",
      "## G03133",
      "",
      "ディレクトリではありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`golem new` に渡したパスが、ディレクトリでなく、ディレクトリを作ることもできない。",
      "通常のファイル、ファイルへのシンボリックリンク、辿れないシンボリックリンク、途中の要素がディレクトリでないパス（`afile/book` の `afile` が通常のファイルなど）がこれに当たる。",
      "ディレクトリへのシンボリックリンクは辿り、その先に雛形を作る。",
      "このときは、ほかの検査をせず、何も作らずに終了コード 1 で終える。",
      "位置は、渡したパスの先頭である。",
      "",
      "- メッセージ: `ディレクトリではありません: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.New`）",
      "- ADR: [docs/adr/0273](adr/0273-golem-new-in-a-directory-without-a-project.md)",
      "",
      "### 主な原因",
      "",
      "- ディレクトリの名前を、すでにあるファイルの名前と取り違えた。",
      "- パスの途中の名前を綴り誤り、ファイルを指した。",
      "",
      "### 直し方",
      "",
      "ディレクトリのパスか、まだないパスを渡す。",
      "",
      "## G03134",
      "",
      ".gitignore がすでにあるので書きませんでした",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
