      "`golem new` に渡したディレクトリに `.gitignore` がすでにあったので、雛形の `.gitignore`（`build/` の一行）を書かずに残した。",
      "ほかの雛形のファイルは書き、終了コードは 0 である。",
      "すでにある `.gitignore` の中身は読まないので、`build/` がすでに書いてあっても出す。",
      "`golem new` が誤りで何も書かなかったときは、出さない。",
      "位置は `.gitignore` の先頭である。",
      "",
      "- メッセージ: `.gitignore がすでにあるので書きませんでした。build/ を除外してください: <パス>`",
      "- 段階とモジュール: プロジェクト（golem-driver の `Golem.Driver.New`）",
      "- ADR: [docs/adr/0273](adr/0273-golem-new-in-a-directory-without-a-project.md)",
      "",
      "### 主な原因",
      "",
      "- git のリポジトリになっている原稿のディレクトリで `golem new` を実行した。",
      "",
      "### 直し方",
      "",
      "出力のディレクトリ `build/` を git で管理しないなら、すでにある `.gitignore` に `build/` の行を足す。",
      "すでに書いてあれば、直す必要はない。",
      "`golem new` は `--no-notices` を受け付けないので、このお知らせは消せない。",
      "",
