      "",
      "## G04004",
      "",
      "章の外にある図版、表、コードに、章番号を使う番号を振れません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の図番号の書式（`figures.number`）が `{chapter}` を使うのに、章の番号を持たない図版がある。",
      "リスト番号の書式（`[code]` の `number`、既定 `リスト{chapter}-{n}`）が `{chapter}` を使うのに、章の番号を持たない、キャプションのあるコードブロックがある場合も、この誤りとする。",
      "表番号の書式（`[tables]` の `number`、既定 `表{chapter}-{n}`）が `{chapter}` を使うのに、章の番号を持たない、キャプションのある表がある場合も同じである（[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。",
      "章は、番号を持つ階層 1 の見出しから、次の階層 1 の見出しまでである。",
      "最初の章の見出しより前の図版とコードブロックと表と、`@nonumber` の階層 1 の見出し（あとがきなど）の後のものが、章の外になる。",
      "キャプションのないコードブロックと表と、`@nonumber` を付けた図版とコードブロックと表は番号を持たないので、この誤りにならない（[docs/adr/0200](adr/0200-figures-and-listings-without-numbers.md)）。",
      "位置は図版かコードブロックか表のブロックである。",
      "",
      "- メッセージ: `章の外にある図版、表、コードには、章番号を使う番号を振れません。章は番号を持つ階層 1 の見出しから始まります。番号を振らないなら @nonumber を付けます`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [golem-doc ADR 0003](golem-doc/adr/0003-document-diagnostic-codes.md)（コードブロックの条件は [golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md) が加えた。メッセージの `@nonumber` の案内は [docs/adr/0200](adr/0200-figures-and-listings-without-numbers.md) が足した。表とメッセージの「図版、表、コード」は [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md) が足した）",
      "",
      "### 主な原因",
      "",
      "- 図番号、リスト番号、表番号の書式が `{chapter}` を使うのに、最初の章の見出しより前に図版か、キャプションのあるコードブロックか表を置いた。",
      "- 図番号、リスト番号、表番号の書式が `{chapter}` を使うのに、`@nonumber` の階層 1 の見出し（あとがきなど）の後に図版か、キャプションのあるコードブロックか表を置いた。",
      "",
      "### 直し方",
      "",
      "図版とコードブロックと表を章の中に移すか、番号の書式から `{chapter}` を外す。",
      "番号の要らない図版とコードブロックと表（前付けや後書きの図など）なら、`@nonumber` を付ける。",
      "",
      "## G04005",
      "",
      "番号を持たない要素への参照です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`ref-number` が、番号を持たない要素を指す。",
      "番号を持つのは、`@nonumber` のない見出し、`@nonumber` のない図版、`@nonumber` のない、キャプションを付けたコードブロックと表である。",
      "位置は参照であり、参照は何も出力しない。",
      "",
      "- メッセージ: `番号を持たない要素への参照です: <ラベル>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [golem-doc ADR 0003](golem-doc/adr/0003-document-diagnostic-codes.md)、[golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md)（コードブロック）、[docs/adr/0200](adr/0200-figures-and-listings-without-numbers.md)（`@nonumber` の図版とコードブロック）、[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)（表）",
      "",
      "### 主な原因",
      "",
      "- `ref-number` で、番号のない見出しや `@nonumber` の図版、キャプションのない表など、番号を持たない要素を指した。",
      "",
      "### 直し方",
      "",
      "題を参照するなら `ref-title` を使う。",
      "番号を参照するなら、番号の付く要素にラベルを移す。",
      "",
      "## G04006",
      "",
      "題を持たない要素への参照です",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`ref-title` が、題を持たない要素を指す。",
      "題を持つのは、見出し（`@toc-title` があればそれ）、図版（代替テキスト）、キャプションを付けたコードブロックと表（キャプション）である。",
      "段落、リスト、キャプションのないコードブロックと表などに付けたラベルは、`ref-title` で参照できない。",
      "位置は参照であり、参照は何も出力しない。",
      "",
      "- メッセージ: `題を持たない要素への参照です: <ラベル>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [golem-doc ADR 0003](golem-doc/adr/0003-document-diagnostic-codes.md)、[golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md)（コードブロック）、[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)（表）",
      "",
      "### 主な原因",
      "",
      "- 段落、リスト、キャプションのない表などに付けたラベルを `ref-title` で指した。",
      "- 題を参照するつもりで、見出しではなく、見出しの次の段落にラベルを付けた。",
      "",
      "### 直し方",
      "",
      "題を参照するなら、見出しか図版にラベルを移す。",
      "その箇所のページを参照するなら `ref-page` を使う。",
      "",
      "## G04007",
      "",
      "@number が自動で振られる番号と同じです",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "見出しか番号付きリストの項目の `@number N` が、`@number` がなくても振られる番号と同じである。",
      "今は効果がないが、項目を入れ替えたときに番号を固定してしまう。",
      "見出しの番号は文書の組み立てで求めた番号と比べ、`@nonumber` の見出しが番号を消費しないことも含めて判定する。",
      "リストの項目の前に `@number` を置くと、その項目から別のリストになる。",
      "その場合は、直前のリストの続きとして振られる番号と比べる。",
      "位置は `@number` の行である。",
      "",
      "- メッセージ: `@number <N> は自動で振られる番号と同じです`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)",
      "",
      "### 主な原因",
      "",
      "- 番号を確かめるつもりで、自動の番号と同じ `@number` を書いた。",
      "- 前の項目を消して、`@number` の番号が自動の番号と一致した。",
      "",
      "### 直し方",
      "",
      "`@number` の行を消す。",
      "番号は自動で振られる。",
      "",
      "## G04008",
      "",
      "本の最後の改ページは効果がありません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "本の最後のファイルで、最後のブロックの後に改ページ（`@page-break`、`@column-break`）しかない。",
      "本の最後の改ページは捨てられるので、白ページは作られない。",
      "ファイルの末尾の改ページは次のファイルに適用されるので、本の最後のファイルのものだけを対象にする。",
      "改ページが続く場合は、一つずつ出す。",
      "位置は改ページのコマンドの行である。",
      "",
      "- メッセージ: `本の最後の改ページは効果がありません`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)、[docs/adr/0017](adr/0017-forced-page-breaks.md)",
      "",
      "### 主な原因",
      "",
      "- 白ページを作るつもりで、本の最後に `@page-break` を書いた。",
      "- 章ごとに末尾へ改ページを書く習慣で、最後の章にも書いた。",
      "",
      "### 直し方",
      "",
      "本の最後の改ページを消す。",
      "",
      "## G04009",
      "",
      "本の最後の `@blank-line` は効果がありません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "本の最後のブロックの後に、`@blank-line` しかない。",
      "間とその後に改ページ（`@page-break`、`@column-break`）、`@need-lines`、`@page-lines`、`@no-page-break` があっても同じである。",
      "本の最後の行アキは、すべての出力で捨てる。",
      "ファイルの末尾の `@blank-line` は次のファイルの最初のブロックの前に置かれるので、本の全体で後にブロックがないものだけを対象にする。",
      "`@blank-line` が続く場合は、一つずつ出す。",
      "位置は `@blank-line` の行である。",
      "",
      "- メッセージ: `本の最後の @blank-line は効果がありません`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0046](adr/0046-blank-line-command.md)",
      "",
      "### 主な原因",
      "",
      "- 最後の章の末尾に、空きを残すつもりで `@blank-line` を書いた。",
      "",
      "### 直し方",
      "",
      "本の最後の `@blank-line` を消す。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G04009\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G04010",
      "",
      "`@blank-line` の直後に改ページがあります",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@blank-line` の直後に、ほかのブロックを挟まずに `@page-break` か `@column-break` がある。",
      "間に `@need-lines`、`@page-lines`、ほかの `@blank-line` があっても同じ位置とみなす。",
      "ファイルの末尾の `@blank-line` と、次のファイルの先頭の改ページの組み合わせも対象にする。",
      "行アキは次のブロックの前に置くので、改ページの前の行アキは、PDF では必ず改ページの後の段の先頭に移って捨てられる。",
      "HTML、EPUB、プレーンテキストで空きが出ると媒体のあいだで結果が食い違うので、その行アキをすべての出力で捨てる。",
      "位置は `@blank-line` の行である。",
      "本の最後では [G04009](#g04009) も出る。",
      "",
      "- メッセージ: `@blank-line の直後に @page-break があります`、`@blank-line の直後に @column-break があります`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0046](adr/0046-blank-line-command.md)",
      "",
      "### 主な原因",
      "",
      "- 章の終わりに空きを入れてから改ページした。",
      "- 改ページの後の本文を下げるつもりで、改ページの前に `@blank-line` を書いた。",
      "",
      "### 直し方",
      "",
      "改ページの前の `@blank-line` を消す。",
      "改ページの後の段の先頭の行アキも捨てられるので、改ページの後の本文を下げる用途には使えない。",
      "",
      "## G04011",
      "",
      "`@blank-line` の行数がページの行数以上なので捨てます",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@blank-line` の行数が、`style.toml` の `[page.grid]` の `lines`（ページの行数）以上である。",
      "続けて書いた `@blank-line`（間に `@need-lines`、`@page-lines`、`@no-page-break` しかないもの）は、行数の和で判定する。",
      "ファイルの末尾の `@blank-line` と、次のファイルの先頭の `@blank-line` も続けて書いたものとみなす。",
      "PDF では、ページの行数以上の行アキは次のブロックの最初の行とともに一つの段に入らないので、必ず段の先頭で捨てられる。",
      "HTML、EPUB、プレーンテキストに残ると、媒体のあいだで結果が食い違い、出力が行数に比例して膨らむので、その行アキをすべての出力で捨てる。",
      "`@blank-line` が続く場合は、一つずつ出す。",
      "位置は `@blank-line` の行である。",
      "`@page-lines` による段の行数の増減は、判定に含めない。",
      "`[page.grid]` のない本では判定しない。",
      "[G04009](#g04009) か [G04010](#g04010) で捨てる行アキには出さない。",
      "",
      "- メッセージ: `@blank-line の行数 <n> がページの行数 <L> 以上なので捨てます`。`<n>` は続けて書いた `@blank-line` の行数の和、`<L>` はページの行数である。",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0047](adr/0047-blank-line-limit.md)",
      "",
      "### 主な原因",
      "",
      "- 段やページの全体を空けるつもりで、ページの行数以上の `@blank-line` を書いた。",
      "- 判型を変えて、ページの行数が減った。",
      "",
      "### 直し方",
      "",
      "ページを改めたいなら、`@blank-line` を `@page-break` に書き換える。",
      "空きを残したいなら、行数をページの行数より少なくする。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G04011\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G04012",
      "",
      "見出しの番号を書式の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "見出しの番号を、`style.toml` の `[headings.<階層>]` の `number` の書式の表記で表せない（[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "`circled` は 1 から 50 まで、ローマ数字は 1 から 3999 まで、`iroha` は 47 まで、`aiueo` は 46 まで、`note-symbols` は 7 までを表せ、ラテン文字とローマ数字と丸数字は 0 を表せない。",
      "上の階層の差し込み（`{1}` など）も、飛ばした階層の値 0 を含めて調べる。",
      "算用数字やほかの表記に替えては書かない。",
      "見出しの番号の文字は、目次、柱、`[ref-number]` にも写るので、文書の組み立てで報告し、PDF、HTML、EPUB、プレーンテキストのどれも書かない。",
      "同じ入力から同じ diagnostics が出るようにするためである。",
      "一つの書式に表せない差し込みが二つあるときは、書式の左から最初の差し込みについて一つだけ出す。",
      "位置はその見出しのブロックである。",
      "`@nonumber` の見出しは番号を持たないので、報告しない。",
      "",
      "- メッセージ: `[headings.<階層>] の number <書式> の {<差し込み>} では、<番号> を表せません`。`<書式>` は `style.toml` に書いた形、`<差し込み>` は `n:circled` のように差し込みの中身である",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0213](adr/0213-numbers-the-number-formats-cannot-write.md)",
      "",
      "### 主な原因",
      "",
      "- `circled` や `note-symbols` のように表せる範囲の小さい表記の書式で、見出しが多すぎる。",
      "- `@number 0` を、0 を表せない表記の見出しに書いた。",
      "",
      "### 直し方",
      "",
      "`[headings.<階層>]` の `number` を、算用数字（`{n}`）などの表せる表記に替えるか、原稿の `@number` を直す。",
      "",
      "## G04013",
      "",
      "図番号を書式の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "図版の番号を、`style.toml` の `[figures]` の `number` の書式の表記で表せない（[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "表せる範囲と、すべてのターゲットを書かないことは [G04012](#g04012) と同じである。",
      "一つの書式に表せない差し込みが二つあるときは、書式の左から最初の差し込みについて一つだけ出す。",
      "位置はその図版のブロックである。",
      "",
      "- メッセージ: `[figures] の number <書式> の {<差し込み>} では、<番号> を表せません`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0213](adr/0213-numbers-the-number-formats-cannot-write.md)",
      "",
      "### 主な原因",
      "",
      "- 表せる範囲の小さい表記の書式で、一つの章の図版が多すぎる。",
      "- `{chapter}` に表せる範囲の小さい表記を使い、章が多すぎる。",
      "",
      "### 直し方",
      "",
      "`[figures]` の `number` を、算用数字などの表せる表記に替える。",
      "",
      "## G04014",
      "",
      "リスト番号を書式の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "キャプションを付けたコードブロックの番号を、`style.toml` の `[code]` の `number` の書式の表記で表せない（[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "表せる範囲と、すべてのターゲットを書かないことは [G04012](#g04012) と同じである。",
      "一つの書式に表せない差し込みが二つあるときは、書式の左から最初の差し込みについて一つだけ出す。",
      "位置はそのコードブロックのブロックである。",
      "",
      "- メッセージ: `[code] の number <書式> の {<差し込み>} では、<番号> を表せません`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0213](adr/0213-numbers-the-number-formats-cannot-write.md)",
      "",
      "### 主な原因",
      "",
      "- 表せる範囲の小さい表記の書式で、一つの章のコードブロックが多すぎる。",
      "- `{chapter}` に表せる範囲の小さい表記を使い、章が多すぎる。",
      "",
      "### 直し方",
      "",
      "`[code]` の `number` を、算用数字などの表せる表記に替える。",
      "",
      "## G04100",
      "",
      "表番号を書式の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "キャプションを付けた表の番号を、`style.toml` の `[tables]` の `number` の書式の表記で表せない（[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)、[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "表せる範囲と、すべてのターゲットを書かないことは [G04012](#g04012) と同じである。",
      "その表は、番号の文字列なしで組む。",
      "一つの書式に表せない差し込みが二つあるときは、書式の左から最初の差し込みについて一つだけ出す。",
      "位置はその表のブロックである。",
      "",
      "- メッセージ: `[tables] の number <書式> の {<差し込み>} では、<番号> を表せません`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)",
      "",
      "### 主な原因",
      "",
      "- 表せる範囲の小さい表記の書式で、一つの章の表が多すぎる。",
      "- `{chapter}` に表せる範囲の小さい表記を使い、章が多すぎる。",
      "",
      "### 直し方",
      "",
      "`[tables]` の `number` を、算用数字などの表せる表記に替える。",
      "",
      "## G04101",
      "",
      "索引の参照先の項目がありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`[index]` の `see` の参照先の語が、同じ `@index` の一覧のどの項目の語とも一致しない（[docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)）。",
      "読みは比べない。",
      "副項目だけを持つ主項目も、一覧に行が出るので項目に数える。",
      "位置は参照を書いた印である。",
      "",
      "- メッセージ: `索引の参照先の項目がありません: <参照先の語>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)",
      "",
      "### 主な原因",
      "",
      "- 参照先の語を書き間違えた。",
      "- 参照先の項目の印が、別の `@index` の一覧の範囲にある。",
      "- 参照先の項目の印を消した。",
      "",
      "### 直し方",
      "",
      "参照先の語を、項目の語と同じに書く。",
      "項目がなければ、参照先の項目の印を置くか、参照を消す。",
      "",
      "## G04102",
      "",
      "索引の「を見よ」の参照が輪になります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "ページを持たない項目どうしの「を見よ」の参照が輪になる（[docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)）。",
      "自分自身を指す参照も輪である。",
      "読者が項目のあいだを回り続け、どの項目でもページにたどり着けないので、エラーにする。",
      "副項目を持つ主項目は、ページを持たなくても輪に数えない。",
      "輪ごとに一つ出し、位置は輪の参照を書いた印のうち、文書の順で最初の印である。",
      "",
      "- メッセージ: `索引の「を見よ」の参照が輪になります: <語>, <語>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)",
      "",
      "### 主な原因",
      "",
      "- 二つの同義語の項目を、互いに参照させた。",
      "- 参照先の項目の印を消し、参照だけが残った。",
      "",
      "### 直し方",
      "",
      "輪の中のどれか一つの項目に、ページの印を置く。",
      "そのうえで、その項目からの参照を消す。",
      "",
      "## G04103",
      "",
      "索引の範囲の始めに、対になる終わりがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`range=begin` の印に、対になる `range=end` の印がない（[docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)）。",
      "始めと終わりは、語と読みの組が等しい印どうしで、同じ `@index` の一覧に載る印の中だけで対にする。",
      "対の作り方は括弧の対応と同じで、終わりの印を、まだ閉じていない最も近い始めの印と対にする。",
      "範囲が二つの `@index` の一覧の境をまたぐと、始めはこのコードに、終わりは [G04104](#g04104) になる。",
      "位置は対のない始めの印である。",
      "",
      "- メッセージ: `索引の範囲の始めに、対になる終わりがありません: <語>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)",
      "",
      "### 主な原因",
      "",
      "- 範囲の終わりの印を書き忘れた。",
      "- 終わりの印の語か読みが、始めの印と違う。",
      "- 範囲の途中に `@index` を置いた。",
      "",
      "### 直し方",
      "",
      "範囲の終わりに、始めと同じ語と読みで `range=end` の印を置く。",
      "",
      "## G04104",
      "",
      "索引の範囲の終わりに、対になる始めがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`range=end` の印に、対になる `range=begin` の印がない（[docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)）。",
      "対の作り方は [G04103](#g04103) と同じである。",
      "位置は対のない終わりの印である。",
      "",
      "- メッセージ: `索引の範囲の終わりに、対になる始めがありません: <語>`",
      "- 段階とモジュール: 文書の組み立て（golem-assemble の `Golem.Assemble`）",
      "- ADR: [docs/adr/0265](adr/0265-index-cross-references-page-ranges-and-section-headings.md)",
      "",
      "### 主な原因",
      "",
      "- 範囲の始めの印を書き忘れたか、始めの印を終わりの印より後に置いた。",
      "- 始めの印の語か読みが、終わりの印と違う。",
      "- 範囲の途中に `@index` を置いた。",
      "",
      "### 直し方",
      "",
      "範囲の始めに、終わりと同じ語と読みで `range=begin` の印を置く。",
      "",
      "## G05001",
      "",
      "改行の前後が欧文なので、単語が空白なしにつながります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "段落の中の改行の前後が、ともに欧文の文字である。",
      "段落の中の改行は文字を生まないので、単語が空白なしにつながる。",
      "`line-breaks = \"keep\"` の段落スタイルの段落の行の区切りには当てない。",
      "改行の様式（`[source]` の `paragraph-separator = \"line\"`）のファイルの段落とリストの項目の改行は段落の区切りなので当てず、散文スロットの中の改行にだけ当てる。",
      "",
      "- メッセージ: `改行の前後が欧文なので、単語が空白なしにつながります。一行で書いてください`",
      "- 段階とモジュール: lint（golem-lint の `Golem.Lint`）",
      "- ADR: [golem-lint ADR 0001](golem-lint/adr/0001-lint-rules.md)（定めた）、[docs/adr/0003](adr/0003-verse-line-breaks.md) と [docs/adr/0005](adr/0005-character-and-paragraph-styles.md)（例外を定めた）、[docs/adr/0013](adr/0013-paragraph-separator.md)（改行の様式の扱いを定めた）、[golem-lint ADR 0002](golem-lint/adr/0002-latin-join-after-trailing-spaces.md)（行末の空白の扱いを定めた）",
      "",
      "### 主な原因",
      "",
      "- 欧文の文を、段落の中で改行して書いた。段落の中の改行は文字を生まない。",
      "- 改行の前に半角の空白を置けば単語が分かれると考えて、行末に空白を置いた。言語の仕様は行末の半角の空白とタブを無視するので、単語はやはりつながる（[golem-lint ADR 0002](golem-lint/adr/0002-latin-join-after-trailing-spaces.md)）。",
      "",
      "### 直し方",
      "",
      "欧文の文は一行で書く。",
      "行末の半角の空白では単語は分かれない。",
      "行を保ちたい段落には、`line-breaks = \"keep\"` の段落スタイル（`verse` など）を付ける。",
      "",
