      "## G05004",
      "",
      "参照されていないラベルです",
      "",
      "- 重大度: dev では警告、prod ではエラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@label` で付けたラベルを、どこからも参照していない。",
      "",
      "- メッセージ: `参照されていないラベルです: <ラベル>`",
      "- 段階とモジュール: lint（golem-lint の `Golem.Lint`）",
      "- ADR: [golem-lint ADR 0001](golem-lint/adr/0001-lint-rules.md)",
      "",
      "### 主な原因",
      "",
      "- `@label` で付けたラベルを、どこからも参照していない。",
