      "図版のキャプションに段落でないブロックを置いた出力（ブロックコマンドとフィルタ）の詳細は、`図版のキャプションには段落だけを置けます` である（[docs/adr/0144](adr/0144-figure-captions-hold-paragraphs-only.md)）。",
