      "`width` を段の行長より大きく書いた図版を、行長に縮めた場合も、このコードである（[docs/adr/0190](adr/0190-non-wrapping-figure-width.md)）。",
      "縮めた図版は、行の方向に余りができ、仕上がりの紙の端に近いほうの段の端に寄せた。",
