      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07039\"` を加えると、このお知らせを出さなくなる。",
      "抑制は本の全体の単位であり、図版ごとには抑制できない。",
      "",
      "## G07041",
      "",
