      "",
      "PDF のコードブロックについて、行長から左右の `padding` を引いた幅が、コードの文字の大きさの 8 字分に満たないか、コードの一行と上下の `padding` が一ページの行数に収まらない。",
      "行番号、差分の印、`[code]` の `wrap-mark` を付けたコードブロックでは、それらの列と空きと印の幅も行長から引く。",
      "`[code]` の `continued` を書いた本では、コードの一行、続きの表示の行、上下の `padding` が一ページに収まらない場合も、この誤りとする（[golem-driver ADR 0023](golem-driver/adr/0023-code-block-book-features.md)）。",
      "`style.toml` とファイルの中の定義だけで決まる最上位のコードブロックの行長の不足は、PDF をターゲットに含むときに、ビルドと `golem check` の両方でレイアウトの前に報告し、位置は `style.toml` の先頭（なければ `manifest.toml` の先頭）である。",
      "リストの深い入れ子の中の行長の不足と、一ページに収まらない場合は、レイアウトで報告し、位置はコードブロックの始まりである。",
      "PDF を書かない。",
      "",
      "- メッセージ: `コードブロックの行長が足りません` または `コードブロックの一行が一ページに収まりません`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0017](golem-driver/adr/0017-pdf-code-blocks.md)",
      "",
      "### 主な原因",
      "",
      "- `[paragraph-styles.code]` の `padding` が大きい。",
      "- コードブロックをリストの深い入れ子の中に置いた。",
      "- 行番号の桁が多いか、行番号と差分の印と `wrap-mark` を合わせた幅が大きい。",
      "- 版面の行数が少なく、コードの文字の大きさと `padding` が大きい。",
      "",
      "### 直し方",
      "",
      "`padding` か `size` を小さくするか、コードブロックをリストの浅いところに移す。",
      "## G07044",
      "",
      "索引の段の行長が足りません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[index]` の `columns` が版面の段数と異なり、索引の段の行長（版面の文字の領域の幅を `columns` の段と `column-gap` の段間に分けた値）が、版面の文字の大きさの 8 字分に満たない。",
      "`style.toml` だけで決まるので、PDF をターゲットに含むときは、ビルドと `golem check` の両方で、レイアウトの前に報告する。",
      "PDF を書かない。",
      "位置は `[index]` の `columns` の値である。",
      "",
      "- メッセージ: `索引の段の行長が足りません。columns を減らすか column-gap を狭めてください`",
      "- 段階とモジュール: レイアウト（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0025](adr/0025-index-columns.md)",
      "",
      "### 主な原因",
      "",
      "- 版面の一行の字数に対して、`[index]` の `columns` が多い。",
      "- `column-gap` が広い。",
      "",
      "### 直し方",
      "",
      "`[index]` の `columns` を減らすか、`column-gap` を狭める。",
      "",
      "## G07045",
      "",
      "ルビの親文字の圏点を PDF で描きません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "ルビの親文字の中に圏点があるか、圏点の中にルビがある。",
      "圏点とルビは親文字の同じ側に置くので、PDF は、ルビの親文字に圏点を描かない。",
      "HTML と EPUB は圏点とルビの両方を出すので、PDF をターゲットに含むときだけ出す。",
      "PDF は書く。",
      "位置は、ルビの親文字の中の圏点ではその圏点の位置、圏点の中のルビではそのルビの位置である。",
      "お知らせなので、エラーにも警告にもならず、ビルドの成否に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `ルビの親文字の圏点は PDF では描きません`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0019](golem-driver/adr/0019-pdf-kenten-shapes.md)",
      "",
      "### 主な原因",
      "",
      "- `[ruby: [kenten: 漢]|かん]` のように、ルビの親文字に圏点を付けた。",
      "- `[kenten: [ruby: 漢|かん]]` のように、圏点の中にルビを書いた。",
      "",
      "### 直し方",
      "",
      "PDF で圏点を描くには、圏点を付ける語からルビを外す。",
      "PDF で圏点がなくてよければ、そのままでよい。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07045\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G07046",
      "",
      "罫線を持つ段落か見出しが版面に入りません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "罫線を持つ段落か見出し（段落スタイルか `[headings.N]` の `rule-before`、`rule-after`）が、前の罫線の領域、行、後の罫線の領域を合わせて、空の段にも入らない。",
      "罫線を持つ段落は、罫線を持たない段落と同じく、孤立行と泣き別れの規則で行を段に分けて組む。",
      "分けて組んだ段落には、前の罫線も後の罫線も引かず、罫線の領域の行も取らない（[golem-driver ADR 0035](golem-driver/adr/0035-paragraph-rules-split-and-space-units.md)）。",
      "後の罫線の領域が最後の部分の後に入る場合も引かない。",
      "罫線を持つ見出しは、行を分けず、後の罫線を省き、それでも入らなければ前の罫線も省く。",
      "PDF は書く。",
      "見出しの行だけで空の段に入らない場合は、[G07024](#g07024) である。",
      "位置は、段落か見出しの位置である。",
      "お知らせなので、エラーにも警告にもならず、ビルドの成否に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `罫線を持つ段落が版面に入らないため、罫線を省いて分けて組みました（段落スタイル <名前>）`、`罫線を持つ見出しが版面に入らないため、罫線を省きました（見出し <階層>）`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0027](golem-driver/adr/0027-paragraph-style-rules.md)、[golem-driver ADR 0035](golem-driver/adr/0035-paragraph-rules-split-and-space-units.md)（分けて組んだ段落の罫線）",
      "",
      "### 主な原因",
      "",
      "- 罫線を持つ段落スタイルを、一ページ（段）より長い段落に当てた。",
      "- 見出しの罫線の間隔が大きく、見出しの行と罫線の領域が一ページ（段）に入らない。",
      "",
      "### 直し方",
      "",
      "罫線を持つ段落を短くするか、罫線を持たない段落スタイルにする。",
      "見出しの罫線の間隔を狭める。",
      "分けて組んでよければ、そのままでよい。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07046\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G07047",
      "",
      "段の先頭に来た `@blank-line` の空きを捨てました",
      "",
      "- 重大度: 情報",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF で、行アキが段の先頭に来たので、空きを取らずに捨てた。",
      "段の先頭の空きは前の段の終わりの余白と見分けられず、前後のブロックの区切りにならないためである。",
      "どのようにして段の先頭に来たかによらず捨てる。",
      "前のブロックが段の最後の行で終わった場合、行アキと次のブロックの最初の部分が今の段に入らずに次の段へ送った場合、改ページか改丁する見出しか `@need-lines` で段を改めた直後、本の最初のブロックの前のどれでも同じである。",
      "送った図版が待っているあいだに書いた図版（待つ図版）の前の行アキの後に、本の終わりまで待つ図版しか続かなければ、行アキは待つ図版を置く段の先頭に来るものとして捨てる（[golem-layout ADR 0026](golem-layout/adr/0026-need-lines-and-blank-lines-pass-over-waiting-figures.md)）。",
      "行アキを途中で切り詰めることはしない。",
      "続けて書いた `@blank-line` を捨てた場合は、それぞれの行に出す。",
      "位置は、捨てた `@blank-line` の行である。",
      "情報なので、コマンドに `--verbose`（`-v`）を付けたときにだけ出し、ビルドの成否と出力に影響しない（[docs/adr/0104](adr/0104-info-severity.md)）。",
      "",
      "- メッセージ: `段の先頭に来た @blank-line の空きを捨てました`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`、golem-layout の `Golem.Layout.Paginate`）",
      "- ADR: [docs/adr/0046](adr/0046-blank-line-command.md)、[docs/adr/0104](adr/0104-info-severity.md)（重大度）、[golem-layout ADR 0026](golem-layout/adr/0026-need-lines-and-blank-lines-pass-over-waiting-figures.md)（本の終わりの待つ図版の前の行アキ）",
      "",
      "### 主な原因",
      "",
      "- 場面の区切りの `@blank-line` が、組んだ結果でページか段の境目に来た。",
      "- 改ページの直後に `@blank-line` を書いた。",
      "",
      "### 直し方",
      "",
      "捨ててよければ、そのままでよい。",
      "区切りを必ず見せたい場合は、＊などの印を原稿に書くか、`@page-lines` などで改ページの位置を変える。",
      "`--verbose` を付けたときにこの情報を出したくなければ、`manifest.toml` の `[diagnostics]` の `silence-info` に `\"G07047\"` を加える。",
      "`silence-notices` に書くと [G03024](#g03024) になる。",
      "",
      "## G07050",
      "",
      "隠しノンブルが版面に重なります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "トンボを付けた PDF に入れる隠しノンブルの数字の列の左右の範囲（ノドの仕上がりの線から `[hidden-folio]` の `gutter` の距離にある中心線から、`size` の半分ずつ）が、そのページの版面か傍注の領域に、左右の方向で重なる。",
      "`style.toml` と `--marks` だけで決まるので、PDF をターゲットに含み、`--marks` が `japanese` か `western` のときは、ビルドと `golem check` の両方で、レイアウトの前に報告する。",
      "`[hidden-folio]` の `enabled` が `false` のときと、`--marks none` のときは検査しない。",
      "PDF を書かない。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `隠しノンブルが版面に重なります。[hidden-folio] の gutter を小さくするか、ノドの余白を広げてください`",
      "- 段階とモジュール: レイアウト（golem-layout-spec の `Golem.LayoutSpec`、golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0021](golem-driver/adr/0021-hidden-folios.md)、[golem-driver ADR 0041](golem-driver/adr/0041-hidden-folio-overlap-check-by-size.md)（数字の列の幅を `size` で測ること）",
      "",
      "### 主な原因",
      "",
      "- `[page.grid]` の `position` の `gutter`（ノドの余白）が数ミリしかない。",
      "- `[hidden-folio]` の `gutter` か `size` が大きい。",
      "",
      "### 直し方",
      "",
      "`[hidden-folio]` の `gutter` を小さくするか、`[page.grid]` の `position` の `gutter` を広げる。",
      "中綴じの本のように隠しノンブルが要らない場合は、`[hidden-folio]` に `enabled = false` を書く。",
      "",
      "## G07051",
      "",
      "柱の行が版面の幅を超えています",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF に描く柱の行の幅が、そのページの版面の幅を超える。",
      "柱は版面の幅で折り返さないので、行は小口かノドの余白へ伸びるが、PDF は組める。",
      "同じ行の文字列には一つだけ出し、ページの番号は最初に現れたページとする。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `柱の行が版面の幅を超えています（<ページ> ページ）: <行の文字列>`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0022](golem-driver/adr/0022-running-head-formats.md)",
      "",
      "### 主な原因",
      "",
      "- 柱の書式の一行に、書名と章の題など長い値を並べた。",
      "- 固定の文言が長い。",
      "",
      "### 直し方",
      "",
      "柱の書式の行を二行に分けるか、`@toc-title` で短い題を付ける。",
      "固定の文言を短くする。",
      "",
      "## G07052",
      "",
      "柱の行がページからはみ出しています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` のマスターページの柱の書式の行が多く、最も外側の行の字の外枠が、仕上がりの判型の外に出る。",
      "柱の行は、版面に最も近い行を一行の柱の位置に置き、ほかの行を行送りずつ天（または地）の側へ重ねるので、行を増やすと柱はページの端へ伸びる。",
      "字の外枠は、ベースラインから天の側へ文字の大きさの 0.88 倍、地の側へ残りとする。",
      "行の数は `style.toml` だけで決まるので、PDF をターゲットに含むときは、ビルドと `golem check` の両方で、レイアウトの前に報告する。",
      "PDF を書かない。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `柱の行がページからはみ出しています。行の数を減らすか、天（または地）の余白を広げてください`",
      "- 段階とモジュール: レイアウト（golem-layout-spec の `Golem.LayoutSpec`）",
      "- ADR: [golem-driver ADR 0022](golem-driver/adr/0022-running-head-formats.md)",
      "",
      "### 主な原因",
      "",
      "- 柱の書式の配列の行が、天（または地）の余白に対して多い。",
      "- 天（または地）の余白が狭い。",
      "",
      "### 直し方",
      "",
      "柱の書式の行の数を減らすか、`[page.grid]` の `position` で天（または地）の余白を広げる。",
      "",
      "## G07100",
      "",
      "見出しが段に入りません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF で、見出しが占める格子の行が、見出しを置いた空の段に残る行より多い。",
      "見出しはページをまたいで分けず、空の段には入らなくても置くので、見出しは段の頭から書いたとおりの行取りで組まれ、段の残りの外にはみ出す。",
      "置き方は変えない。",
      "見出しは一ページの行数には収まるので（収まらなければ [G07024](#g07024)）、この場面は `@page-lines` で段の行数を減らしたときに起きる。",
      "段を減らして高い見出しを置く組み方は、特殊な組版で意図して使うことがあるので、エラーにも警告にもしない。",
      "位置は見出しである。",
      "段を減らした `@page-lines` の位置ではない。",
      "改ページの繰り返し（S2）の最後の回の結果から求める。",
      "`golem check` はページ分けを行わないので、このお知らせを出さない。",
      "お知らせなので、ビルドの成否と出力に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `見出しが段に入りません（<階層> の見出し: <題>。見出しは <n> 行、段の残りは <m> 行）`。注の一覧の見出しでは、括弧の中の前半を `注の一覧の見出し: <題>` とする。",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`、golem-layout の `Golem.Layout.Paginate`）",
      "- ADR: [golem-layout ADR 0020](golem-layout/adr/0020-heading-taller-than-column.md)",
      "",
      "### 主な原因",
      "",
      "- `@page-lines` の負の値で段の行数を減らし、その段の先頭に見出しが来た。",
      "",
      "### 直し方",
      "",
      "意図した組み方なら、そのままでよい。",
      "意図していなければ、`@page-lines` で減らす行を少なくするか、`@page-lines` を見出しの後に移すか、`[headings.<階層>]` の `lines` を減らす。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07100\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G07101",
      "",
      "ダッシュの字形に線がないので、二倍ダッシュの線をつながずに描きます",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF で、和文の中の全角のダッシュの連なり（二倍ダッシュ）に、フォントの字形が線（字面の枠）を持たないダッシュがある。",
      "二倍ダッシュは、各ダッシュの字形を送りの方向に拡大縮小し、線を箱の端から端までつなげて描く。",
      "線のない字形は拡大縮小できないので、そのダッシュは拡大縮小せず、箱の中の一字分の区画の始まりに描く。",
      "連なりの一つにつき一度出す。",
      "位置は、連なりの最初のダッシュである。",
      "メッセージのコードポイントとフォントは、連なりの中で最初の、線のないダッシュのものである。",
      "フォントを読まない `golem check` は、このお知らせを出さない。",
      "お知らせなので、ビルドの成否と出力に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `ダッシュの字形に線がないので、二倍ダッシュの線をつながずに描きます: <コードポイント>（<フォントのパス>）`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0172](adr/0172-continuous-double-dashes.md)",
      "",
      "### 主な原因",
      "",
      "- 和文のフォントの `U+2014` か `U+2015` の字形が、線を持たない空の字形である。",
      "",
      "### 直し方",
      "",
      "ダッシュの字形が線を持つフォントを `[fonts]` の役割の `ja` に指定する。",
      "線のないダッシュのままでよければ、そのままでよい。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07101\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G07102",
      "",
      "注の番号を mark-format の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "注の番号を、`style.toml` の `[notes]` の `mark-format` の表記で表せない（[ADR 0177](adr/0177-note-mark-style-and-numerals.md)）。",
      "`note-symbols` は 1 から 7 まで、`circled` は 1 から 50 まで、ローマ数字は 1 から 3999 まで、`aiueo` は 46 まで、`iroha` は 47 までを表せる。",
      "記号の連なりが尽きた後に記号を重ねること、算用数字に戻ること、最初に戻ることはしない。",
      "番号は文書の組み立て（S1）で決まるので、[G07029](#g07029) と同じく出力の段階で報告する。",
      "PDF、HTML、EPUB、プレーンテキストのどれを組んでも報告し、どれも書かない。",
      "同じ入力から同じ diagnostics が出るようにするためである。",
      "位置はその注である。",
      "リストの番号の [G07029](#g07029) とは、直すキーが違うのでコードを分ける。",
      "",
      "- メッセージ: `注の番号 <番号> は、[notes] の mark-format <書式> で表せません`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0177](adr/0177-note-mark-style-and-numerals.md)",
      "",
      "### 主な原因",
      "",
      "- `note-symbols` や `circled` の書式で、番号を振る範囲（`[notes]` の `numbering`）の注が多すぎる。",
      "",
      "### 直し方",
      "",
      "`[notes]` の `numbering` で番号を振り直す範囲を狭めるか、`mark-format` の表記を算用数字（`{n}`）などの表せる表記に替える。",
      "## G07103",
      "",
      "PDF/UA では見出しの段を飛ばせません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[targets.pdf]` に `pdfua` を書いた本で、見出しの段が飛んでいる。",
      "最初の見出しが 1 の段でないか、ある見出しが前の見出しより二つ以上深い。",
      "PDF/UA-1 は、見出しの構造の要素（`H1` から）が段を飛ばさないことを求める。",
      "浅くなる向きには、いくつ段を戻ってもよい。",
      "最初の見出しでは、前の段を 0（文書）として述べる。",
      "`pdfua` を書かない本では調べない。",
      "PDF は書かず、HTML、EPUB、プレーンテキストは書く。",
      "dev と prod の両方でエラーである。",
      "位置はその見出しである。",
      "",
      "- メッセージ: `PDF/UA では見出しの段を飛ばせません: <前の段> から <この段>`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。PDF を書くときに、組む前に調べる",
      "- ADR: [docs/adr/0183](adr/0183-tagged-pdf-and-pdf-a.md)",
      "",
      "### 主な原因",
      "",
      "- 文字の大きさを変えるために、`#` の次に `###` を置いた。",
      "- 章の最初の見出しを `##` で始めた。",
      "",
      "### 直し方",
      "",
      "見出しの段を一つずつ深くする。",
      "見た目を変えたいだけなら、`style.toml` の `[headings]` で段の体裁を変える。",
      "",
      "## G07104",
      "",
      "PDF/A-2a の PDF に私用領域の字は書けません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の `[targets.pdf]` に `pdfa` を書いた本で、PDF に描く字が Unicode の私用領域（U+E000 から U+F8FF、U+F0000 から U+FFFFD、U+100000 から U+10FFFD）の字に対応づけられる。",
      "PDF/A-2a は、私用領域の字に、意味を表す代わりの文字（`ActualText`）を求める。",
      "Golem には私用領域の字の意味が分からないので、書かない。",
      "原稿の一つの位置につき、字ごとに一度出す。",
      "柱、ノンブルなど、Golem が描くすべての字を調べる。",
      "PDF は書かず、HTML、EPUB、プレーンテキストは書く。",
      "dev と prod の両方でエラーである。",
      "位置はその字を含む原稿の位置である。",
      "",
      "- メッセージ: `PDF/A-2a の PDF に私用領域の字は書けません: U+<符号位置>`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。組んだ後、フォントを埋め込む前に調べる",
      "- ADR: [docs/adr/0183](adr/0183-tagged-pdf-and-pdf-a.md)",
      "",
      "### 主な原因",
      "",
      "- 外字や記号を、フォントの私用領域の符号位置で書いた。",
      "",
      "### 直し方",
      "",
      "Unicode に符号位置のある字で書く。",
      "字形が要るなら、図版にして `alt` で意味を書く。",
      "",
      "## G07105",
      "",
      "行が行長からはみ出しています",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、行分割が、行長に収められなかった行を残した。",
      "行分割の最後の段は、改行の位置のあいだの箱の並びだけで行長を超えるときに限り、行長を超える行を作る。",
      "行の自然な幅から縮みの合計（字形の圧縮を含む）と行長を引いた量が正の行を報告し、1sp でもはみ出せば出す。",
      "本文、見出し、表のセル、キャプション、脚注、傍注、目次の題のすべての行を対象とする。",
      "描いた行ごとに一つ出し、別のページにもう一度描く行（表の見出しの行）は、描いたページごとに出す。",
      "位置は、行の箱を行頭から順に見て、終わりが行長を超える最初の箱の、最初の字（長さ 0）である。",
      "その箱が原稿にない字（見出しの番号、目次の題など）なら、その行を含む原稿のブロックの位置とする。",
      "終わりが行長を超える箱がない行も、その行を含む原稿のブロックの位置とする。",
      "dev と prod の両方で警告で、PDF を書き、終了コードを変えない。",
      "お知らせではないので、`silence-notices` と `--no-notices` では抑制できない。",
      "HTML、EPUB、プレーンテキストのターゲットと、`golem check`、LSP では出さない。",
      "`golem preflight` は、同じ行を、同じ位置、同じメッセージ、同じ事実の [G09013](#g09013) とともに出す。",
      "はみ出しを測る位置の箱が改行しない範囲（文字スタイルの `no-break` が真の文字）の箱なら、このコードではなく [G07122](#g07122) を出す（[docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)）。",
      "引用の印の頁の文言（`p.`、`pp.`）と値のあいだでは改行しないので、文言と値を合わせた幅が行長より長い行も、このコードで報告する（[docs/adr/0277](adr/0277-keep-the-page-label-of-a-citation-mark-with-its-value.md)）。",
      "書き手が改行しない範囲を付けたのではないので、印が改行しない範囲の中になければ、G07122 ではなくこのコードを出す。",
      "",
      "- メッセージ: `行が行長から <量> はみ出しています（PDF の <ページ> ページ目）`（例: `行が行長から 1.24mm はみ出しています（PDF の 1 ページ目）`）。`<量>` は mm で、小数点以下 2 桁に切り上げて書く（1sp のはみ出しは `0.01mm`）。事実の `overfull` は、メッセージと同じ表記の `<量>` で、`pdf-pages` はそのページである",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`、golem-preflight の `Golem.Preflight`）",
      "- ADR: [docs/adr/0210](adr/0210-warn-overfull-lines-in-build.md)",
      "",
      "### 主な原因",
      "",
      "- 分割できない長い語や URL がある。",
      "- 長い識別子を本文の中のコード（`[code: …]`）に書いた。コードの欧文の並びは、空白、`/` の後、`_` の連なりの後、`-` と `.` の連なりの後（数字のあいだを除く）でしか改行しない。",
      "- 行長が短い。",
      "- 行長の短い組版（表のセルなど）に、頁を指定した引用の印（`[cite knuth1981 page=5...7]`）を書いた。",
      "",
      "### 直し方",
      "",
      "語を分けられるようにするか、文を書き換える。",
      "URL の文字スタイルの `tracking` を負にして、字の送りを詰める方法もある。",
      "",
      "## G07106",
      "",
      "ノンブルを書式の表記で表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "ページのノンブルを、`style.toml` の `[masters.<名前>]` の `folio` の `format` の表記で表せない（[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "ノンブルの番号は、ページラベルの番号である（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)）。",
      "G07106 は、`format` に書いた表記（`{n:circled}` など）で書けない場合に限る。",
      "表記を書かない `{n}` がページのセクションの表記で書けない場合は、[G07110](#g07110) だけを出し、G07106 は出さない。",
      "表せる範囲は [G04012](#g04012) と同じである。",
      "算用数字やほかの表記に替えては書かない。",
      "ノンブルは PDF だけが描くので、PDF をターゲットに含むときだけ報告し、PDF を書かない。",
      "HTML、EPUB、プレーンテキストは書く。",
      "ページを決めた後、ノンブルを描く前に調べる。",
      "マスターページごとに一つだけ出し、番号は、そのマスターページを使うページのうち、表せない最初のページのノンブルである。",
      "白ページのようにノンブルを描かないページは調べない。",
      "位置は `[masters.<名前>]` の `folio` の `format` の値である。",
      "",
      "- メッセージ: `[masters.<名前>] の folio の format <書式> の {<差し込み>} では、ノンブル <番号> を表せません`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0213](adr/0213-numbers-the-number-formats-cannot-write.md)",
      "",
      "### 主な原因",
      "",
      "- 丸数字のように表せる範囲の小さい表記をノンブルに使い、本のページが多すぎる。",
      "",
      "### 直し方",
      "",
      "`[masters.<名前>]` の `folio` の `format` を、算用数字（`{n}`）などの表せる表記に替える。",
      "",
      "## G07107",
      "",
      "構造の木にない内容を描きました",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF のページに描いた印付きの内容のうち、構造の木にないもの（孤立した葉）がある。",
      "構造の木を作る処理と、描く箱に葉の番号を振る処理が食い違ったときにだけ起き、原稿では起こせない。",
      "孤立した葉を PDF に書くと、読む順では文書の最後になり、本来の構造の型を失うので、PDF を書かない。",
      "HTML、EPUB、プレーンテキストは書く。",
      "孤立した葉の数にかかわらず、PDF ごとに一つだけ出す。",
      "dev と prod の両方で、`pdfa` と `pdfua` の宣言によらずエラーである。",
      "位置は、最初に描いた孤立した葉の原稿の位置である。",
      "本文の葉はそのブロックの位置、脚注と傍注の葉はその注の位置で、引けないときは `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `構造の木にない内容を描きました（<n> か所）。Golem の誤りです。この入力を添えて報告してください`。`<n>` は孤立した葉の異なるものの数である",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。すべてのページを描いた後、PDF を書く前に調べる",
      "- ADR: [docs/adr/0216](adr/0216-drawn-content-missing-from-the-structure-tree-is-an-error.md)",
      "",
      "### 主な原因",
      "",
      "- Golem の誤り。構造の木を作る処理に、単位の種類か場所を足し忘れた。",
      "",
      "### 直し方",
      "",
      "利用者が直すことはない。",
      "このコードが出たら、Golem の誤りとして、その入力を添えて報告する。",
      "",
      "## G07108",
      "",
      "表のセルが多すぎて PDF に組めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF に組む表のセルの数が、一つの表で 100,000 を超えた。",
      "セルの数は、見出しの行と本体の行のセルの数の合計である。",
      "見出しの行がすべて空のセル（見出しのない表）でも、そのセルを数える。",
      "上限は表の出所によらず、`@table` の CSV と TSV、`.gm` の `|` の表、Emet の `Block.table`、プラグインのブロックの表のどれにも当たる。",
      "セルを一つも組む前に数え、超えていればその表を組まない。",
      "この表には [G07041](#g07041) と [G07042](#g07042) を出さない。",
      "PDF は書かない。",
      "HTML、EPUB、プレーンテキストには、この上限はない。",
      "PDF を組まない `golem check` と LSP は、このコードを出さない。",
      "dev でも prod でもエラーである。",
      "位置は表のブロックである。",
      "",
      "- メッセージ: `表のセルが多すぎて PDF に組めません（<n> 個、上限は 100000 個）`。n はその表のセルの数である",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0224](adr/0224-limit-the-cells-of-a-table-set-in-pdf.md)",
      "",
      "### 主な原因",
      "",
      "- データの一覧をそのまま表にしようとした。",
      "- Emet の関数が、意図より多くの行を作った。",
      "",
      "### 直し方",
      "",
      "表を分け、一つの表のセルを 100,000 以下にする。",
      "10,000 行の表なら 10 列まで、2,000 行の表なら 50 列までである。",
      "上限は設定では変えられない。",
      "",
      "## G07109",
      "",
      "page-numbering のセクションにページがありません",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の項目の `page-numbering` で始めたセクションが、ページを一つも持たない（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)）。",
      "後の項目のセクションが同じページから始まった場合と、本がそのセクションの改ページの後に何も置かずに終わった場合である。",
