      "ページは PDF だけが持つので、PDF をターゲットに含むときだけ、収束した最終回のページから求める。",
      "位置はそのセクションの `page-numbering` の値である。",
      "",
      "- メッセージ: `page-numbering のセクションにページがありません。後の項目のセクションが同じページから始まるか、本がこのセクションの改ページの後に終わっています`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0260](adr/0260-front-matter-folios-and-page-labels.md)",
      "",
      "### 主な原因",
      "",
      "- `page-numbering` を書いたファイルが空で、次の項目も `page-numbering` を書いている。",
      "- 本の最後のファイルが空で、`page-numbering` を書いている。",
      "",
      "### 直し方",
      "",
      "働いていない `page-numbering` を消すか、空のファイルに内容を書く。",
      "",
      "## G07110",
      "",
      "page-numbering の style ではノンブルを表せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`manifest.toml` の章の項目の `page-numbering` の `style` の表記で、そのセクションのページの番号を書けない（[ADR 0260](adr/0260-front-matter-folios-and-page-labels.md)、[ADR 0213](adr/0213-numbers-the-number-formats-cannot-write.md)）。",
      "表せる範囲は [G04012](#g04012) と同じである（`circled` は 50 まで、`upper-roman` と `lower-roman` は 3999 まで）。",
      "ノンブルを描かないページも、PDF のページラベルとして書くので調べる。",
      "セクションごとに、書けない最初のページについて一つだけ出し、出す順はマニフェストのセクションの順である。",
      "PDF をターゲットに含むときだけ報告し、PDF を書かない。",
      "HTML、EPUB、プレーンテキストは書く。",
      "マスターページの `folio` の `format` の表記を書かない `{n}` がこの理由で書けないときは、G07110 だけを出し、[G07106](#g07106) は出さない。",
      "位置はそのセクションの `page-numbering` の `style` の値である。",
      "",
      "- メッセージ: `page-numbering の style <表記> では、ノンブル <番号> を表せません（<通し番号> ページ）`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。ページを決めた後、ノンブルを描く前に調べる",
      "- ADR: [docs/adr/0260](adr/0260-front-matter-folios-and-page-labels.md)",
      "",
      "### 主な原因",
      "",
      "- 丸数字のように表せる範囲の小さい表記をセクションに使い、セクションのページが多すぎる。",
      "",
      "### 直し方",
      "",
      "`style` を、そのセクションのページの数を表せる表記（`lower-roman`、`arabic` など）に替える。",
      "",
      "## G07111",
      "",
      "段落スタイルの keep-with-next を守れませんでした",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`keep-with-next` を書いた段落スタイルの段落の最後の行と、後に続くものの最初の部分を、同じ段に置けなかった（[ADR 0261](adr/0261-keep-options-of-paragraph-styles.md)）。",
      "後が送った図版の場合、後が `page-break` の段落か改丁の見出しで段を改めた場合、本の末尾の場合、合わせて段に入らない場合である。",
      "`@no-page-break` の [G07037](#g07037) と同じく、指定を守らずに組んだ結果なので警告とする。",
      "同じ位置に `@no-page-break` があれば、両方を報告する。",
      "PDF をターゲットに含むときだけ、改ページの繰り返しの最後の回の結果から求める。",
      "位置は段落の範囲である。",
      "",
      "- メッセージ: `段落スタイル <名前> の keep-with-next を守れませんでした`",
      "- 段階とモジュール: レイアウト（golem-layout の `Golem.Layout.Paginate`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0261](adr/0261-keep-options-of-paragraph-styles.md)",
      "",
      "### 主な原因",
      "",
      "- 連動の連なりが長く、段に入らない。",
      "- 連動する段落の後に、図版や `page-break` の段落を置いた。",
      "",
