      "",
      "段落を分けるか、その段落には `keep-all-lines` を当てない。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07112\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G07113",
      "",
      "段の行が足りないので、段落の部分を短くしました",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
