      "- 段階とモジュール: レイアウト（golem-layout の `Golem.Layout.Paginate`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0261](adr/0261-keep-options-of-paragraph-styles.md)",
      "",
      "### 主な原因",
      "",
      "- 段の行の数が少ない。`@page-lines` で段を短くした。",
