      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "表の `@column-widths` で `auto` でない列に指定した幅の合計が、列が分け合う幅（行長から列の間隔の和を引いた幅）を超える（[docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)）。",
      "`zw` はセルの段落スタイルの文字の大きさに、`%` は列が分け合う幅に掛け、どちらも sp の未満を切り捨ててから足す。",
      "表を組まない。",
      "PDF を組むときにだけ出す。",
