      "",
      "- メッセージ: `表の列に指定した幅の合計（<幅>）が、列の間隔を除いた行長（<幅>）を超えます`。幅は [G07041](#g07041) と同じく mm で書く",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0262](adr/0262-table-numbers-captions-column-widths-and-cell-styles.md)",
