      "キャプションを短くするか、表の行を分ける。",
      "",
      "## G07117",
      "",
      "目次の項目の行の長さが、段落スタイルの一字に足りません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "目次の階層 l の項目の行の長さ（段の行長から、最も大きい行の字下げ、`end-indent`、ページ番号の予約の幅 R を引いた長さ）が、段落スタイル `toc-<l>` の文字の大きさの一字に満たない（[ADR 0264](adr/0264-paragraph-styles-for-toc-entries.md)）。",
      "字下げを大きく書いた設定で、題が一字も置けない行を黙って組まないためである。",
      "`@toc` の `depth` 以下の階層で、その階層の項目が目次にあるときだけ、階層ごとに一つ出す。",
      "PDF をターゲットに含むときだけ報告し、PDF を書かない。",
      "HTML、EPUB、プレーンテキストは書く。",
      "位置は、`style.toml` に `toc-<l>` の表を書いていればその表、書いていなければ `@toc` の位置である。",
      "",
      "- メッセージ: `目次の階層 <l> の項目の行の長さが、段落スタイル toc-<l> の一字に足りません。indent、first-line-indent、end-indent を狭めてください`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0264](adr/0264-paragraph-styles-for-toc-entries.md)",
      "",
      "### 主な原因",
      "",
      "- `toc-<l>` の `indent` か `end-indent` を、段の行長に比べて大きく書いた。",
      "- 段の行長の短い版面で、深い階層の項目の字下げが残る行を食いつぶした。",
      "",
      "### 直し方",
      "",
      "`toc-<l>` の `indent`、`first-line-indent`、`end-indent` を狭めるか、`@toc` の `depth` を浅くする。",
      "",
      "## G07118",
      "",
      "索引の範囲の終わりのページが、始めのページより前にあります",
