      "## G07120",
      "",
      "リンクの元かしおりの項目の行先が、描いたページにありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF の文書の中のリンクの元（相互参照、注の印、目次の項目、索引のページ番号、引用の番号）か、しおりの項目の行先が、描いたページにない（[ADR 0267](adr/0267-pdf-bookmarks-and-links-inside-the-document.md)）。",
      "行先を集める処理とリンクの元を作る処理が食い違ったときにだけ起き、原稿では起こせない。",
      "行先のないリンクを黙って落とすと出力を黙って変えることになるので、PDF を書かない。",
      "HTML、EPUB、プレーンテキストは書く。",
      "行先のないリンクの元としおりの項目の数にかかわらず、PDF ごとに一つだけ出す。",
      "dev と prod の両方でエラーである。",
      "位置は、最初に描いたリンクの元の原稿の位置で、しおりの項目なら見出しのブロックである。",
