      "- メッセージ: `リンクの元かしおりの項目の行先が、描いたページにありません（<n> か所）。Golem の誤りです。この入力を添えて報告してください`。`<n>` は、行先のないリンクの元としおりの項目の、原稿の位置の異なるものの数である",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）。すべてのページを描いた後、PDF を書く前に調べる",
