      "",
      "利用者が直すことはない。",
      "このコードが出たら、Golem の誤りとして、その入力を添えて報告する。",
      "",
      "## G07121",
      "",
      "段落スタイルの囲みの一行と上下の padding が段に収まりません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、囲みを持つ段落スタイル（`background` か `border` を持つ段落スタイル）の段落について、空の段に、囲みの前の k 行、一行、囲みの後の k 行が入らない。",
      "k は、`padding` を収めるために囲みが最初の行の前と最後の行の後に足す格子の行の数であり、行送りを p、格子の字面の高さを h、`padding` を d として、`(p − h)/2 + k × p ≥ d` を満たす最も小さい 0 以上の整数である。",
      "2k + 1 が段の行の数を超えると、どの段にも囲みの部分を置けない。",
      "版面と `padding` だけで決まるので、組む前に検査する。",
      "位置は、その段落スタイルの最初の段落であり、同じ段落スタイルには一度だけ出す。",
      "PDF を書かない。",
      "",
      "- メッセージ: `段落スタイル <名前> の囲みの一行と上下の padding が段に収まりません`",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0271](adr/0271-paragraph-backgrounds-and-borders.md)",
      "",
      "### 主な原因",
      "",
      "- 段落スタイルの `padding` が、段の高さに比べて大きい。",
      "- `[page.grid]` の `lines` が少ない。",
      "",
      "### 直し方",
      "",
      "段落スタイルの `padding` を小さくするか、`[page.grid]` の `lines` を増やす。",
      "",
      "## G07122",
      "",
      "改行しない範囲が行に収まりません",
      "",
      "- 重大度: 警告",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、改行しない範囲（文字スタイルの `no-break` が真の文字）が行に収まらず、行が行長からはみ出した。",
      "改行しない範囲の中では分割の候補を置かないので、範囲が行長より長ければ、範囲を分けずにはみ出す行を作る。",
      "はみ出しを測る位置（行の箱を行頭から見て、終わりが行長を超える最初の箱）が範囲の中の箱なら、[G07105](#g07105) の代わりにこのコードを出す。",
      "一つの行には、G07105 かこのコードのどちらか一つだけを出す。",
      "重大度、位置、量の書き方、事実、描いたページごとに出すこと、dev と prod の扱い、`golem check` と LSP で出さないことは G07105 と同じである。",
      "`golem preflight` は、同じ行を [G09013](#g09013) でも報告する。",
      "",
      "- メッセージ: `改行しない範囲が行に収まりません。行が行長から <量> はみ出しています（PDF の <ページ> ページ目）`。`<量>` と事実は G07105 と同じである",
      "- 段階とモジュール: レイアウト（golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)",
      "",
      "### 主な原因",
      "",
      "- `[style no-break: …]` に、行に収まらない長さの文字列を入れた。",
      "- `no-break = true` の文字スタイルを、長い範囲に当てた。",
      "",
      "### 直し方",
      "",
      "改行しない範囲を短くするか、範囲を外す。",
      "範囲の中で改行してよい位置があれば、そこで範囲を二つに分ける。",
      "",
      "## G07123",
      "",
      "前後が語の字でないソフトハイフンを、分割の候補にしませんでした",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、ソフトハイフン（U+00AD か `[shy]`）の前か後ろが、同じ欧文の語の要素の字（一般カテゴリが L の字）でなかった。",
      "そのソフトハイフンは分割の候補にならず、何も描かない。",
      "句読点の前（`a[shy].`）、語の終わり、和文の字のあいだのソフトハイフンがこれにあたる。",
      "要素の最初の字より前のソフトハイフン（`[shy]table`）は、その要素を分けない指定なので、このコードを出さない。",
      "語が文字スタイルなどのインラインの境目で分かれていても、語の字は境目の両側の字をつないだ語で数える（[ADR 0285](adr/0285-read-soft-hyphens-at-inline-boundaries-in-the-joined-word.md)）。",
      "`a[shy][strong: b]` のソフトハイフンは分割の候補になり、このコードを出さない。",
      "位置はソフトハイフンで、`[shy]` で書いたものは `[shy]` である。",
      "一つの文字列に複数あれば、それぞれに出す。",
      "HTML、EPUB、プレーンテキストだけのビルドと、`golem check`、LSP では出さない。",
      "",
      "- メッセージ: `ソフトハイフンの前か後ろが語の字でないので、分割の候補にしません`",
      "- 段階とモジュール: レイアウト（golem-layout の `Golem.Layout.Japanese`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)、[ADR 0285](adr/0285-read-soft-hyphens-at-inline-boundaries-in-the-joined-word.md)",
      "",
      "### 主な原因",
      "",
      "- `[shy]` を書く位置が一字ずれた。",
      "- 和文の文章に、U+00AD を含む文字列を貼り付けた。",
      "",
      "### 直し方",
      "",
      "語を分けたい位置（字と字のあいだ）に書き直すか、ソフトハイフンを消す。",
      "",
      "## G07124",
      "",
      "改行しない文字の中か隣のソフトハイフンを、分割の候補にしませんでした",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、改行しない文字の中か隣にソフトハイフン（U+00AD か `[shy]`）があった。",
      "改行しない文字は、本文の中のコード、文字スタイル `url` の文字、リンクの語、改行しない範囲（文字スタイルの `no-break` が真の文字）である。",
      "そのソフトハイフンは分割の候補にならず、何も描かない。",
      "前か後ろが語の字でないソフトハイフンでも、改行しない文字の中にあれば、[G07123](#g07123) ではなくこのコードを出す。",
      "ソフトハイフンが改行しない文字の外にあっても、インラインの境目の両側の字をつないだ語で前の字と後の字がどちらも語の字であり、そのどちらかが改行しない文字なら、このコードを出す（`[link \"https://example.com/\": abc][shy]def`）。",
      "後の字が語の字でないもの（`[link \"https://example.com/\": abc][shy].`）は、[G07123](#g07123) である。",
      "要素の最初の字より前のソフトハイフンには出さない（コードと `url` の文字の中を除く）。",
      "位置はソフトハイフンで、`[shy]` で書いたものは `[shy]` である。",
      "HTML、EPUB、プレーンテキストだけのビルドと、`golem check`、LSP では出さない。",
      "",
      "- メッセージ: `改行しない文字（コード、URL、リンク、改行しない範囲）の中か隣のソフトハイフンなので、分割の候補にしません`",
      "- 段階とモジュール: レイアウト（golem-layout の `Golem.Layout.Japanese`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0272](adr/0272-discretionary-hyphens-hyphenation-exceptions-and-no-break.md)、[ADR 0285](adr/0285-read-soft-hyphens-at-inline-boundaries-in-the-joined-word.md)、[ADR 0297](adr/0297-report-soft-hyphens-next-to-unbreakable-characters-as-g07124.md)",
      "",
      "### 主な原因",
      "",
      "- コードやリンクの語の中か隣に `[shy]` を書いた。",
      "- 改行しない範囲の中で、語を分けられると考えた。",
      "",
      "### 直し方",
      "",
      "ソフトハイフンを消す。",
      "分けたい位置があるなら、その位置が改行しない範囲の外になるように範囲を分ける。",
      "",
      "## G07126",
      "",
      "約物の字面が隣の字にかかります",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、JLReq の規則で前後の空きを決める約物（始め括弧類、終わり括弧類、句点類、読点類、中点類）の一字の字面が、同じ行の隣の字にかかった。",
      "字面は、フォントの字形の枠（FreeType の枠）の、行の方向の範囲である。",
      "字面がトラッキングを除いた箱の端から出た量が、その側の隣の箱とのあいだの空き（グルーとカーンを置いた幅）より大きいときに出す。",
      "隣に箱がない行の端と、ぶら下げた句読点には出さない。",
      "負のトラッキングで詰めたことだけによる重なりにも出さない。",
      "欧文の語の中の字の重なりは、このコードの対象ではない。",
      "フォントのファイルとコードポイントの組ごとに一度出す。",
      "位置は、その組の、原稿の順で最初の約物である。",
      "HTML、EPUB、プレーンテキストだけのビルドと、`golem check`、LSP では出さない。",
      "お知らせなので、ビルドの成否と出力に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `約物の字面が隣の字にかかります: <コードポイント>（<フォントのパス>）`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [ADR 0302](adr/0302-full-width-glyphs-for-punctuation-and-boxes-for-narrower-ones.md)",
      "",
      "### 主な原因",
      "",
      "- 約物の字形の字面が、フォントの送りの外まで描かれている（斜体の引用符など）。",
      "- 文字スタイルの `features` か `punctuation-width = \"font\"` で、字面の広い字形を選んだ。",
      "",
      "### 直し方",
      "",
      "約物の字面が送りの中にあるフォントを、`[fonts]` の役割に指定する。",
      "重なりが目立たなければ、そのままでよい。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G07126\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G08001",
      "",
      "フォントを読まずに PDF を作ろうとしました",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "フォントを読まない `noFontProvider` で PDF を作ろうとした。",
      "`golem` のコマンドは本物のフォントの読み込みを使うので、利用者がこのコードを見ることはない。",
      "テストが、フォントなしで PDF の経路の手前までを確かめるために使う。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `フォントを読まない設定（noFontProvider）では PDF を出力できません`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- テストがフォントを読まない `noFontProvider` で PDF を作ろうとした。`golem` のコマンドは本物のフォントの読み込みを使うので、利用者がこのコードを見ることはない。",
      "",
      "### 直し方",
      "",
      "利用者が直すことはない。",
      "`golem` のコマンドでこのコードが出たら、Golem の誤りとして報告する。",
      "",
      "## G08002",
      "",
      "PDF のフォントのファイルがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF が使う役割のフォントのファイルがないか、パスが不正である。",
      "PDF を書かない。",
      "`golem check` も報告する。",
      "LSP は出さない。",
      "位置は `style.toml` の先頭である。",
      "本文のフォントの設定がない場合は [G08007](#g08007) である。",
      "",
      "- メッセージ: `フォントのファイルがありません: <パス>`、またはパスの誤りの文言（`絶対パスは使えません: <パス>` など）",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset.FontProvider`）",
      "- ADR: [golem-project ADR 0004](golem-project/adr/0004-font-file-check-per-target.md)（ターゲットごとの検査を定めた）、[golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)（本文のフォントの設定の欠けを G08007 に分けた。[golem-cli ADR 0003](golem-cli/adr/0003-new-project-page-and-fonts.md) も触れる）",
      "",
      "### 主な原因",
      "",
      "- `style.toml` の `[fonts]` のパスの綴りを誤ったか、ファイルを置いていない。",
      "- `golem new --no-fonts` で作ったプロジェクトに、まだフォントを置いていない。",
      "",
      "### 直し方",
      "",
      "`style.toml` の `[fonts]` のパスを直すか、指すファイルを置く。",
      "",
      "## G08003",
      "",
      "フォントを読み込めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF が使う役割のフォントのファイルを、OpenType（TrueType の輪郭か CFF の輪郭）のフォントとして開けない。",
      "読み込めないファイルをすべて、パスごとに一つずつ報告する。",
      "PDF を書かない。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `フォントを読み込めません: <パス>`。パスは `style.toml` に書いたとおりである。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset.FontProvider`）",
      "- ADR: [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- フォントのファイルが壊れている。",
      "- OpenType として読めない、対応しない形式である。",
      "- 輪郭の表（`CFF ` も `glyf` も）がない。",
      "",
      "### 直し方",
      "",
      "別のファイルを指す。",
      "",
      "## G08004",
      "",
      "ライセンスが埋め込みを禁じているフォントです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "フォントの OS/2 の `fsType` が、PDF への埋め込みを禁じている。",
      "OpenType の仕様に従い、次のどれかに当てはまれば埋め込まない。",
      "ビット 1（`0x0002`、制限付きのライセンス）が立ち、ビット 2（`0x0004`）とビット 3（`0x0008`）が立っていない。",
      "ビット 8（`0x0100`、サブセット化の禁止）が立っている。",
      "Golem はサブセットしか埋め込まないためである。",
      "ビット 9（`0x0200`、ビットマップの埋め込みだけを許す）が立っている。",
      "読み込めないファイルをすべて、パスごとに一つずつ報告する。",
      "PDF を書かない。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `ライセンスが埋め込みを禁じているフォントです（fsType <値>）: <パス>`。値は `0x0102` のように `0x` と 4 桁の大文字の 16 進数で書く。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset.FontProvider`、golem-font の `Golem.Font`）",
      "- ADR: [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)（[golem-font ADR 0001](golem-font/adr/0001-shaping-and-metrics.md) がエラーにすると定めた）",
      "",
      "### 主な原因",
      "",
      "- フォントの OS/2 の `fsType` が、PDF への埋め込みかサブセット化を禁じている。",
      "",
      "### 直し方",
      "",
      "埋め込みとサブセット化を許すフォントに替える。",
      "",
      "## G08005",
      "",
      "PostScript 名が同じ異なるフォントがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "バイト列の異なる二つのフォントのファイルが、同じ PostScript 名を持つ。",
      "[G08003](#g08003) と [G08004](#g08004) がないときだけ検査する。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `PostScript 名が同じ異なるフォントがあります: <名前>（<パス>、<パス>）`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset.FontProvider`）",
      "- ADR: [golem-driver ADR 0003](golem-driver/adr/0003-pdf-heading-styles.md)（位置は [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)）",
      "",
      "### 主な原因",
      "",
      "- 同じフォントの別のバージョンを混ぜている。",
      "",
      "### 直し方",
      "",
      "どちらか一方のファイルにそろえる。",
      "",
      "## G08006",
      "",
      "出力インテントの ICC プロファイルがありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF を作るときに、`[color]` の `intent` が指す ICC プロファイルのファイルがないか、パスが不正である。",
      "PDF を書かない。",
      "LSP は出さない。",
      "",
      "- メッセージ: `出力インテントの ICC プロファイルがありません: <パス>`、またはパスの誤りの文言（`絶対パスは使えません: <パス>` など）",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-project ADR 0004](golem-project/adr/0004-font-file-check-per-target.md)",
      "",
      "### 主な原因",
      "",
      "- `[color]` の `intent` のパスの綴りを誤ったか、ファイルを置いていない。",
      "- パスが絶対パスなど、使えない形である。",
      "",
      "### 直し方",
      "",
      "ICC プロファイルのファイルを置くか、パスを直す。",
      "",
      "## G08007",
      "",
      "PDF の本文のフォントの設定がありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含むのに、`style.toml` の `[fonts]` に役割が一つもないか、本文の役割に `ja` も `latin` もない。",
      "本文の役割は `body` で、`[fonts]` に `body` がなければ名前の順で最初の役割である。",
      "`golem check` も報告し、PDF のレイアウトに進まない。",
      "LSP は出さない。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `style.toml に本文のフォントがありません。[fonts.body] を書いてください`、`[fonts.<役割>] にフォントのファイルがありません`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`）",
      "- ADR: [golem-driver ADR 0016](golem-driver/adr/0016-output-and-layout-diagnostic-codes.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` に `[fonts.body]` を書いていない。",
      "- 本文の役割に `features` だけを書き、`ja` と `latin` を書いていない。",
      "",
      "### 直し方",
      "",
      "`style.toml` に `[fonts.body]` を書き、`ja` か `latin` にフォントのファイルのパスを書く。",
      "",
      "## G08008",
      "",
      "コードの書体の役割がありません",
      "",
      "- 重大度: お知らせ",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "本にコードブロックかコードの文字スタイル（`code` と、`based-on` で `code` に行き着く文字スタイル）の文字があるのに、`style.toml` に `[fonts.code]` がない。",
      "PDF はコードを本文の役割で組む。",
      "一回のビルドで一つだけ出し、PDF は書く。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "`code` の段落スタイルか文字スタイルの `font` を別の役割に変え、その役割が `[fonts]` にない場合は [G03008](#g03008) である。",
      "お知らせなので、エラーにも警告にもならず、ビルドの成否に影響しない（[golem-syntax ADR 0002](golem-syntax/adr/0002-notice-severity.md)）。",
      "",
      "- メッセージ: `コードの書体の役割 code がないので、本文の書体で組みます`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0017](golem-driver/adr/0017-pdf-code-blocks.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` に、コード用の書体の役割 `[fonts.code]` を書いていない。`golem new` の雛形は書かない。",
      "",
      "### 直し方",
      "",
      "`style.toml` に `[fonts.code]` を書き、等幅の書体のファイルを `latin`（和文も載せるなら `ja`）に書く。",
      "本文の書体で組んでよければ、そのままでよい。",
      "`manifest.toml` の `[diagnostics]` の `silence-notices` に `\"G08008\"` を加えると、このお知らせを出さなくなる。",
      "",
      "## G08009",
      "",
      "圏点の字が書体にありません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "圏点を付けた字の役割の和文の書体に、圏点の形の字（`sesame` なら U+FE45 の `﹅`）がない。",
      "書体にない字は `.notdef` の箱で描かれるので、PDF を書く前に止める。",
      "役割と形の組ごとに一つだけ出す。",
      "PDF を書かない。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `役割 <役割> の和文の書体に圏点の形 <形> の字（U+<符号位置>）がありません`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`）",
      "- ADR: [golem-driver ADR 0019](golem-driver/adr/0019-pdf-kenten-shapes.md)",
      "",
      "### 主な原因",
      "",
      "- 和文の役割に、圏点の字を持たない書体（欧文の書体など）を指定した。",
      "- `[kenten ...]` の `shape` か `style.toml` の `[composition]` の `kenten` に、書体にない形を書いた。",
      "",
      "### 直し方",
      "",
      "`shape`（または `[composition]` の `kenten`）を、書体にある形に替える。",
      "あるいは、圏点の字を持つ書体を、その役割の `ja` に指定する。",
      "## G08010",
      "",
      "図版を PDF に置けません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`@figure` の画像のファイルはあるが、PDF に置ける形で読めない。",
      "PNG と JPEG の図版は画像として読めないとき、PDF の図版は Golem が取り込めないときに出す。",
      "PNG の tRNS のチャンクが PNG の仕様に反するときも、画像として読めないものとして出す（[golem-pdf ADR 0014](golem-pdf/adr/0014-png-trns-transparency.md)）。",
      "理由は次のとおりである。",
      "",
      "- tRNS が二つ以上ある：`PNG に tRNS が二つ以上あります`",
      "- 色の種類 4 か 6（アルファのチャンネルを持つ PNG）に tRNS がある：`アルファのある PNG に tRNS があります`",
      "- パレットの PNG の tRNS が、パレットの色の数より長い：`PNG の tRNS がパレットより長いです`",
      "- グレーの PNG の tRNS が 2 バイトでない、RGB の PNG の tRNS が 6 バイトでない：`PNG の tRNS の長さが色の種類に合いません`",
      "",
      "tRNS を持つ PNG の画素の数（幅 × 高さ）が 2^29 を超えるときは、理由を `tRNS を持つ PNG の画素が多すぎます` として出す。",
      "透過を表すアルファの面が画素ごとに 1 バイトを使うためで、フィルタの前の画素のデータの上限（`PNG の画像が大きすぎます`）とは別の上限である。",
      "SVG の図版は、XML として読めないとき、UTF-8 でないとき、内部サブセットを持つ `DOCTYPE` があるとき、大きさ（ルートの `width` と `height` か `viewBox`）がないときに出す（[golem-pdf ADR 0009](golem-pdf/adr/0009-svg-figures.md)）。",
      "大きさの数の絶対値が 10^9 を超えるときも、大きさがないときと同じく、理由を `大きさの数が大きすぎます` として出す（[docs/adr/0041](adr/0041-svg-marker-and-number-limits.md)）。",
      "大きさの数が 0 でなく、絶対値が 10^-9 より小さいときは、理由を `大きさの数が小さすぎます` として出す（[docs/adr/0083](adr/0083-svg-number-lower-limit.md)）。",
      "大きすぎる数と小さすぎる数の両方があれば、理由は `大きさの数が大きすぎます` である。",
      "SVG の範囲の外のものは [G08011](#g08011) である。",
      "PDF の図版を取り込めないのは、次のどれかの場合である。",
      "",
      "- 相互参照などが壊れている。",
      "- 暗号化されている。",
      "- `page` のページがない。",
      "- 扱わない圧縮（`LZWDecode`、`JBIG2Decode`、`JPXDecode` など）を使っている。",
      "- 埋め込んでいないフォントがある。",
      "- 特色（Separation か DeviceN）がある。",
      "- RGB のインライン画像がある。",
      "- レイヤー（オプショナルコンテンツ）がある。",
      "- `UserUnit` が 1 でない。",
      "- 展開した大きさの合計が 256 MiB を超える。理由は `PDF として読めません（展開した大きさが上限を超えました）` である。",
      "- ページの木で、一つのノードを二度指している（同じ `Page` を二つの `Kids` から指すなど）。理由は `PDF として読めません（ページの木）` である。",
      "- 相互参照の項目の数が、すべての改訂を合わせて 8,388,607 を超える。理由は `PDF として読めません（相互参照）` である。",
      "- Flate の予測子の `Colors`、`BitsPerComponent`、`Columns` が範囲の外にある。理由は `PDF として読めません（予測子）` である。",
      "",
      "最後の四つは、取り込みの資源の上限である（[docs/adr/0040](adr/0040-pdf-import-resource-limits.md)）。",
      "ページの `Contents` をつないだ内容が 256 MiB を超える場合は、このコードではなく [G08015](#g08015) である。",
      "ページが二度以上名指すストリームの番号が 2147483647 を超える場合も、このコードではなく [G08020](#g08020) である。",
      "壊れている PDF の理由は `PDF として読めません（<箇所>）` の形であり、`ページの木` と `相互参照` の箇所は、上限を超えた場合とそのほかの壊れ方で同じ文言になる。",
      "上限の値と数え方は [golem-pdf の仕様書](golem-pdf/specifications.md) にある。",
      "",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "dev と prod の両方でエラーである。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出す。",
      "HTML、EPUB、プレーンテキストでは出さない。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `図版を PDF に置けません: <パス>（<理由>）`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset`、golem-pdf の `Golem.Pdf.Image` と `Golem.Pdf.Import`、golem-svg の `Golem.Svg`）",
      "- ADR: [golem-pdf ADR 0008](golem-pdf/adr/0008-pdf-figures.md)、[docs/adr/0040](adr/0040-pdf-import-resource-limits.md)、[docs/adr/0041](adr/0041-svg-marker-and-number-limits.md)（SVG の大きさの数）、[docs/adr/0083](adr/0083-svg-number-lower-limit.md)（SVG の大きさの小さすぎる数）、[golem-pdf ADR 0014](golem-pdf/adr/0014-png-trns-transparency.md)（PNG の tRNS）",
      "",
      "### 主な原因",
      "",
      "- 画像のファイルが壊れている。",
      "- SVG の図版の大きさに、10^9 を超える数か、0 でなく絶対値が 10^-9 より小さい数を書いた。",
      "- インターレースの PNG を使った。",
      "- PNG の tRNS のチャンクが壊れている（二つある、アルファのある PNG に付いている、長さが合わない）か、tRNS を持つ PNG の画素が多すぎる。",
      "- 拡張子と中身の形式が食い違っている（中身が PDF の `.png` など）。",
      "- PDF の図版の書き出しの設定で、フォントを埋め込んでいないか、特色やレイヤーを残している。",
      "- PDF の図版が仕様に反している（ページの木の重なりなど）か、展開すると大きすぎる。",
      "",
      "### 直し方",
      "",
      "理由に合わせて図版を書き出し直す。",
      "PDF の図版なら、フォントを埋め込み、特色をプロセスカラーに直し、レイヤーを統合して書き出す。",
      "PNG はインターレースを外して書き出す。",
      "tRNS が理由なら、画像を編集するツールで PNG を書き出し直す。",
      "透過を残すなら、アルファのチャンネルを持つ PNG にしてもよい。",
      "画素が多すぎるなら、画像を小さくするか、アルファのチャンネルを持つ PNG に書き出す。",
      "ページの木や相互参照が理由なら、PDF を作り直す道具で書き出し直す。",
      "展開した大きさが理由なら、図版を必要なページだけの PDF に分けて書き出す。",
      "",
      "## G08011",
      "",
      "SVG の図版に扱えないものがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "SVG の図版に、Golem が PDF に描ける範囲の外の要素、属性、プロパティの値がある。",
      "範囲は [golem-pdf ADR 0009](golem-pdf/adr/0009-svg-figures.md) の表のとおりで、パス、基本の図形、変換、塗りと線、マーカーなどである。",
      "輪郭にしていない文字（`text`、`tspan`、`textPath` の要素と `@font-face`）も範囲の外である。",
      "絶対値が 10^9 を超える数と、0 でなく絶対値が 10^-9 より小さい数も範囲の外であり、その属性かプロパティの名前に `（読めない数）` を添える（[docs/adr/0041](adr/0041-svg-marker-and-number-limits.md)、[docs/adr/0083](adr/0083-svg-number-lower-limit.md)）。",
      "`marker` の循環は [G08016](#g08016)、深すぎる `marker` の入れ子は [G08017](#g08017)、`marker` が描く区間の延べ数の超過は [G08101](#g08101) であり、このコードには入れない。",
      "範囲の外のものを黙って無視せず、文書の順にすべて集め、最初のものの名前と位置（SVG のファイルの中の行と桁）を書き、残りの件数を添える。",
      "最初のものが文字なら、輪郭にして書き出すよう案内する。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "同じ `@figure` に G08016、G08017、G08101 も当たれば、このコードの後に続けて出す（[docs/adr/0084](adr/0084-svg-marker-drawn-segment-limit.md)）。",
      "dev と prod の両方でエラーである。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出し、HTML、EPUB、プレーンテキストでは出さない。",
      "HTML と EPUB は SVG を PDF の部分集合では検査せず、動的なコンテンツだけを [G08014](#g08014) で検査する。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `SVG の図版に扱えないものがあります: <パス>:<行>:<桁>（<名前>）ほか <n> 件`。文字なら `（<名前>: 文字は輪郭にして書き出してください）`。ほかになければ `ほか <n> 件` を書かない。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset` と `Golem.Typeset.Svg`、golem-svg の `Golem.Svg`）",
      "- ADR: [golem-pdf ADR 0009](golem-pdf/adr/0009-svg-figures.md)、[docs/adr/0041](adr/0041-svg-marker-and-number-limits.md)（読めない数）、[docs/adr/0054](adr/0054-svg-marker-cycle-and-depth-codes.md)（`marker` の循環と入れ子を G08016 と G08017 に分けた）、[docs/adr/0083](adr/0083-svg-number-lower-limit.md)（小さすぎる読めない数）",
      "",
      "### 主な原因",
      "",
      "- 文字を輪郭にせずに書き出した。",
      "- グラデーション、`use`、クリップ、フィルター、1 でない不透明度などを使った。",
      "- 子孫の結合子などの、扱わない CSS のセレクターを使った。",
      "- 地図のタイルなどの、大きな座標を使う図を書き出した。",
      "- 浮動小数点数の誤差（`6.123233995736766e-17` など）を、座標や行列の値として書き出した。",
      "",
      "### 直し方",
      "",
      "図の作成ツールで、文字を輪郭（アウトライン）にして書き出す。",
      "範囲の外の機能は、ツールの側で範囲の中に収めて書き出し直す。",
      "読めない数は、座標を縮めて書き出し直す。",
      "小さすぎる読めない数は、座標と行列の値を丸めて書き出し直す。",
      "SVG で収まらない図は、PDF で書き出して PDF の図版として置く。",
      "",
      "## G08013",
      "",
      "出力先がシンボリックリンクです",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`build`、または出力するターゲットのディレクトリ（`build/html`、`build/epub`、`build/text`、`build/pdf`）が、シンボリックリンクか、ディレクトリではないファイルである。",
      "`golem build` は出力の前にこれらのディレクトリを消すので、リンクの先のファイルを消さないように、どのターゲットも消さず、書かずに止める。",
      "該当するパスごとに一つ出す。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `出力先がシンボリックリンクかディレクトリではないので、消すことも書くこともしません: <パス>`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`）",
      "- ADR: [docs/adr/0035](adr/0035-security-hardening.md)",
      "",
      "### 主な原因",
      "",
      "- 原稿のリポジトリに、`build` という名前のシンボリックリンクが置かれている。",
      "- `build` を別のディスクに向けるために、シンボリックリンクにした。",
      "",
      "### 直し方",
      "",
      "リンクの先を確かめてから、`build` のリンク（またはファイル）を消す。",
      "出力を別の場所に置きたいときは、リンクにせず、ディレクトリをマウントする。",
      "",
      "## G08014",
      "",
      "SVG の図版に、HTML と EPUB に写せない動的なコンテンツがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "HTML と EPUB に写す SVG のファイルに、ブラウザーが SVG を文書として開いたときに動かすか読むもの（動的なコンテンツ）がある。",
      "写す SVG は、`@figure` の図版か `web` のうち、拡張子が `.svg` のものと、プラグインが作った SVG の図版（[docs/adr/0123](adr/0123-figures-from-plugins.md)）である。",
      "HTML と EPUB は SVG をそのまま写すので、読者が SVG を直接開けば、そのスクリプトが動く。",
      "拒むのは、`script` の要素、`foreignObject`、`iframe`、`embed`、`object`、`handler`、`listener` の要素、名前空間が XHTML の要素、名前が `on` で始まる属性、`#` で始まらない `href` と `xlink:href`、`href` かイベントの属性を書き換える `set` と `animate`（`attributeName` の接頭辞を問わない）、CSS の `@import` と `#` で始まらない `url()` と `image-set()`、対象が `xml-stylesheet` の処理命令である。",
      "CSS は、`style` の要素の中身と、すべての属性の値（`fill`、`filter` などの表現の属性や、`set` の `to` を含む）から探す（[docs/adr/0158](adr/0158-svg-external-references-beyond-href.md)）。",
      "XML として読めない SVG、UTF-8 でない SVG、内部サブセットを持つ `DOCTYPE` を持つ SVG も、中身を確かめられないのでこのコードにする。",
      "見つかったものを文書の順に集め、最初のものの名前と位置（SVG のファイルの中の行と桁）を書き、残りの件数を添える。",
      "`@figure` ごとに一つ出し、HTML と EPUB を書かない。",
      "PDF とプレーンテキストは書く。",
      "dev と prod の両方でエラーである。",
      "HTML か EPUB を組むとき（`golem build`）にだけ出す。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `SVG の図版に、HTML と EPUB に写せない動的なコンテンツがあります: <パス>:<行>:<桁>（<名前>）ほか <n> 件`。`<名前>` は要素の名前、属性の名前、`url()`、`@import`、`image-set()`、`xml-stylesheet` のどれかである。ほかになければ `ほか <n> 件` を書かない。読めない SVG なら `SVG の図版に、HTML と EPUB に写せない動的なコンテンツがあります: <パス>（<G08010 と同じ理由>）`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver` と `Golem.Driver.Svg`、golem-svg の `Golem.Svg.Active`）",
      "- ADR: [docs/adr/0039](adr/0039-svg-active-content-in-html-and-epub.md)、[docs/adr/0057](adr/0057-g0814-says-dynamic-content.md)（文言）、[docs/adr/0158](adr/0158-svg-external-references-beyond-href.md)（属性の値の CSS、処理命令、XHTML の要素）",
      "",
      "### 主な原因",
      "",
      "- Web 用に作ったインタラクティブな SVG を、図版にした。",
      "- 図の作成ツールが、外部の画像やフォントへの参照を書き出した。",
      "- 他人から受け取った原稿のリポジトリに、スクリプトを持つ SVG が置かれている。",
      "",
      "### 直し方",
      "",
      "図の作成ツールで、スクリプト、イベント、外部への参照を使わずに書き出し直す。",
      "外部の画像を参照する図は、画像を埋め込むか、`web` に PNG を置く。",
      "他人から受け取った SVG でこのコードが出たら、中身を確かめてから使う。",
      "",
      "## G08015",
      "",
      "図版の PDF のページの内容をつなぐと 256 MiB を超えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF の図版のページの `Contents` の配列のストリームを改行でつないだ内容が、256 MiB（2^28 バイト）を超える。",
      "Golem は、同じストリームを何度も名指しするページでも、そのストリームを出力に一度だけ書き、名指しの位置から呼ぶ。",
      "ただし、そのストリームが `q` と `Q` の外でグラフィックスの状態やテキストの状態を変える場合や、ストリームの境目で演算子の被演算子やテキストオブジェクトがまたがる場合は、呼び出しに置き換えると描画が変わるので、ストリームをつないで写す。",
      "つないだ内容は名指しの回数に比例して大きくなるので、上限を設けている。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出し、dev と prod の両方でエラーである。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `図版の PDF のページの内容をつなぐと 256 MiB を超えます: <パス>`",
      "- 段階とモジュール: 出力（golem-pdf の `Golem.Pdf.Import`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0051](adr/0051-reuse-repeated-pdf-content-streams.md)",
      "",
      "### 主な原因",
      "",
      "- 同じ内容のストリームを何度も名指しし、そのストリームが最上位で色や線の太さなどの状態を変えている PDF を、図版にした。",
      "",
      "### 直し方",
      "",
      "図版を作ったツールで PDF を書き出し直すか、図版を SVG か PNG にする。",
      "",
      "## G08016",
      "",
      "SVG の図版の marker が循環しています",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "SVG の図版の `marker` が、自分自身を、ほかの `marker` を経てでも置く。",
      "循環する `marker` は描き終わらない図なので、Golem の範囲によらず描かない。",
      "判定は `marker` の参照のグラフで行い、図の本体から届く `marker` のあいだの参照のうち、両端が同じ強連結成分にあるもの（自分自身への参照を含む）を循環の参照とする（[docs/adr/0054](adr/0054-svg-marker-cycle-and-depth-codes.md)）。",
      "循環の中の参照をすべて数える。",
      "図の本体が置かない `marker` は数えない。",
      "循環の参照を文書の順に集め、最初のものの位置（参照を持つ図形の、SVG のファイルの中の行と桁）と置く `marker` の id を書き、残りの件数を添える。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "同じ `@figure` に [G08011](#g08011) も当たれば、その後に、[G08017](#g08017) か [G08101](#g08101) も当たれば、その前に出す。",
      "dev と prod の両方でエラーである。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出す。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `SVG の図版の marker が循環しています: <パス>:<行>:<桁>（<id>）ほか <n> 件`。ほかになければ `ほか <n> 件` を書かない。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset` と `Golem.Typeset.Svg`、golem-svg の `Golem.Svg`）",
      "- ADR: [docs/adr/0054](adr/0054-svg-marker-cycle-and-depth-codes.md)",
      "",
      "### 主な原因",
      "",
      "- `marker` が自分自身を参照する SVG を生成した。",
      "- 二つ以上の `marker` が互いを置く SVG を生成した。",
      "",
      "### 直し方",
      "",
      "循環の中の参照を一つ切る。",
      "",
      "## G08017",
      "",
      "SVG の図版の marker の入れ子が 9 段を超えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "SVG の図版の `marker` の中の `marker` が、9 段を超えて入れ子になる。",
      "図が置く `marker` を 1 段目とし、描く手間を限るために 9 段まで描く。",
      "`marker` の深さは、循環の参照を除いた、図の本体からの最も長い参照の列の長さとする（[docs/adr/0054](adr/0054-svg-marker-cycle-and-depth-codes.md)）。",
      "深さ 9 以上の `marker` の中の参照を、すべて数える。",
      "循環の参照でもある参照は、[G08016](#g08016) として数える。",
      "参照を文書の順に集め、最初のものの位置（参照を持つ図形の、SVG のファイルの中の行と桁）と置く `marker` の id を書き、残りの件数を添える。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "同じ `@figure` に [G08011](#g08011) か G08016 も当たれば、その後に、[G08101](#g08101) も当たれば、その前に出す。",
      "dev と prod の両方でエラーである。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出す。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `SVG の図版の marker の入れ子が 9 段を超えます: <パス>:<行>:<桁>（<id>）ほか <n> 件`。ほかになければ `ほか <n> 件` を書かない。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset` と `Golem.Typeset.Svg`、golem-svg の `Golem.Svg`）",
      "- ADR: [docs/adr/0054](adr/0054-svg-marker-cycle-and-depth-codes.md)",
      "",
      "### 主な原因",
      "",
      "- `marker` を深く入れ子にした SVG を生成した。",
      "",
      "### 直し方",
      "",
      "`marker` の入れ子を 9 段までにする。",
      "",
      "## G08018",
      "",
      "フォントから CFF の表を取り出せません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "輪郭が CFF のフォントを PDF に埋め込むとき、埋め込むフォント（サブセット、作れなければ元のフォント）から `CFF ` の表を取り出せない。",
      "Golem は CFF のフォントを、CFF の表だけを `FontFile3` に `/Subtype /CIDFontType0C` で埋め込む。",
      "OpenType のままの埋め込み（`/Subtype /OpenType`）は、Chromium の PDF のビューアー（PDFium）が CID-keyed の CFF の和文を描かないので、代わりに使わない。",
      "PDF を書かない。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）に出し、dev と prod の両方でエラーとする。",
      "位置は `style.toml` の先頭（`style.toml` がなければマニフェストの先頭）である。",
      "フォントとして開けないファイル（輪郭の表がない、表の目録が壊れているなど）は、埋め込みより前に [G08003](#g08003) になる。",
      "このエラーは、開けたフォントの埋め込みの処理（サブセットや表の取り出し）が `CFF ` の表を失ったとき、OpenType のまま黙って埋め込むのを防ぐ。",
      "",
      "- メッセージ: `フォントから CFF の表を取り出せません: <パス>`。パスは `style.toml` に書いたとおりである。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset.FontProvider`、`Golem.Typeset`）",
      "- ADR: [golem-pdf ADR 0011](golem-pdf/adr/0011-cff-fontfile3-subtype.md)、[golem-pdf ADR 0013](golem-pdf/adr/0013-renamed-cff-table-is-g08003.md)",
      "",
      "### 主な原因",
      "",
      "- プロジェクトのフォントからは通常は起きない。埋め込みの処理の不具合を防ぐためのエラーである。`CFF ` の表の目録を壊したフォントも、CFF のフォントを含むフォントのコレクション（`.ttc`）も、試したかぎりでは G08018 にならなかった（[golem-pdf ADR 0013](golem-pdf/adr/0013-renamed-cff-table-is-g08003.md)）。",
      "",
      "### 直し方",
      "",
      "Golem の不具合として報告する。",
      "フォントの配布元から取り直したファイルで同じエラーが出るかを確かめると、報告の手がかりになる。",
      "",
      "## G08019",
      "",
      "CFF2 の輪郭のフォントは PDF に埋め込めません",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF が使う役割のフォントが、CFF2 の輪郭（`CFF2` の表）を持つ。",
      "CFF2 の輪郭は、可変の OpenType/CFF2 のフォントが使う。",
      "PDF の埋め込みフォントの入れ物は CFF2 の輪郭を受けず、TrueType の入れ物に入れた PDF はビューアーで字が描かれない。",
      "フォントのファイルごとに一つ出す。",
      "PDF を書かない。",
      "`golem build` の PDF、`golem check`、`golem preflight` が報告する。",
      "HTML と EPUB はフォントのファイルをそのまま同梱し、ブラウザーと読書環境が CFF2 を描くので、出さない。",
      "位置は `style.toml` の先頭（`style.toml` がなければマニフェストの先頭）である。",
      "",
      "- メッセージ: `CFF2 の輪郭のフォントは PDF に埋め込めません: <パス>。CFF か TrueType の輪郭のフォントを使ってください`。パスは `style.toml` に書いたとおりである。",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-typeset の `Golem.Typeset.FontProvider`、golem-font の `Golem.Font`）",
      "- ADR: [golem-font ADR 0003](golem-font/adr/0003-reject-cff2-fonts-in-pdf.md)",
      "",
      "### 主な原因",
      "",
      "- 可変フォントの `.otf`（たとえば `SourceSerif4Variable-Roman.otf`）を、本の役割に指定した。",
      "",
      "### 直し方",
      "",
      "同じ書体の、CFF の輪郭の版（静的な `.otf`）か TrueType の輪郭の版（`.ttf`）を使う。",
      "Source Serif 4 なら、`SourceSerif4-Regular.otf` か `SourceSerif4Variable-Roman.ttf` である。",
      "",
      "## G08020",
      "",
      "図版の PDF のページが二度以上名指すストリームのオブジェクトの番号が 2147483647 を超えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF の図版のページの `Contents` の配列が二度以上名指すストリームのオブジェクトの番号が、2147483647（2^31 − 1）を超える。",
      "Golem は、そのようなストリームを出力に一度だけ書き、名指しの位置から呼ぶ（[G08015](#g08015) を見る）。",
      "呼ぶ先の Form XObject を区別するキーは、ストリームの番号とページの番号から作り、2147483647 を超える番号ではキーが重なりうるので、取り込まない。",
      "ISO 32000-1 の Annex C が定めるオブジェクトの番号の最大は 8,388,607 であり、ふつうのツールが書き出す PDF では起きない。",
      "一度だけ名指すストリームと、呼び出しに置き換えられずにつなぐストリームは、番号によらず取り込む。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出し、dev と prod の両方でエラーである。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `図版の PDF のページが二度以上名指すストリームのオブジェクトの番号が 2147483647 を超えます: <パス>（<番号>）`",
      "- 段階とモジュール: 出力（golem-pdf の `Golem.Pdf.Import`、golem-typeset の `Golem.Typeset`）",
      "- ADR: [docs/adr/0259](adr/0259-record-what-the-audit-of-the-ci-release-and-tooling-adrs-found-on-2026-11-09.md)、[docs/adr/0247](adr/0247-keep-the-values-of-golem-wasm-independent-of-the-width-of-int.md)",
      "",
      "### 主な原因",
      "",
      "- オブジェクトの番号を 2147483647 より大きく付けるツールで書き出した PDF を、図版にした。",
      "",
      "### 直し方",
      "",
      "図版を作ったツールで PDF を書き出し直すか、図版を SVG か PNG にする。",
      "",
      "## G08100",
      "",
      "フォントにグリフのない文字があります",
      "",
      "- 重大度: dev では警告、prod ではエラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、シェイピングの結果のグリフ番号が 0（.notdef）になった文字がある。",
      "その文字は、PDF では空の箱（豆腐）などで表示される。",
      "原稿の文字、番号の文字列、柱、ノンブル、目次と索引の文字列、ルビ、圏点のすべてを対象とする。",
      "符号位置とフォントのファイルの組ごとに一つにまとめ、JSON の `facts` に `code-point`、`font`、`pdf-pages`、`count` を書く。",
      "位置は、その文字を含む行のブロックの位置である。",
      "dev では PDF を書き、終了コードを変えない。",
      "prod ではエラーなので PDF を書かず（前のビルドの PDF も消す）、終了コードは 1 になる。",
      "ほかのターゲットは書く。",
      "HTML、EPUB、プレーンテキストのターゲットと、`golem check`、LSP では出さない。",
      "`golem preflight` はビルドを prod で走らせるので、同じ文字を [G09002](#g09002) とともにエラーで出す。",
      "プリフライトの設定の `glyph-missing` は、このコードに当たらない。",
      "",
      "- メッセージ: `フォントにグリフのない文字です: U+<16 進数>「<文字>」（<フォントのパス>、PDF の <ページ> ページ目）`。結合文字と制御文字は「」の字を省く。ページは 10 ページまで並べ、残りを「ほか <n> ページ」とする",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`、golem-preflight の `Golem.Preflight`）",
      "- ADR: [docs/adr/0081](adr/0081-missing-glyphs-warn-in-build.md)",
      "",
      "### 主な原因",
      "",
      "- 本文のフォントが、その文字（外字、絵文字、私用領域の文字など）を持っていない。",
      "- 和文の文字を、欧文だけのフォントの役割で組んでいる。",
      "",
      "### 直し方",
      "",
      "その文字を持つフォントを `style.toml` の `[fonts]` の役割に書くか、原稿の文字を替える。",
      "",
      "## G08101",
      "",
      "SVG の図版の marker が描くパスの区間が 1000000 を超えます",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "SVG の図版の `marker` が描くパスの区間の延べ数が、1,000,000 を超える。",
      "区間は、図形とパスを変換した後のパスの区間（`MoveTo`、`LineTo`、`CurveTo`、`ClosePath`）の一つずつであり、円弧は変換した後の曲線の数で数える。",
      "一つの `marker` の区間の数は、その中身の図形の区間の数と、中身が置く `marker` の区間の数を置く回数だけ足したものとする。",
      "図版の延べ数は、図の本体が置く `marker` の区間の数を、置く回数だけ足したものとする（[docs/adr/0084](adr/0084-svg-marker-drawn-segment-limit.md)）。",
      "図の本体が直接描く区間は数えない。",
      "描かない参照（[G08016](#g08016) の循環の参照、[G08017](#g08017) の深すぎる参照、[G08011](#g08011) の範囲の外の要素の中の区間）も数えない。",
      "1,000,000 ちょうどは描く。",
      "入れ子の深さが 2 でも、置く回数が多ければこの上限に当たる。",
      "`@figure` ごとに一つ出し、PDF を書かない。",
      "同じ `@figure` に G08011、G08016、G08017 も当たれば、その後に出す。",
      "dev と prod の両方でエラーである。",
      "PDF を組むとき（`golem build` の PDF と `golem preflight`）にだけ出す。",
      "HTML、EPUB、プレーンテキストでは出さない。",
      "HTML と EPUB は SVG を写すだけで、`marker` を展開しないためである。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `SVG の図版の marker が描くパスの区間が 1000000 を超えます: <パス>（<n>）`。`<n>` は延べ数である。延べ数は図版の全体の数であり、一つの図形の位置に帰せないので、SVG のファイルの中の行と桁は書かない。",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset` と `Golem.Typeset.Svg`、golem-svg の `Golem.Svg`）",
      "- ADR: [docs/adr/0084](adr/0084-svg-marker-drawn-segment-limit.md)",
      "",
      "### 主な原因",
      "",
      "- 点の多い散布図の各点や、矢印の多い図の各線に、`marker` を置いた。",
      "- `marker` の中身に、さらに多くの `marker` を置く SVG を生成した。",
      "",
      "### 直し方",
      "",
      "メッセージの延べ数を見て、`marker` を置く回数か中身の区間を減らす。",
      "図の作成ツールで `marker` を図形に展開して書き出すか、PDF で書き出して PDF の図版として置く。",
      "展開した図形は図の本体の区間になるので、数えない。",
      "",
      "## G08102",
      "",
      "図版の画像の出力のパスが、プラグインの画像を置くフォルダー images/golem-plugin と重なります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "原稿の `@figure` の図版で、HTML と EPUB に写す画像（`web` があれば `web`、なければ図版そのもの）のパスが `images/golem-plugin/` の下にある。",
      "HTML と EPUB は、プラグインが作った画像を `images/golem-plugin/<SHA-256>.<拡張子>` に置く（[docs/adr/0123](adr/0123-figures-from-plugins.md)）。",
      "原稿の画像を同じ場所に写すと、プラグインの画像と取り違えるおそれがあるので、プラグインを使っていない本でも拒む。",
      "パスは `./` や `..` を正規化してから比べる。",
      "`@figure` ごとに一つ出し、HTML と EPUB を書かない。",
      "PDF とプレーンテキストは書く。",
      "HTML か EPUB を組むとき（`golem build`）にだけ出す。",
      "位置は、その `@figure` のブロックである。",
      "",
      "- メッセージ: `図版の画像の出力のパスが、プラグインの画像を置くフォルダー images/golem-plugin と重なります: <パス>`",
      "- 段階とモジュール: 出力（golem-driver の `Golem.Driver`）",
      "- ADR: [docs/adr/0123](adr/0123-figures-from-plugins.md)、[docs/adr/0137](adr/0137-plugin-image-folder-collision-g08102.md)",
      "",
      "### 主な原因",
      "",
      "- 画像を `images/golem-plugin/` というフォルダーに置いた。",
      "",
      "### 直し方",
      "",
      "画像を別のフォルダーに移し、`@figure` のパスを直す。",
      "",
      "## G08103",
      "",
      "フォントに OpenType の機能がありません",
      "",
      "- 重大度: dev では警告、prod ではエラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF をターゲットに含む `golem build` で、フォントの役割、段落スタイル、文字スタイルの `features` が有効にした機能を、その字を組む書体が持たない。",
      "書体が機能を持つとは、その書体の GSUB か GPOS の機能の一覧にそのタグがあることであり、用字系と言語系を問わない。",
      "同じ見た目の字の連なり（ラン）ごとに調べ、ランの字が使う書体（和文の字は和文の書体、欧文の字は欧文の書体）のどれもがその機能を持たないときに出す。",
      "和文と欧文が混じったランで、欧文の書体だけが機能を持つ場合は出さない。",
      "止める機能（値 0）と、Golem が足す機能（カーニングの方式、`proportional-metrics`、約物の打ち消し）には出さない。",
      "フォントのファイルと機能のタグの組ごとに一つにまとめ、フォントのパス、タグの順に並べる。",
      "JSON の `facts` に `font`、`feature`、`pdf-pages`（その機能のランが現れたページ）を書く。",
      "位置は、その機能を有効にした `style.toml` の値のうちファイルの中で最初のものであり、`@style-def` だけが書いた場合はその行である。",
      "書体が機能を持たなければ字形は変わらず、元の字形で組む。",
      "合成のスモールキャップは作らない。",
      "dev では PDF を書き、終了コードを変えない。",
      "prod ではエラーなので PDF を書かず（前のビルドの PDF も消す）、終了コードは 1 になる。",
      "ほかのターゲットは書く。",
      "HTML、EPUB、プレーンテキストのターゲットと、`golem check`、LSP では出さない。",
      "",
      "- メッセージ: `フォント <パス> に OpenType の機能 <tag> がありません`",
      "- 段階とモジュール: 出力（golem-typeset の `Golem.Typeset.Draw`、golem-driver の `Golem.Driver`）",
      "- ADR: [ADR 0268](adr/0268-opentype-features-on-character-styles.md)",
      "",
      "### 主な原因",
      "",
      "- スモールキャップを持たない書体の範囲に `smcp` を当てた。",
      "- 和文の書体だけで組む範囲に、欧文の書体の機能を当てた。",
      "- タグを書き誤った（`smpc` など）。",
      "",
      "### 直し方",
      "",
      "その機能を持つ書体を役割に書くか、その範囲に当てる文字スタイルから機能を消す。",
      "書体の機能は、フォントの仕様書か、フォントの編集ソフトの機能の一覧で確かめる。",
      "",
      "## G09001",
      "",
      "プリフライトの設定に誤りがあります",
      "",
      "- 重大度: エラー",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`golem preflight` が読むプリフライトの設定のファイルに誤りがある。",
      "ファイルは `--rules` で指したもの、指さなければプロジェクトのルートの `preflight.toml` である。",
      "ファイルが読めない（`--rules` の指すファイルがない、UTF-8 でない）、TOML として読めない、知らないキーがある、値の型や範囲が違う、のどれもがこのコードになる。",
      "`based-on` が `basic`、`print`、`none` のどれでもないとき、`image-resolution` の `error-below` が `warning-below` より大きいときも、このコードである。",
      "しきい値が負のときは [G02103](#g02103) である（[docs/adr/0102](adr/0102-natural-number-type.md)）。",
      "位置は、そのファイルの中の誤りの位置である。",
      "このコードが出ると、PDF を組まずに終える。",
      "重大度は、プリフライトの設定で変えられない。",
      "",
      "- メッセージ: TOML の誤りは TOML の読み込みの文言、ほかは `<キー> の値が正しくありません: <値>（<理由>）`。ファイルがなければ `プリフライトの設定のファイルがありません: <パス>`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight.Rules`、golem-driver の `Golem.Driver`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- キーの名前を書き違えた。",
      "- `severity` に `error`、`warning`、`off` のほかの値（`notice` など）を書いた。",
      "- 長さに `zw` を使った。",
      "- `--rules` のパスを書き違えた。",
      "",
      "### 直し方",
      "",
      "メッセージが示すキーを直す。",
      "書けるキーと値は、利用者のマニュアルの付録 D「preflight.toml のリファレンス」にある。",
      "",
      "## G09002",
      "",
      "フォントにグリフのない文字があります",
      "",
      "- 重大度: プリフライトの設定による（print の既定はエラー）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "シェイピングの結果のグリフ番号が 0（.notdef）になった文字がある。",
      "その文字は、PDF では空の箱などで表示される。",
      "原稿の文字、番号の文字列、柱、ノンブル、目次と索引の文字列のすべてを対象とする。",
      "符号位置とフォントのファイルの組ごとに一つにまとめ、JSON の `facts` に `code-point`、`font`、`pdf-pages`、`count` を書く。",
      "位置は、その文字を含む原稿のブロックの位置である。",
      "",
      "- メッセージ: `フォントにグリフのない文字です: U+<16 進数>「<文字>」（<フォントのパス>、PDF の <ページ> ページ目）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 本文のフォントが、その文字（外字、絵文字、私用領域の文字など）を持っていない。",
      "- 和文の文字を、欧文だけのフォントの役割で組んでいる。",
      "",
      "### 直し方",
      "",
      "その文字を持つフォントを `style.toml` の `[fonts]` の役割に書くか、原稿の文字を替える。",
      "検査を外すときは、プリフライトの設定の `[glyph-missing]` の `severity` を `off` にする。",
      "ただし、同じ文字は `golem build` が [G08100](#g08100) で報告し、`golem preflight` は prod で組むので、それがエラーになる。",
      "`glyph-missing` を `off` にしても、フォントにない文字があれば `golem preflight` は終了コード 1 で終わる。",
      "",
      "## G09003",
      "",
      "この設定では使えない形式のフォントです",
      "",
      "- 重大度: プリフライトの設定による（print の既定は off）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "PDF に埋め込んだフォントの形式が、プリフライトの設定の `[font-formats]` の `allowed` にない。",
      "形式は、`CFF ` の表を持つ OpenType を `cff`、`CFF2` の表を持つ OpenType を `cff2`、そのどちらでもないものを `truetype` とする（[golem-font ADR 0003](golem-font/adr/0003-reject-cff2-fonts-in-pdf.md)）。",
      "`cff2` のフォントは [G08019](#g08019) で PDF を組めないので、`allowed` に書けるが、この検査には現れない。",
      "フォントのファイルごとに一つ出す。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `この設定では使えない形式のフォントです: <パス>（<形式>）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 印刷所が、TrueType のフォントの入稿を受けない。",
      "",
      "### 直し方",
      "",
      "印刷所が受ける形式のフォントに替える。",
      "",
      "## G09004",
      "",
      "文字が小さすぎます",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "文字の大きさが、プリフライトの設定の `[type-size]` の `min-size` より小さい。",
      "`multi-ink-only` が真なら、色が二つ以上の版を使う文字だけを対象とする。",
      "版のずれで、小さな文字がにじむからである。",
      "ルビと圏点も文字に含める。",
      "大きさの出どころ、字の種類、色の組ごとに一つにまとめる。",
      "大きさの出どころは、その文字の大きさを決めた `style.toml` の定義であり、段落スタイルか文字スタイルか見出しの `size`、`[notes]` の `mark-size`、`[page.grid]` の `font-size`（どの定義も `size` を書かずに組んだ文字。柱とノンブルを含む）、`[hidden-folio]` の `size` のどれかである。",
      "`based-on` で `size` を引き継ぐスタイルの文字は、`size` を書いた引き継ぎ元の定義にまとめる。",
      "字の種類は、親文字、ルビ、圏点のどれかである。",
      "色は、スウォッチの名前である。",
      "スウォッチを持たない文字は一つの組とする。",
      "位置は、組の中で原稿の順に最初の文字を含む、原稿のテキストの位置である。",
      "原稿のテキストを持たない文字は、それを生んだ要素の位置とする。",
      "見出しの番号は見出し、目次の項目とリーダーはその見出し、リストの印はその段落、柱とノンブルは `style.toml` の先頭である。",
      "diagnostics は、位置の原稿の順に並べる。",
      "まとまりと位置は原稿と `style.toml` だけで決まり、改ページの位置では変わらない。",
      "改ページで変わるのは、メッセージのページの列だけである。",
      "diagnostic の事実（JSON の `facts`）に、大きさの出どころの `style.toml` のキー（`source`、`paragraph-styles.a.size` など）と字の種類（`part`、`base`、`ruby`、`kenten` のどれか）と、メッセージと同じ表記の大きさ（`size`、`1.41mm` など）を持つ。",
      "",
      "- メッセージ: `文字が小さすぎます: <大きさ>（<min-size> 未満、<出どころ>、色 <スウォッチの名前>、PDF の <ページ> ページ目）`（例: `文字が小さすぎます: 1.41mm（1.76mm 未満、段落スタイル a の size、色 rich、PDF の 1 ページ目）`）。`<出どころ>` は `段落スタイル a の size`、`文字スタイル b の size のルビ`、`[headings.1] の size の圏点`、`[notes] の mark-size`、`[page.grid] の font-size` のように書く。スウォッチを持たない文字の色は `なし` と書く",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)、[golem-cli ADR 0008](golem-cli/adr/0008-g0904-by-size-source-and-colour.md)（まとめの単位と位置）",
      "",
      "### 主な原因",
      "",
      "- 小さなルビや注を、複数の版を使う色（リッチブラックなど）で組んでいる。",
      "",
      "### 直し方",
      "",
      "メッセージが示す出どころの定義の `size` を大きくするか、色を一つの版（K だけなど）にする。",
      "",
      "## G09005",
      "",
      "図版を PDF に置けません",
      "",
      "- 重大度: プリフライトの設定による（print の既定はエラー）",
      "- 状態: 廃止",
      "",
      "### 意味",
      "",
      "廃止した。",
      "`@figure` の画像のファイルはあるが、JPEG か PNG として読めない図版を `golem preflight` が報告するコードだった。",
      "置けない図版は `golem build` と `golem preflight` のどちらでも [G08010](#g08010) のエラーになり、PDF を作れなければプリフライトは何も検査しないので、このコードは出なくなった。",
      "`preflight.toml` の `image-unplaceable` は、知らないキー（[G09001](#g09001)）になった。",
      "",
      "- メッセージ: `図版を PDF に置けません: <パス>（<理由>）`",
      "- 段階とモジュール: プリフライト（golem-preflight）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)（定めた）、[golem-pdf ADR 0008](golem-pdf/adr/0008-pdf-figures.md)（使わなくした）",
      "",
      "### 直し方",
      "",
      "[G08010](#g08010) を見る。",
      "`preflight.toml` に `image-unplaceable` を書いていれば消す。",
      "",
      "## G09006",
      "",
      "図版の実効の解像度が足りません",
      "",
      "- 重大度: プリフライトの設定による（print では 150ppi 未満がエラー、300ppi 未満が警告）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "画像の実効の解像度が、その画像の種類の `warning-below` か `error-below` を下回る。",
      "実効の解像度は、画素数を紙面に置いた大きさ（インチ）で割った値で、縦と横の小さいほうを、小数点以下を切り捨てて使う。",
      "画像の種類は、一ビットのグレーを `bitmap`、ほかのグレーを `gray`、RGB と CMYK とパレットを `color` とする。",
      "`error-below` を下回ればエラー、そうでなく `warning-below` を下回れば警告である。",
      "`@figure` ごとに一つ出し、JSON の `facts` に `ppi`、`limit`、`pixels`、`pdf-pages` を書く。",
      "",
      "- メッセージ: `図版の実効の解像度が足りません: <パス>（<ppi>ppi、<しきい値>ppi 未満、PDF の <ページ> ページ目）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 画面用の小さな画像を、紙面に大きく置いた。",
      "",
      "### 直し方",
      "",
      "画素数の多い画像に替えるか、紙面に置く大きさを小さくする。",
      "",
      "## G09007",
      "",
      "図版の実効の解像度が高すぎます",
      "",
      "- 重大度: プリフライトの設定による（print の既定は off）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "画像の実効の解像度が、その画像の種類の上限（`[image-resolution-max]` の `color-max`、`gray-max`、`bitmap-max`）を超える。",
      "PDF の大きさを抑えたい入稿先のための検査である。",
      "`@figure` ごとに一つ出す。",
      "",
      "- メッセージ: `図版の実効の解像度が高すぎます: <パス>（<ppi>ppi、<しきい値>ppi 超）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 撮影したままの大きな画像を、紙面に小さく置いた。",
      "",
      "### 直し方",
      "",
      "Golem は画像を縮小しないので、画像のファイルを小さく作り直す。",
      "",
      "## G09008",
      "",
      "この設定では使えない色空間の図版です",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "画像の色空間が、プリフライトの設定の `[image-color-space]` の `allowed` にない。",
      "色空間は、グレーを `gray`、RGB とパレットを `rgb`、CMYK を `cmyk` とする。",
      "PDF の図版では、ICC プロファイルの色空間を成分の数で `gray`（1）、`rgb`（3）、`cmyk`（4）とし、それ以外の成分の数のものを `icc`、Lab を `lab` とする。",
      "SVG の図版は `rgb` である。",
      "`@figure` ごとに一つ出す。",
      "PDF の図版で許さない色空間が二つ以上あれば、一つの diagnostic に `、` で並べる。",
      "",
      "- メッセージ: `この設定では使えない色空間の図版です: <パス>（<色空間>）。Golem は画像の色を変換しないので、CMYK に変換した画像に替えます`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- RGB の画像を使った。PDF/X-4 は RGB の画像を許すが、日本の印刷所の多くは CMYK の入稿を求める。",
      "",
      "### 直し方",
      "",
      "画像を、印刷所の求める条件で CMYK に変換して置き換える。",
      "",
      "## G09009",
      "",
      "出力インテントと違う ICC プロファイルを持つ CMYK の図版です",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "CMYK の画像が ICC プロファイルを埋め込んでおり、そのバイト列が `style.toml` の `[color] intent` のファイルのバイト列と違う。",
      "同じ特性の別のバージョンのプロファイルも、違うとみなす。",
      "`[color] intent` がなければ、何も出さない。",
      "`@figure` ごとに一つ出す。",
      "",
      "- メッセージ: `出力インテントと違う ICC プロファイルを持つ CMYK の図版です: <パス>。印刷の工程で色が変換されることがあります`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 出力インテントと違う条件で、画像を CMYK に変換した。",
      "",
      "### 直し方",
      "",
      "出力インテントと同じプロファイルで画像を変換し直す。",
      "",
      "## G09010",
      "",
      "塗り足しの幅が足りません",
      "",
      "- 重大度: プリフライトの設定による（print の既定はエラー、3mm 未満）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "`style.toml` の `[page] bleed` が、プリフライトの設定の `[bleed-size]` の `min` より小さい。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `塗り足しの幅が足りません: <bleed>（<min> 以上にします）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` の `[page]` に `bleed` を書いていない。`golem new` の雛形は書かない。",
      "",
      "### 直し方",
      "",
      "`style.toml` の `[page]` に `bleed = \"3mm\"` のように書く。",
      "",
      "## G09011",
      "",
      "図版が仕上がりの線の近くにあり、塗り足しまで届いていません",
      "",
      "- 重大度: プリフライトの設定による（print の既定はエラー、3mm）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "画像のどれかの辺が、仕上がりの線の内側に `[bleed-trim-hazard]` の `distance` 未満まで近づいているか、仕上がりの線を越えているが塗り足しの線まで届いていない。",
      "辺から仕上がりの線までの距離を、内側を正として e とすると、`-<bleed> < e < <distance>` のときである。",
      "仕上がりの線ちょうど（e = 0）の辺は、塗り足しが 0 でも対象とする。",
      "`@figure` ごとに一つ出す。",
      "v1 の図版は版面の中に置くので、版面の余白が `distance` 以上ある本では何も出さない。",
      "",
      "- メッセージ: `図版が仕上がりの線の近くにあり、塗り足しまで届いていません: <パス>（<辺>、仕上がりの線から <e>、PDF の <ページ> ページ目）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- 版面の余白が狭い。",
      "",
      "### 直し方",
      "",
      "版面の余白を広げるか、図版を小さくする。",
      "",
      "## G09012",
      "",
      "文字が仕上がりの線に近すぎます",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告、3mm）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "文字の行の範囲か線の範囲が、仕上がりの線から `[live-area]` の `distance` だけ内側の矩形（安全域）からはみ出す。",
      "文字の行の範囲は、行頭から行末まで、文字の大きさの高さである。",
      "トンボは対象にしない。",
      "要素の種類と辺の組ごとに一つにまとめるので、柱とノンブルは一つになる。",
      "位置は、本文の行では原稿のブロック、柱とノンブルでは `style.toml` の先頭である。",
      "",
      "- メッセージ: `文字が仕上がりの線に近すぎます: <要素>（<辺>、仕上がりの線から <距離>、PDF の <ページ> ページ目）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- `[masters]` の柱かノンブルの位置が、仕上がりの線に近い。",
      "- 版面の余白が狭い。",
      "- 段落スタイルか見出しの罫線を、`start-indent`、`end-indent`、`keep-in-column = false` で仕上がりの線の近くまで出した（[golem-driver ADR 0027](golem-driver/adr/0027-paragraph-style-rules.md)）。",
      "",
      "### 直し方",
      "",
      "版面の位置か、柱とノンブルの位置を仕上がりの線から離す。",
      "",
      "## G09013",
      "",
      "行が行長からはみ出しています",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "行分割が、行長に収められなかった行を残した。",
      "Knuth-Plass の行分割は、最後の段で行長を超える行を許す。",
      "描いた行ごとに一つ出す。",
      "量と位置は [G07105](#g07105) と同じである。",
      "量は、行の自然な幅から縮みの合計（字形の圧縮を含む）と行長を引いた量で、mm で小数点以下 2 桁に切り上げて書く。",
      "位置は、終わりが行長を超える最初の箱の最初の字で、その箱が原稿にない字なら、その行を含む原稿のブロックである。",
      "同じ行を、`golem build` と `golem preflight` が [G07105](#g07105) の警告で報告する。",
      "`golem preflight` では、二つが同じ位置、同じメッセージ、同じ事実で並ぶ。",
      "",
      "- メッセージ: `行が行長から <量> はみ出しています（PDF の <ページ> ページ目）`（例: `行が行長から 1.24mm はみ出しています（PDF の 1 ページ目）`）。事実の `overfull` は、メッセージと同じ表記の `<量>` である",
      "- 段階とモジュール: プリフライト（golem-typeset の `Golem.Typeset`、golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)、[docs/adr/0210](adr/0210-warn-overfull-lines-in-build.md)",
      "",
      "### 主な原因",
      "",
      "- 分割できない長い語や URL がある。",
      "- 行長が短い。",
      "",
      "### 直し方",
      "",
      "語を分けられるようにするか、文を書き換える。",
      "検査を外すときは、プリフライトの設定の `[overfull-lines]` の `severity` を `off` にする。",
      "ただし、同じ行は [G07105](#g07105) の警告で報告される。",
      "",
      "## G09014",
      "",
      "PDF/X-4 の要件を満たしていません",
      "",
      "- 重大度: プリフライトの設定による（print の既定はエラー）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "組んだ PDF が、[golem-pdf ADR 0002](golem-pdf/adr/0002-pdf-x-4.md) の PDF/X-4 の要件のどれかを満たさない。",
      "`Golem.Pdf.X4.verify` が、書く前の PDF のオブジェクトを検査する。",
      "項目は、PDF のバージョン、出力インテントとその ICC プロファイル、XMP の `GTS_PDFXVersion` と `Trapped`、各ページのボックス、ICC プロファイルのない RGB、暗号化と JavaScript と外部への参照である。",
      "フォントの埋め込みは、この検査でなく [G09019](#g09019) が出す（[docs/adr/0232](adr/0232-check-inks-fonts-figures-links-and-epubs-structurally-in-ci.md)）。",
      "`Golem.Pdf.X4.verify` はフォントの埋め込みも要件として返すが、golem-preflight の `pdf-x` の検査がそれを除く。",
      "したがって、`pdf-x` を `error`、`font-embedding` を `off` にした設定では、埋め込んでいないフォントは報告されない。",
      "JavaScript と外部への参照の禁止の名前は、`JavaScript`、`JS`、`URI`、`Launch`、`GoToR` である。",
      "ただし、ページの `/Annots` にあるリンクの注釈の `/A` が `/S /URI` のアクションであれば、その中の `URI` は数えない（[docs/adr/0182](adr/0182-external-links.md)）。",
      "ほかの位置の `URI` と、注釈の中のほかの禁止の名前は数える。",
      "要件ごとに一つ出す。",
      "JavaScript と外部への参照の詳細は、見つけた禁止の名前を、トレーラー、オブジェクトの順に見つけた順に一度ずつ並べる（[golem-pdf ADR 0012](golem-pdf/adr/0012-x4-forbidden-names-in-found-order.md)）。",
      "`style.toml` に `[color] intent` がないときは、続く要件の不足を並べず、一つにまとめる。",
      "位置は `style.toml` の先頭で、`style.toml` がなければ `manifest.toml` の先頭である。",
      "この検査は PDF/X-4 の適合の判定ではない（[golem-pdf ADR 0003](golem-pdf/adr/0003-pdf-x-4-validator.md)）。",
      "",
      "- メッセージ: `PDF/X-4 の要件を満たしていません: <要件>（<詳細>）`。出力インテントがなければ `PDF/X-4 の要件を満たしていません: 出力インテントがありません（style.toml の [color] に intent を書きます）`",
      "- 段階とモジュール: プリフライト（golem-pdf の `Golem.Pdf.X4`、golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- `style.toml` の `[color]` に `intent` を書いていない。`golem new` の雛形は書かない。",
      "",
      "### 直し方",
      "",
      "印刷所が指定する ICC プロファイルを置き、`style.toml` の `[color]` に `intent` を書く。",
      "入稿の前には、商用のプリフライトでも確かめる。",
      "",
      "## G09015",
      "",
      "色の総インキ量が多すぎます",
      "",
      "- 重大度: プリフライトの設定による（print の既定は警告、350%）",
      "- 状態: 使用中",
      "",
      "### 意味",
      "",
      "紙面で使った色（文字と地の色）のスウォッチの C、M、Y、K の値の和が、`[ink-coverage]` の `max` を超える。",
      "スウォッチごとに一つ出す。",
      "画像の画素は検査しない。",
      "位置は `style.toml` の先頭である。",
      "",
      "- メッセージ: `色の総インキ量が多すぎます: <スウォッチの名前>（<和>%、<max>% 超）`",
      "- 段階とモジュール: プリフライト（golem-preflight の `Golem.Preflight`）",
      "- ADR: [golem-cli ADR 0006](golem-cli/adr/0006-preflight.md)",
      "",
      "### 主な原因",
      "",
      "- リッチブラック（C、M、Y、K をすべて重ねた黒）のスウォッチを使った。",
      "",
      "### 直し方",
      "",
      "スウォッチの値を下げる。",
      "",
      "## G09016",
      "",
      "ページ数が指定の倍数ではありません",
      "",
      "- 重大度: プリフライトの設定による（print の既定は off）",
      "- 状態: 使用中",
      "",
