      "折の単位（16 ページなど）で台割を組む印刷所のための検査である。",
      "位置は `manifest.toml` の先頭である。",
      "",
      "- メッセージ: `ページ数が <multiple-of> の倍数ではありません: <ページ数>（あと <差> ページ）`",
