      "事実は `font`（記述子の `FontName`）である。",
      "Golem はすべてのフォントを埋め込み、取り込む PDF の図版の埋め込まないフォントも [G08010](#g08010) で拒むので、今の Golem の出力ではこの diagnostic は出ない。",
      "Golem の誤りでこの性質が崩れたときに、入稿の前に気づくための検査である。",
